pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual is "dead" if it's too small to hold even the smallest plausible item (<= 10)
    // or too small to hold the next item when that would have been a perfect fit.
    if post_residual < 10 {
        score += 60.0; // tiny unusable sliver — severe penalty
    } else if post_residual < item_size.min(20) {
        // gap smaller than the current item: likely wasted unless next item fits
        if next_item_size == 0 || post_residual < next_item_size {
            score += 25.0;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead coupling: reward residuals that exactly fit the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // keep room for the next item if possible
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize spreading); with few bins, be more permissive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bins have bad fits
    // (large post_residual relative to mean residual) or few fitting bins.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score = 20.0 + 70.0 * bad_fit * scarcity - 30.0 * pressure.min(2.0);
    }

    // Mild stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are dead weight.
    // Minimum plausible item size is 1; but treat "awkward" residuals harshly.
    if post_residual > 0 {
        // Perfect fit: zero dead space, huge reward.
        if post_residual == 0 {
            score -= 1000.0;
        }
        // Post-residual smaller than the smallest useful chunk -> near-total dead space.
        if post_residual < 10 {
            score += 40.0; // unusable sliver
        }
        // Dead space relative to capacity: quadratic penalty on wasted fraction.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 60.0 * waste_frac * waste_frac;
    } else {
        score -= 1000.0; // exact fill
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0; // chain-friendly residual
    } else if next_item_size > 0 && post_residual > 0 {
        score += 15.0; // next item cannot use leftover
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to remaining capacity pressure or open-bin residuals are messy.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base preference for reusing bins; new bin gets a moderate cost.
        let mut new_bin_score = 120.0;
        // Late in the stream, opening bins is less costly (fewer future items to fill them).
        new_bin_score -= 50.0 * progress;
        // If many bins are open with scattered residuals, a fresh bin is more attractive.
        new_bin_score -= (open_bins_count as f64).min(20.0) * 2.0;
        // If mean residual is small, open bins are nearly full -> new bin better.
        new_bin_score -= (mean_residual / bin_capacity as f64).max(0.0) * 60.0;
        // Large items prefer fresh bins to avoid fragmentation.
        new_bin_score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        score = new_bin_score;
    }

    // Open-bin count pressure: mildly discourage spreading across many bins.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (1..15) are nearly useless
    // for future items (sizes 10..80), so penalize them heavily.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }
    // Medium dead space (15..35) is mildly penalized.
    else if post_residual >= 15 && post_residual < 35 {
        score += 10.0 * (1.0 - (post_residual as f64 - 15.0) / 20.0);
    }
    // Comfortable residual (>=35) is rewarded: bin stays reusable.
    else if post_residual >= 35 {
        score -= 8.0;
    }

    // Perfect / near-perfect fits are excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving exactly enough room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 12.0; // leaves a sliver unusable by next item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills
    // (i.e., small post_residual) and discourage new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // New-bin candidate handling: only open a new bin when all open bins would
    // leave bad dead space or residuals are fragmented.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 * 5.0;
        let mean_frag = mean_residual; // average leftover in open bins
        // Opening a bin is attractive when existing residuals are small/fragmented
        // and can't host the item well.
        let attract = (mean_frag * 0.3) + open_pressure * 0.5;
        score = 70.0 - attract;
        // Late in the stream, closing out bins is better: make new bins costly.
        score += progress * 30.0;
        // If lookahead fits typical residual, keep new bin as fallback.
        if next_item_size > 0 && next_item_size <= mean_residual as u32 {
            score += 15.0;
        }
    }

    // Mild preference for bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual, non-linearly.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 40.0 * tight * tight;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space: post_residual too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_ratio = (next_item_size as f64 - post_residual as f64) / cap;
        score += 20.0 * waste_ratio * cap * (0.5 + progress);
    }

    // Reward perfect lookahead fit: next item exactly fills the new residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: acceptable early or when open bins are nearly full,
    // penalized when open bins have plenty of room (mean_residual high).
    if bin_residual == bin_capacity {
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        score += 15.0 + 30.0 * openness * (1.0 - progress);
        score -= 10.0 * progress;
    }

    // Mild penalty for spreading across many bins late in the stream.
    score += (open_bins_count as f64).ln() * 1.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: penalize wasted space nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 / bin_capacity as f64 * 20.0;
        } else {
            // Next item won't fit here; penalize leaving a large unusable-looking gap.
            score += (post_residual as f64 / bin_capacity as f64) * 15.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large relative to the item, or early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_waste = mean_residual - item_size as f64;
        // Penalize new bins generally; relax when open bins are nearly full.
        score += 30.0
            - avg_waste * 0.6
            - progress * 10.0
            - (open_bins_count as f64).powi(2) * 0.5;
        // If no open bin can even fit, opening is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late stream: prefer consolidating into existing bins.
        if progress > 0.8 {
            score += 20.0;
        }
    }

    // Mild preference for filling fuller bins among many candidates.
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Crowding: with many open bins, discourage spreading items thinly.
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Tightness reward: non-linear, progress-coupled (sharpened)
    score += pr_norm * (0.8 + 2.4 * progress * progress) * cap * 0.5;

    // Dead-space avoidance with deeper dead zone
    let dead_zone = (1.0 - pr_norm).powi(7);
    score += dead_zone * (10.0 + 46.0 * progress);

    // Exact / near-exact fit: overwhelming rewards
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 280.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead chain logic (strengthened, from best lineage)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 680.0;
        } else if (next_item_size as u64) < (post_residual as u64) {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 330.0 } else if fill > 0.6 { 200.0 } else { 125.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual { score -= 36.0; }
            if after == 0 { score -= 65.0; }
            else if after <= 4 { score -= 45.0; }
            else if after <= 10 && next_item_size >= after { score -= 28.0; }
            if after as f64 > mean_residual * 2.0 { score += 28.0; }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 6.0 { 0.55 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Dead-space penalty: residual too small for the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_ratio = (next_item_size as f64 - pr) / cap;
        score += 20.0 * waste_ratio * cap * (0.5 + progress);
    }

    // Tight-fit reward relative to item size
    if post_residual > 0 && post_residual >= item_size {
        let tight_i = item_size as f64 / pr;
        if tight_i > 0.92 { score -= 55.0 * tight_i; }
        else if tight_i > 0.75 { score -= 20.0 * tight_i; }
        else { score -= 8.0 * tight_i; }
    }

    // Last-chance consolidation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 32.0 + 22.0 * progress;
    }

    // New-bin candidate handling (simplified per best lineage)
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 12.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 32.0;
        }
    }

    // Spread / fragmentation penalties
    score += 0.5 * open_bins_count as f64 * pr_norm;
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);
    score += 0.3 * (mean_residual - pr);

    // Penalize leaving residuals that no typical item can use
    if post_residual > 0 {
        let usable = (post_residual as f64 / mean_residual.max(1.0)).min(2.0);
        if usable < 1.0 {
            score += 18.0 * (1.0 - usable) * (0.5 + progress);
        }
    }

    // Reward bins whose post-residual matches next item within a small window
    if next_item_size > 0 && post_residual >= next_item_size {
        let d = (post_residual - next_item_size) as f64;
        if d <= 12.0 {
            score -= 20.0 * (1.0 - d / 12.0) * (0.6 + 0.4 * progress);
        }
    }

    // Reward keeping post-residual aligned with mean residual (harmonized leftovers)
    if post_residual > 0 && mean_residual > 0.0 {
        let align = 1.0 - ((pr - mean_residual).abs() / cap).min(1.0);
        score -= 6.0 * align * (0.4 + 0.6 * progress);
    }

    // Late-stream consolidation — prefer filling nearly-full bins more aggressively
    if progress > 0.7 && post_residual > 0 {
        let squeeze = 1.0 - pr_norm;
        score -= 14.0 * squeeze * squeeze * (progress - 0.7) / 0.3;
    }

    // MUTATION: two-step lookahead synergy — reward bins where item + next item
    // nearly exhaust the bin, combining fine-grained residual fitting with lookahead
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = pr - next_item_size as f64;
        let two_fill = (item_size as f64 + next_item_size as f64) / (bin_residual as f64);
        if two_fill > 0.97 {
            score -= 95.0 * (two_fill - 0.97) / 0.03;
        } else if after2 <= 6.0 {
            score -= 38.0 * (1.0 - after2 / 6.0);
        }
        // Penalize residuals that can fit neither the next item nor a small item
        if after2 > 0.0 && after2 < 8.0 {
            score += 10.0 * (8.0 - after2) / 8.0 * (0.5 + progress);
        }
    }

    // MUTATION: mid-stream tightening of fragmentation tolerance
    if progress > 0.35 && progress <= 0.7 && post_residual > 0 {
        let squeeze = 1.0 - pr_norm;
        score -= 8.0 * squeeze * squeeze * (progress - 0.35) / 0.35;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += 2.0 * open_bins_count as f64;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 60.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score = 0.0; // forced new bin
        } else if post_residual >= 40.0 {
            // opening a fresh bin keeps room for large future items
            score -= 25.0;
        }
        // penalize opening new bins when existing bins fit reasonably
        if mean_residual > item_size as f64 * 1.5 {
            score += 30.0;
        }
    }

    // Lookahead: favor bins that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Tightness reward: non-linear, progress-coupled
    score += pr_norm * (0.8 + 2.1 * progress * progress) * cap * 0.5;

    // Dead-space avoidance with sharpened dead zone
    let dead_zone = (1.0 - pr_norm).powi(6);
    score += dead_zone * (10.0 + 42.0 * progress);

    // Exact / near-exact fit: overwhelming rewards
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead chain logic
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if (next_item_size as u64) < (post_residual as u64) {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual { score -= 32.0; }
            if after == 0 { score -= 60.0; }
            else if after <= 4 { score -= 42.0; }
            else if after <= 10 && next_item_size >= after { score -= 25.0; }
            if after as f64 > mean_residual * 2.0 { score += 25.0; }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Dead-space penalty: residual too small for the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_ratio = (next_item_size as f64 - pr) / cap;
        score += 20.0 * waste_ratio * cap * (0.5 + progress);
    }

    // Tight-fit reward relative to item size
    if post_residual > 0 && post_residual >= item_size {
        let tight_i = item_size as f64 / pr;
        if tight_i > 0.92 { score -= 50.0 * tight_i; }
        else if tight_i > 0.75 { score -= 20.0 * tight_i; }
        else { score -= 8.0 * tight_i; }
    }

    // Last-chance consolidation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0 + 30.0 * openness * (1.0 - progress);
        }
        score -= 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // Penalize opening new bins when open bins already fit
        if fitting_bins_count >= 2 {
            score += 18.0 * (fitting_bins_count as f64).min(4.0);
        }
    }

    // Spread / fragmentation penalties
    score += (open_bins_count as f64).ln() * 1.5 * progress;
    score += 0.5 * open_bins_count as f64 * pr_norm;
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);
    score += 0.3 * (mean_residual - pr);

    // NEW: penalize leaving residuals that no typical item can use
    if post_residual > 0 {
        let usable = (post_residual as f64 / mean_residual.max(1.0)).min(2.0);
        if usable < 1.0 {
            score += 18.0 * (1.0 - usable) * (0.5 + progress);
        }
    }

    // NEW: reward bins whose post-residual matches next item within a small window
    if next_item_size > 0 && post_residual >= next_item_size {
        let d = (post_residual - next_item_size) as f64;
        if d <= 12.0 {
            score -= 20.0 * (1.0 - d / 12.0) * (0.6 + 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Tightness reward, non-linear, progress-coupled (borrowed from best).
    score += pr_norm * (0.8 + 2.1 * progress * progress) * cap * 0.5;

    // Sharpened dead-zone avoidance.
    let dead_zone = (1.0 - pr_norm).powi(6);
    score += dead_zone * (10.0 + 42.0 * progress);

    // Exact / near-exact fit bonuses.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead chain logic.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if (next_item_size as u64) < (post_residual as u64) {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
                score -= 32.0;
            }
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Dead-space penalty: residual too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_ratio = (next_item_size as f64 - pr) / cap;
        score += 20.0 * waste_ratio * cap * (0.5 + progress);
    }

    // Tightness relative to the placed item.
    if post_residual > 0 && post_residual >= item_size {
        let tight_i = item_size as f64 / pr;
        if tight_i > 0.92 {
            score -= 50.0 * tight_i;
        } else if tight_i > 0.75 {
            score -= 20.0 * tight_i;
        } else {
            score -= 8.0 * tight_i;
        }
    }

    // Last-chance consolidation: stronger than parent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0 + 30.0 * openness * (1.0 - progress);
        }
        score -= 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // Penalize opening new bins when many open bins already fit the item.
        if fitting_bins_count >= 2 {
            score += 18.0 * (fitting_bins_count as f64).min(4.0);
        }
    }

    // Spread / fragmentation penalties.
    score += (open_bins_count as f64).ln() * 1.5 * progress;
    score += 0.5 * open_bins_count as f64 * pr_norm;
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits exactly into the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // Next item fits: mildly good, prefer larger leftover for it.
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item does NOT fit in leftover: penalize wasted potential,
            // worse when leftover is close to next item size (near miss).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 2.0 * gap;
            }
        }
        // If next item could fit in this bin NOW but not after placing item,
        // consider deferring (penalize blocking a larger follow-up).
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 30.0;
        }
    }

    // Relative to mean residual: bins with residuals close to item size are
    // tight fits; penalize bins far below mean residual (already crowded).
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.3 * (-dev);
    } else {
        score -= 0.1 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is bad
    // and we're early in the stream (room to consolidate later).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = if post_residual > 0 { 1.0 } else { 0.0 };
        let penalty = 60.0 + 120.0 * progress - 40.0 * bad_fit;
        score += penalty;
        // Opening new bins is cheaper when few are open.
        score -= 3.0 * open_bins_count as f64;
    }

    // Small stream-position modulation: late in stream, tighten up (avoid waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min size 1, but practically < ~12 are near-useless) are heavily penalized.
    let dead_zone = 12.0;
    if post_residual >= 1 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }

    // Perfect / near-perfect fits are rewarded strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward tight fits relative to residual (waste fraction penalty).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 10.0;

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage scattering across many bins,
    // but a brand-new bin (residual == capacity) escapes this pressure.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 0.8;
    } else {
        // New bin: mildly discourage unless it avoids dead space.
        score += 3.0 + 0.3 * (open_bins_count as f64);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item would leave yet another dead gap, penalize.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && (gap as f64) < dead_zone {
            score += (dead_zone - gap as f64) * 2.0;
        }
    }

    // Slight preference early in stream to keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    // Mean residual coupling: prefer bins deviating below mean residual
    // (i.e., fuller bins) when many bins are open.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05 * (open_bins_count as f64).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

