    score += pr_norm * (0.8 + 2.4 * progress * progress) * cap * 0.5;

    // Dead-space avoidance with sharpened dead zone
    let dead_zone = (1.0 - pr_norm).powi(7);
    score += dead_zone * (10.0 + 46.0 * progress);

    // Exact / near-exact fit: overwhelming rewards
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 280.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead chain logic
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 680.0;
        } else if (next_item_size as u64) < (post_residual as u64) {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 330.0 } else if fill > 0.6 { 200.0 } else { 125.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual { score -= 36.0; }
            if after == 0 { score -= 65.0; }
            else if after <= 4 { score -= 45.0; }
            else if after <= 10 && next_item_size >= after { score -= 28.0; }
            if after as f64 > mean_residual * 2.0 { score += 28.0; }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 6.0 { 0.55 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Dead-space penalty: residual too small for the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_ratio = (next_item_size as f64 - pr) / cap;
        score += 20.0 * waste_ratio * cap * (0.5 + progress);
    }

    // Tight-fit reward relative to item size
    if post_residual > 0 && post_residual >= item_size {
        let tight_i = item_size as f64 / pr;
        if tight_i > 0.92 { score -= 55.0 * tight_i; }
        else if tight_i > 0.75 { score -= 20.0 * tight_i; }
        else { score -= 8.0 * tight_i; }
    }

    // Last-chance consolidation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
