        // Penalize opening new bins when open bins already fit
        if fitting_bins_count >= 2 {
            score += 18.0 * (fitting_bins_count as f64).min(4.0);
        }
        // Stronger penalty when many open bins have ample room
        let roomy = open_bins_count as f64 * (mean_residual / cap).max(0.0);
        if roomy > 1.5 {
            score += 22.0 * (roomy - 1.5).min(3.0);
        }
    }

    // Spread / fragmentation penalties
    score += (open_bins_count as f64).ln() * 1.5 * progress;
    score += 0.5 * open_bins_count as f64 * pr_norm;
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);
    score += 0.3 * (mean_residual - pr);

    // Penalize leaving residuals that no typical item can use
    if post_residual > 0 {
        let usable = (post_residual as f64 / mean_residual.max(1.0)).min(2.0);
        if usable < 1.0 {
            score += 18.0 * (1.0 - usable) * (0.5 + progress);
        }
    }

    // Reward bins whose post-residual matches next item within a small window
    if next_item_size > 0 && post_residual >= next_item_size {
        let d = (post_residual - next_item_size) as f64;
        if d <= 12.0 {
            score -= 20.0 * (1.0 - d / 12.0) * (0.6 + 0.4 * progress);
        }
    }

    // Reward keeping post-residual aligned with mean residual (harmonized leftovers)
    if post_residual > 0 && mean_residual > 0.0 {
        let align = 1.0 - ((pr - mean_residual).abs() / cap).min(1.0);
        score -= 6.0 * align * (0.4 + 0.6 * progress);
    }

    // Late-stream consolidation — prefer filling nearly-full bins more aggressively
    if progress > 0.7 && post_residual > 0 {
        let squeeze = 1.0 - pr_norm;
        score -= 14.0 * squeeze * squeeze * (progress - 0.7) / 0.3;
    }

    // Two-step lookahead synergy — reward bins where item + next item nearly exhaust the bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = pr - next_item_size as f64;
        let two_fill = (item_size as f64 + next_item_size as f64) / (bin_residual as f64);
        if two_fill > 0.97 {
            score -= 90.0 * (two_fill - 0.97) / 0.03;
        } else if after2 <= 6.0 {
            score -= 35.0 * (1.0 - after2 / 6.0);
        }
        // Penalize residuals that can fit neither the next item nor a small item
        if after2 > 0.0 && after2 < 8.0 {
            score += 10.0 * (8.0 - after2) / 8.0 * (0.5 + progress);
        }
    }

    // Mid-stream tightening of fragmentation tolerance
    if progress > 0.35 && progress <= 0.7 && post_residual > 0 {
        let squeeze = 1.0 - pr_norm;
        score -= 8.0 * squeeze * squeeze * (progress - 0.35) / 0.35;
    }

    // MUTATION: residual-shape targeting — reward leaving residuals that are
    // multiples of a "harmonic" chunk so future mid-size items tile them cleanly
    if post_residual > 0 && mean_residual > 1.0 {
        let ratio = pr / mean_residual;
        let nearest = ratio.round();
        let dev = (ratio - nearest).abs();
        if nearest >= 1.0 && dev < 0.12 {
            score -= 22.0 * (1.0 - dev / 0.12) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION: pair-completion lookahead — strongly prefer bins where the next
    // item's leftover can still host a third small item (triple-fill chains)
    if next_item_size > 0 && post_residual > next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after >= 1.0 && after <= mean_residual * 0.6 {
            score -= 18.0 * (1.0 - after / (mean_residual * 0.6)) * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post residual, but weighted non-linearly by stream progress.
    // Early on, prefer filling bins tightly (minimize post_residual strongly);
    // later, tolerate larger residuals slightly to keep flexibility.
    let residual_weight = 1.0 + 0.6 * progress * progress;
    let mut score = pr * residual_weight;

    // Non-linear penalty for small dead space: residuals close to zero are great,
    // residuals in a mid "awkward" band are penalized super-linearly.
    let norm_pr = pr / cap;
    let awkwardness = norm_pr * (1.0 - norm_pr); // peaks mid-band
    score += 12.0 * awkwardness * awkwardness * cap / 100.0;

    // Reward tight fits (small post_residual) with a convex bonus.
    score -= 8.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins whose residual deviates badly from the mean residual
    // (favor balanced residual portfolios), with smooth quadratic coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // reward; if post_residual is too small for the next item, mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack).powi(2);
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Smooth preference for keeping fewer open bins when residuals are large.
    let openness = open_bins_count as f64;
    score += 0.05 * openness * norm_pr;

    // New-bin candidate: make an empty bin attractive only when the item is large
    // relative to capacity or many bins are already open and residuals are low.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        let attractiveness = fill_frac * fill_frac * (1.0 + 0.5 * progress);
        score = 30.0 - 25.0 * attractiveness - 0.3 * openness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // penalty grows with how much next item overshoots this residual
            let over = (next_item_size as f64 - post_residual as f64).min(bin_capacity as f64);
            score += 0.3 * over;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins: prefer consolidating into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose residual is near the item need
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a bin, modulated by how poor existing fits are
        let poor_fit = if post_residual == bin_capacity as u32 { 0.0 } else { 0.0 };
        score = 55.0 + poor_fit;
        // early in stream with few bins, opening is cheaper
        score -= 15.0 * (1.0 - progress);
        // if many bins already fit the item, discourage opening a new one
        score += 8.0 * (fitting_bins_count as f64).min(5.0);
        // if the item is large and next item is also large, new bin is reasonable
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the new residual -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits into the post residual: moderate reward, scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 50.0 + 150.0 * tightness;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space, worse when leftover is small.
        let dead = post_residual as f64;
