    // Compare against mean residual: prefer bins whose residual usage stays balanced,
    // but allow tightening a large-residual bin.
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Opening a new bin is attractive only when no open bin gives a good fit
    // (post residual too small relative to typical items) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_fit_possible = next_item_size > 0 && post_residual >= next_item_size;
        if !good_fit_possible {
            score -= 120.0;
        }
        // Mild preference for consolidating early, spreading late.
        score += 30.0 * (1.0 - progress) - 30.0 * progress;
    }

    // Reward closing bins almost completely (waste < 10).
    if post_residual < 10 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    } else if post_residual >= 90 {
        // Wasteful placement into a nearly full bin leaves a big empty bin? No:
        // large post_residual means item was small; slight penalty for squandering space.
        score += 30.0;
    }

    // 2-step lookahead: strongly favor bins whose leftover exactly hosts the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Good if next item fits with little slack left over.
            score -= 150.0 - slack * 1.5;
        } else {
            // Next item won't fit here: penalize by the shortfall, worse when
            // this bin is the only fitting option (last-chance bin).
            let shortfall = (next_item_size - post_residual) as f64;
            let last_chance = if fitting_bins_count <= 1 { 2.5 } else { 1.0 };
            score += shortfall * last_chance;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer filling bins with below-average residual (tight bins first).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.8;
    } else {
        score += (res - mean_residual) * 0.4;
    }

    // Last-chance bonus: if this is the only bin that fits, use it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a decent fit (i.e., item is large relative to all residuals). Make the
    // empty bin moderately attractive so it wins only when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // But if the item is huge relative to mean residual, opening is preferable.
        let pressure = item_size as f64 / (mean_residual.max(1.0));
        if pressure > 0.85 {
            score -= (pressure - 0.85) * 700.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Mild penalty for many open bins: encourage closing bins out.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: if the next item exactly fills the post residual,
    // heavily reward this bin (it becomes perfectly packed after two placements).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Post residual can still host the next item: reward proportionally
            // to how tightly the next item fits (smaller leftover after next).
            let after_next = post_residual - next_item_size;
            score -= 50.0 + (after_next as f64).min(30.0);
        } else {
            // Next item cannot fit in leftover: penalize dead space that is
            // "almost" big enough (wasted potential), scaled by proximity.
            let gap = (next_item_size - post_residual) as f64;
            score += 20.0 + gap * 0.5;
        }
    }

    // Penalize tiny unusable residuals (dead space) more aggressively.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward packing into bins with below-average residual (tight bins),
    // keeping large-residual bins flexible for future items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Late in the stream, consolidate: favor filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0;

    // Slight preference for bins that end with residual divisible by common
    // item granularity (heuristic for future fit).
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual;
    let pr = post as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Harmonic class of post residual (inherited from parent, retuned)
    let class = post / 10;
    let rem = post % 10;

    if post == 0 {
        score -= 1000.0;
    } else if post <= 3 {
        score -= 280.0;
    } else if post <= 10 {
        score += 25.0 + (10 - post) as f64;
    } else {
        let harmonic_bonus = if rem == 0 {
            40.0 + class as f64 * 3.0
        } else if rem <= 3 {
            20.0
        } else {
            -5.0
        };
        score -= harmonic_bonus;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 680.0; // perfect chain
        } else if next_item_size < post {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 330.0 } else if fill > 0.6 { 200.0 } else { 125.0 };
            score -= chain_bonus * fill;
            let after = post - next_item_size;
            if after == 0 {
                score -= 65.0;
            } else if after <= 4 {
                score -= 45.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 28.0;
            }
            if after as f64 <= mean_residual {
                score -= 36.0;
            } else if after as f64 > mean_residual * 2.0 {
                score += 28.0;
            }
        } else {
            let gap = (next_item_size - post) as f64;
            let near_miss_scale = if gap <= 6.0 { 0.55 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tightness of the current placement
    if post > 0 && post >= item_size {
        let tight = item_size as f64 / pr;
        if tight > 0.92 {
            score -= 55.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Bin dies after this item: penalize if next item is large
    if next_item_size > 0 && post < next_item_size {
        score += (next_item_size - post) as f64 * 0.4;
    }

    // Last-chance logic
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 32.0 + 22.0 * progress;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if open_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 12.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 32.0;
        }
        if item_size as f64 >= 0.85 * cap {
            score -= 40.0 * (item_size as f64 / cap - 0.85);
        }
    } else {
        if fitting_bins_count > 1 {
            score += fitting_bins_count as f64 * 0.5;
        }
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Balance and fragmentation modulation
    score += 0.3 * (mean_residual - pr);
    score += 0.5 * open_bins_count as f64 * pr_norm;
    let frag = pr / (pr + item_size as f64);
    score += 12.0 * frag * frag * (0.5 + progress);

    // Progress modulation: keep flexibility early, close bins late
    score += (1.0 - progress) * pr * 0.15;
    score -= progress * (post == 0) as i32 as f64 * 50.0;

    // Near-miss dead-zone trap
    if post > 0 && post < 12 && next_item_size > post && (next_item_size - post) <= 4 {
        score += 18.0;
    }

    // Modulo coupling on harmonics
    if item_size % 10 == 0 && post % 10 == 0 && post > 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
