}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        // Small dead space is nearly as bad as unusable space.
        score += 50.0 - (post_residual as f64) * 5.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: reward proportionally to how well it matches.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.3;
        } else {
            // Next item blocked: penalize, worse when residual is just barely too small.
            let gap = (next_item_size - post_residual) as f64;
            score += 20.0 + gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins that are already more filled than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a poor fit,
    // but reward using it when the fit is good.
    if fitting_bins_count == 1 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio > 0.8 {
            score -= 30.0;
        } else {
            score += 15.0;
        }
    }

    // New-bin candidate: only attractive when no open bin offers a good home.
    if bin_residual == bin_capacity {
        // Neutral baseline; slightly penalized so good existing fits win.
        score += 10.0;
        // If item is large relative to capacity and mean residual is small, opening is fine.
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Prefer denser packing overall: reward larger item share of the residual.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how it divides into capacity fractions
    let pr = post_residual as i64;
    let cap = bin_capacity as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic classes of post_residual modulo 10 / 20 / 25
    let m10 = pr % 10;
    let m20 = pr % 20;
    let m25 = pr % 25;
    score += (m10 as f64) * 0.8;
    score += (m20 as f64) * 0.5;
    score += (m25 as f64) * 0.4;

    // Integer-division thresholds: residuals that are clean fractions of capacity are reusable
    let frac = post_residual as f64 / cap;
    if (frac * 4.0).round() as i64 * 25 == pr {
        score -= 25.0; // exactly 1/4, 1/2, 3/4 of capacity
    } else if (frac * 2.0).round() as i64 * 50 == pr {
        score -= 20.0;
    }

    // Lookahead: does next item fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.6;
        } else {
            // next item won't fit here; penalize large leftover
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
        // harmonic class match between next item and post residual
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize unless current bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        score += 90.0;
        if open_bins_count == 0 {
            score -= 200.0;
        }
        if mean_residual < item_size as f64 * 1.2 && open_bins_count > 0 {
            score -= 100.0; // open bins too tight, new bin is good
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 40.0; // large item coming, fresh bin useful
        }
    }

    // Tightness reward: prefer bins whose current residual is close to item size
    let tightness = (bin_residual - item_size) as f64 / cap;
    score -= (1.0 - tightness) * 10.0;

    // Mild preference to spread load when many bins are open
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Stream progression: early on be conservative about opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let fit_ratio = item / cap;                       // how much of the bin the item consumes
    let tightness = 1.0 - (post / cap);               // 1.0 = perfect fill now

    // Base: reward consuming more of the bin's space (lower score for tight fits)
    let mut score = cap - post;

    // Strong reward for very tight fits (post_residual near 0)
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: small leftovers that are hard to reuse later.
    // A leftover is "dead" if it's small relative to typical item sizes.
    let dead_threshold = 20.0;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 2.5;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // reward leaving space usable by the next item, scaled by how well it fits
            let lookahead_fit = 1.0 - ((post - nxt) / cap);
            score -= 25.0 * lookahead_fit;
        } else {
            // next item won't fit in the leftover: mild penalty for wasting the gap
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the current item
    // is large and would leave a very awkward residual everywhere else.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = cap * 0.9;
        // if no open bin fits (fitting_bins_count==0 means only the new bin was called),
        // this is mandatory: make it attractive
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // large items pack well into fresh bins early in the stream
        if fit_ratio > 0.6 {
            score -= 30.0 * (fit_ratio - 0.6);
        }
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    // to avoid spreading waste; few open bins -> slightly favor new bins for flexibility.
    let residual_pressure = mean_residual / cap;      // 0..1 average wasted space
    if bin_residual != bin_capacity {
        score -= 15.0 * residual_pressure;            // reward using bins with lots of space
        // mild penalty for spreading across many bins when residuals are already small
        if residual_pressure < 0.15 {
            score += 0.5 * open_bins_count as f64;
        }
    }

    // Non-linear coupling: combine tightness with stream progress — late in the stream,
    // tightness matters more (endgame packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * tightness * progress;

    // Small tie-breaker: prefer bins with residual close to item (exact-ish fits)
    let slack = (bin_residual as f64 - item).abs();
    score += slack * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits after this placement: reward tight-but-compatible fits.
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 - slack * 0.5;
    } else if next_item_size > 0 {
        // Next item would NOT fit here afterwards: penalize dead space creation,
        // scaled by how close we came to fitting it (near misses are worst).
        let miss = (next_item_size - post_residual) as f64;
        score += 50.0 + 200.0 / (1.0 + miss);
