    // Reward tight fits relative to residual (small post_residual is good unless lookahead fails).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 40.0;

    // Penalize bins whose residual is far from the mean residual (outlier dead space).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Baseline neutral score; becomes attractive only if open bins score worse
        // due to dead-space penalties. Add mild preference against early bin explosion.
        score += open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can perfectly host the next item too if item leaves exact room.
            if item_size + next_item_size == bin_capacity {
                score -= 900.0;
            }
        }
    }

    // Stream progression: as the stream ends, consolidate into existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
