    score -= (bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual context: penalize bins far below mean residual (fragmentation)
    score += 0.3 * (mean_residual - pr).abs() * (0.5 + progress);

