    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress) - (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize dead space
    // that is too small to be useful for typical items.
    let dead_zone = 12.0;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            // Perfect chaining: post_residual exactly matches next item.
            let chain_quality = 1.0 - ((post_residual as f64 - next) / bin_capacity as f64);
            score -= 15.0 * chain_quality;
        } else {
            // Next item won't fit here: penalize proportionally to the shortfall,
            // but soften if the shortfall is small (near-miss).
            let shortfall = next - post_residual as f64;
            score += shortfall * 0.35;
        }
        // Bonus for two perfect fits in a row (item + next exactly filling bin).
        if post_residual as f64 + next as f64 == bin_capacity as f64 {
            score -= 20.0;
        }
    } else {
        // Last item: just minimize waste.
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: bins with residual above mean are "loose";
    // prefer packing into them when post_residual stays near the mean.
    let mean_gap = post_residual as f64 - mean_residual;
    score += mean_gap * 0.15;

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when the
    // item is large relative to typical residuals or next item is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = open_bins_count as f64 * 0.4;
        let next_pull = if next_item_size > 0 { next_item_size as f64 / 100.0 } else { 0.0 };
        // Default penalty so fresh bins are used sparingly.
        score += 25.0 - pressure - next_pull * 10.0 - progress * 5.0;
        // Large items pair well with fresh bins.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream.
    score += open_bins_count as f64 * 0.05;

    score
}

