    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: leftover space too small to hold anything useful.
    let min_useful = 10u32.min(bin_capacity);
    if post_residual < min_useful {
        score += 25.0; // sealed bin is fine, but only if it was a tight fit
        score -= 20.0 * fit_ratio; // ...which the tight fit already rewarded
    } else {
        // Penalize residuals that are awkwardly small (likely dead space later).
        let awkward = (min_useful as f64 / post_residual as f64).min(1.0);
        score += 8.0 * awkward;
    }

    // Lookahead: reward if the next item fits into post_residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64));
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't chain here; mild penalty proportional to how close we were.
        score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it expensive unless the stream is early or all fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 + 40.0
            - 30.0 * (1.0 - progress) // slightly cheaper to open early? no: early = more bins later, so cheaper later
            + 10.0 * progress; // penalize opening new bins late in the stream
        // If no bin fits at all (this is the only option), it's effectively forced;
        // fitting_bins_count counts fitting open bins, new bin isn't counted.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Global state coupling: when open bins are on average full-ish, prefer
    // consolidating into the emptiest sensible bin (low residual = full bin).
    score += 0.05 * (mean_residual - post_residual as f64);

    // Slight preference for bins with residuals close to item_size (perfect packing).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits mildly; late in the stream, punish residual waste quadratically.
    let tight = pr / cap; // normalized waste
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score += 12.0 * tight * tight * (1.0 + 2.0 * progress_poly);

    // Reward using a bin whose residual is nearly consumed (smooth, non-piecewise).
    let fill = 1.0 - tight;
    score -= 8.0 * fill * fill * fill * (0.5 + progress_poly);

    // Last-chance bonus: only one fitting bin, smooth exponential urgency.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress_poly);
    }

    // Penalize opening new bins when many bins are open and mean residual is large.
    let new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if new_bin {
        score += 10.0 + 0.5 * open_bins_count as f64 + 5.0 * (mean_residual / cap);
    } else {
        // Favor bins whose residual is close to the item (smooth closeness term).
        let closeness = 1.0 - ((bin_residual as f64 - item_size as f64) / cap).abs();
        score -= 4.0 * closeness * closeness;
    }

    // Lookahead: bonus if post_residual can still accommodate the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        return -10000.0;
    }

    // Harmonic class of the leftover: classify post_residual by capacity fractions.
    // Residuals in the "large half" class (post_residual > cap/2) are valuable;
    // tiny residuals are dead space unless they match common small-item sizes.
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction of leftover

    // Reward leaving a residual that is a "harmonic" usable size (multiples of 25, 20, 10)
    if post_residual % 25 == 0 { score -= 12.0; }
    else if post_residual % 20 == 0 { score -= 8.0; }
    else if post_residual % 10 == 0 { score -= 4.0; }
    else { score += 6.0; } // odd leftovers are harder to fill

    // Dead-space penalty: leftover too small to hold anything meaningful (< 10)
    // (item sizes >= 10 in classic regime; be safe for >=1 regime too).
    if post_residual < 10 {
        score += 40.0;
    } else if frac < 0.1 {
        score += 15.0;
    }

    // Reward leaving room for the next item exactly (lookahead harmony).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // leftover can host next item: good, scaled by how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot fit here: mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer fuller bins overall (tight packing): reward small residual fraction.
    score += 10.0 * (1.0 - (bin_residual as f64) / cap) * (1.0 - (bin_residual as f64) / cap);

    // Discourage spreading across many bins when mean residual is already high:
    // favor bins below mean residual (fill the emptier-relative bins less).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - frac);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; waived if item is huge relative to
        // current residuals (poor fit everywhere) via fitting_bins_count signal.
        let mut new_bin_cost = 20.0;
        if fitting_bins_count == 0 {
            new_bin_cost = -50.0; // no open bin fits: must open
        } else if fitting_bins_count == 1 {
            new_bin_cost = 35.0; // one last-chance bin exists: keep it closed
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item size (1) are wasted, but gaps below a practical threshold are
    // nearly unusable. Penalize hard when post_residual falls in the
    // "dead zone" (small but nonzero).
    let dead_threshold = 6u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 6.0;
    }

    // Perfect fit bonus: strong reward for filling the bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements where the next item exactly fills the resulting gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Penalize if the leftover gap cannot host the lookahead item but is
    // large enough to be "tempting" dead space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // still usable, mild reward
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // gap unusable by lookahead: mild penalty
    }

    // Tightness reward: prefer bins where the item occupies a large fraction
    // of the residual (best-fit style, but sharpened).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill_ratio;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few open bins, opening a new bin is cheaper.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins already open
        // (want to use them), reward when few bins exist.
        score += 25.0 + 6.0 * bin_pressure;
        // But if this bin is the last chance and fit is poor, opening new
        // bin may be better: handled implicitly by penalties below.
    } else {
        // Existing bin: reward using it, more so when many bins are open.
        score -= 4.0 * bin_pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        // If the fit leaves a dead gap, soften the bonus.
        if post_residual > 0 && post_residual < dead_threshold {
            score += 25.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is "drier" than average; prefer filling dry bins to keep a pool of
    // large residuals available for big future items.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Stream progression: early on, be liberal about opening bins (future
    // items unknown); late in the stream, pack tightly to close bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Dead space: post_residual too small for the next item (wasted gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Bonus if the bin can also host the next item after this placement (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * ((post_residual as f64 - next_item_size as f64) / bin_capacity as f64).min(0.2);
    }

    // Relative fullness vs mean residual: prefer bins tighter than average.
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.3 * open_bins_count as f64;
        // But if this is a very poor fit anywhere (huge item), new bin is fine.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Late in the stream: consolidate aggressively, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 60.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * next_tightness;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Dead space that the next item cannot use: penalize.
        score += 8.0 * (post_residual as f64) / bin_capacity as f64;
    }

    // New-bin candidate handling: only prefer a fresh bin when fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin; the penalty shrinks when few bins fit or
        // mean residual across open bins is large (poor existing fits).
        let poor_fits = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let spread = (mean_residual - post_residual as f64).abs();
        score += 70.0 - 45.0 * poor_fits - 0.15 * mean_residual.min(200.0) - 0.05 * spread;
        // Late in the stream, slightly discourage new bins more (fewer chances to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Reward using existing bins, especially when many are open.
        score -= 6.0 + 0.5 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild preference for bins with smaller residual overall (best-fit flavor).
    score += 0.05 * (post_residual as f64 - mean_residual);

    // Small bonus for keeping residual aligned to common small item sizes (divisibility).
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Polynomial coupling of post_residual with stream progress:
    // early on, be lenient about residuals; late, penalize them more
    let progress_coupling = pr_norm * (0.8 + 2.0 * progress * progress);
    score += progress_coupling * cap * 0.5;

    // Penalize residuals that are too small to fit a typical future item,
    // smoothly scaled by progress
    let dead_zone = (1.0 - pr_norm).powi(6);
    score += dead_zone * (10.0 + 40.0 * progress);

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - fit_margin) * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Favor bins tighter than the mean residual (smooth pull)
    score += 0.3 * (mean_residual - pr);

    // Mild encouragement to consolidate into fewer bins
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: prefer it only when residuals are all poor
    if bin_residual == bin_capacity {
        score = 20.0 + 30.0 * progress + 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: strongly reward small post_residual.
    score += 40.0 * (post_residual as f64 / bin_capacity as f64).powi(2);

    // Harmonic class of post_residual: modulo-10 buckets.
    // Residuals that are "dead" (small, hard to reuse) are penalized;
    // residuals in useful harmonic classes (e.g. multiples of 5 or 10) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let r10 = pr % 10;
        if r10 == 0 {
            score -= 12.0; // perfectly reusable class
        } else if r10 == 5 {
            score -= 6.0;
        } else if r10 <= 3 {
            score += 10.0; // tiny dead space, likely unusable
        }
    }

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item exactly fits the post_residual,
    // this is a chained harmonic match — reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if pr >= next_item_size {
            // next item fits: residual class after chaining stays useful
            let chained = pr - next_item_size;
            if chained % 10 == 0 || chained == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use the leftover dead space
            score += 0.05 * (pr - next_item_size) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new bin
    // (i.e. reward using this bin) unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 5 {
            score -= 20.0;
        }
    }

    // New-bin candidate (empty bin): prefer it only when the item is large
    // relative to capacity (poor fit anywhere) or late in the stream.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score = 55.0 - 40.0 * frac;
        if next_item_size > 0 && next_item_size >= pr.max(item_size) {
            // next item is large; fresh bin useful
            score -= 10.0;
        }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
    }

    // Mild penalty for proliferating open bins when mean residual is already high.
    if bin_residual != bin_capacity && mean_residual > 30.0 && open_bins_count > 3 {
        score += 0.02 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to be useful later are heavily penalized.
    // Treat residual < 10 (or < min plausible future item) as dead space.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual as f64);
    }
    // Non-linear penalty for medium-small gaps that few future items can fill.
    if post_residual > 0 && post_residual < item_size {
        score += 8.0;
    }

    // --- Reward tight fits (small post_residual relative to item) ---
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 15.0 * tightness;

    // --- Perfect fit bonus ---
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // If multiple bins fit, prefer ones with tighter residual.
    if fitting_bins_count > 1 {
        score -= 5.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // --- Open bins pressure: discourage spreading across many bins ---
    score += 2.0 * open_bins_count as f64;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive: penalize, but less when current bin
        // fit would leave a very awkward gap or few bins fit elsewhere.
        let mut new_bin_penalty = 30.0;
        if post_residual > 0 && (post_residual as f64) < dead_threshold {
            new_bin_penalty -= 20.0; // current placement creates dead space -> new bin ok
        }
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 10.0;
        }
        // Late in the stream, prefer consolidating.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty += 20.0 * progress;
        score += new_bin_penalty;
    }

    // --- Lookahead coupling: if next item fits exactly in post_residual, big reward ---
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; slightly penalize leaving a gap nothing uses
        score += 3.0;
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins) ---
    score -= 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Reward proportionally to how well the next item fills leftover space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * fill;
        } else {
            // Next item cannot use this residual: penalize wasted space, worse for large residuals.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    let dev = post_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
