pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space: residual that cannot fit even the smallest plausible item.
        let dead = (post_residual as f64 / 10.0).floor();
        score += 6.0 * dead * dead;
    }

    // Lookahead: reward if post_residual can exactly or well fit the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; few open bins: mild encouragement to reuse.
    if open_bins_count > 3 {
        score += 0.6 * (open_bins_count as f64 - 3.0);
    } else {
        score -= 1.5 * (3.0 - open_bins_count as f64);
    }

    // Global residual state: if this bin's residual is far below mean, it's a good
    // candidate to fill (it is the "odd" bin); if above mean, mild penalty.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well or stream is early
    // and residual everywhere is fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { (mean_residual / bin_capacity as f64) } else { 1.0 };
        if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits; new bin is necessary anyway
        } else if fragmentation < 0.35 || progress < 0.15 {
            score -= 15.0; // open bins are too full/fragmented or stream just started
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64; // discourage opening when reuse is viable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
