    // Small dead residuals that the next item cannot use
    if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
        score += 20.0;
    }

    // Last-chance bin
    if fitting_bins_count <= 1 && post_residual >= item_size {
        score -= 60.0;
    }

    // Tightness reward
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.9 {
            score -= 45.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        }
    }

    // Exact repeat fit
    if post_residual > 0 && post_residual == item_size {
        score -= 35.0;
    }

    // Overshoot penalty: leftover far above mean after next item
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size
        && (post_residual - next_item_size) as f64 > mean_residual * 2.0 {
        score += 25.0;
    }

    // Large items prefer emptiest bins; small items prefer tight bins
    if item_class >= 2 {
        score -= 0.3 * bin_residual as f64;
    } else {
        score += 0.1 * bin_residual as f64;
    }

    // New-bin candidate economics (borrowed from best)
    if is_new_bin {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 60.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 80.0;
        }
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    } else {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev.abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if it cannot plausibly hold a small item (min size 1,
    // but gaps under ~12 are statistically wasted in typical streams).
    if post_residual > 0 {
        if post_residual < 12 {
            // Tiny slivers: almost certainly dead space.
            score += 30.0 + (12 - post_residual) as f64 * 4.0;
        } else if post_residual < 25 {
            // Marginal zone: risky gap, moderate penalty scaled by risk.
            score += 10.0 + (25 - post_residual) as f64 * 1.5;
        } else {
            // Usable gap: reward keeping flexibility, mildly.
            score -= 5.0;
        }
    } else {
        // Perfect fit: zero waste, strongest reward.
        score -= 40.0;
    }

    // Reward filling bins that are close to full (tight packing pressure).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than leaving many partially-filled bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item would fit in the post-residual, keep this bin
    // attractive; if next item is large and post_residual is a bad gap, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (post_residual as f64) * 0.3;
        }
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins
    // are crowded (mean residual low) or many bins are already struggling.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
        if mean_residual > 30.0 {
            score -= 20.0; // open bins have room, discourage new bin
        }
    }

    // Progression: later in the stream, waste matters relatively more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += score.abs() * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: bin's post-residual exactly matches next item (perfect chain fit)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight lookahead matching: reward closeness of post_residual to next_item_size
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        if post_residual == next_item_size {
            score -= 40.0; // exact 2-step chain completion bonus
        }
        // Penalize leaving a gap that neither fits the next item well nor is reusable
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0; // dead space blocking the lookahead item
        }
    } else {
        score += 10.0; // last item: less reason to preserve chains
    }

    // Reward placing into tight bins relative to fleet mean residual
    let residual_f = bin_residual as f64;
    score -= 0.5 * (mean_residual - residual_f).max(0.0);
    score += 0.3 * (residual_f - mean_residual).max(0.0);

    // Last-chance bonus: only one bin fits the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is poor
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = 130.0 + 0.6 * waste - 20.0 * (item_size as f64 / bin_capacity as f64);
        // If next item is huge and current bins are fragmented, opening is more acceptable
        if next_item_size >= 70 {
            score -= 10.0;
        }
    }

    // Slight late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward near-perfect fits: exact fills are free, small dead space is costly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Penalize creating dead space that no plausible future item can use.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead synergy: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = (next_item_size as f64 / post.max(1.0)).min(1.0);
        score -= 10.0 + 15.0 * tightness;
    }
    // If next item almost fits (misses by <= 10), slight penalty for wasting the gap.
    else if next_item_size > post_residual && next_item_size - post_residual.min(next_item_size - 1) <= 10 && post_residual > 0 && next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should lose unless open bins are fragmented
    // or the fit into open bins would be terrible. Penalize new bin mildly by default.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if open bins are nearly full on average, a fresh bin is attractive.
        let mean_fill = 1.0 - (mean_residual / cap).max(0.0).min(1.0);
        score -= 30.0 * mean_fill;
        // Late in the stream, avoid proliferating bins with tiny leftovers elsewhere.
        if progress > 0.8 {
            score -= 5.0 * progress;
        }
    }

    // Prefer placing into bins whose residual is close to the mean (balance preservation),
    // penalize draining already-small residuals into unusable slivers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference to fill larger-residual bins early, keep small residuals as buffers.
    if bin_residual < bin_capacity {
        let rel = bin_residual as f64 / cap;
        score -= 10.0 * rel * rel;
    }

    // Crowding effect: many open bins -> prefer consolidating into existing ones.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / cap;

    // Non-linear penalty on unusable residual: dead space grows quadratically,
    // amplified as the stream progresses (late dead space is costlier).
    let dead_penalty = pr * pr * (1.0 + 1.5 * progress);
    score += 20.0 * dead_penalty;

    // Reward near-perfect fits via smooth exponential coupling
    let fit_reward = (-6.0 * pr).exp();
    score -= 12.0 * fit_reward * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates from the mean residual
    // (prefer balanced packing), with smooth coupling to post state.
    let dev = (post_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // Lookahead: reward bins whose post-residual can accommodate the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            score -= 6.0 * (1.0 - (nx / cap));
        } else {
            score += 3.0 * ((nx - post_residual as f64) / cap);
        }
    }

    // New-bin candidate: empty bin should only win when no good fit exists.
    // Smoothly discourage it more as progress increases (consolidation phase).
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Perfect / near-perfect fills: huge rewards
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 250.0;
    } else if post_residual == item_size {
        score -= 35.0;
    }

    // Poor-fit penalty: residual smaller than the item
    if post_residual < item_size && post_residual > 4 {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste;
    }

    // Tightness reward when residual >= item
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.9 {
            score -= 45.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        }
    }

    // Lookahead chain bonus for next item
    if next_item_size > 0 {
        if next_item_size as u64 == post_residual as u64 {
            score -= 620.0;
        } else if next_item_size as u64 <= post_residual as u64 {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 300.0 } else if fill > 0.6 { 190.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
                score -= 30.0;
            }
            if after <= 4 {
                score -= 40.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tiny dead residual that cannot fit the next item
    if post_residual > 0 && post_residual < 12 && next_item_size as u64 > post_residual as u64 {
        score += 20.0;
    }

    // Last-chance bin: strong reward
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize leaving a residual far above mean*2 when next item still fits
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size
        && (post_residual - next_item_size) as f64 > mean_residual * 2.0 {
        score += 25.0;
    }

    // Smooth mean-residual pull and consolidation term (weakened)
    score += 0.15 * (mean_residual - pr);
    score += 0.3 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: prefer only when item is large relative to capacity
    // or residuals are generally poor
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 60.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: integer-division thresholds.
    // Small dead space (< 10) is nearly worthless -> heavy penalty.
    if post_residual < 10 {
        score -= 60.0; // perfect fill, reward strongly
    } else if post_residual < 20 {
        score -= 8.0;
    } else if post_residual < 30 {
        score -= 2.0;
    } else if post_residual < 50 {
        score += 5.0;
    } else {
        score += 12.0;
    }

    // Modulo-arithmetic class: leftovers that are multiples of 10 are
    // "harmonic" with typical item sizes and easier to fill later.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 3.0;
    }
    // Odd, awkward leftovers (mod 10 in 1..=3) are hard to reuse.
    let r = post_residual % 10;
    if r >= 1 && r <= 3 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement is excellent (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // reward grows when the next item leaves a small remainder too
            let rem2 = post_residual - next_item_size;
            score -= 10.0 - (rem2 as f64) * 0.15;
        } else {
            // next item won't fit here: mildly penalize hoarding space
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin is bad if plenty of open bins already fit the item.
        if fitting_bins_count >= 2 {
            score += 30.0 + 5.0 * (fitting_bins_count as f64 - 2.0);
        } else if fitting_bins_count == 1 {
            // prefer reusing the single fitting bin over a fresh bin
            score += 8.0;
        } else {
            // no open bin fits: new bin is mandatory, neutral score
            score += 0.0;
        }
        // early in the stream, allow more bins to be opened (spreads load)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for bins with residuals below the running mean
    // (concentrate filling where space is already tight).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Tie-break: mildly prefer bins whose residual is close to the item
    // (best-fit flavor) via quadratic coupling.
    let tightness = (bin_residual - item_size) as f64;
    score += 0.01 * tightness * tight_step(tightness);

    score
}

#[inline]
fn tight_step(t: f64) -> f64 {
    // smooth step: 0 for large residuals, 1 for tight fits
    if t < 20.0 { 1.0 } else if t < 60.0 { 0.5 } else { 0.0 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals too small for typical future items
    // are "dead space". Penalize heavily in the unusable gap zone.
    let dead_zone_low = 1.0f64;
    let dead_zone_high = 12.0f64;
    let pr = post_residual as f64;
    if pr >= dead_zone_low && pr <= dead_zone_high {
        // Dead space: harsh penalty, worse the deeper into the zone
        score += 60.0 * (1.0 - (pr - dead_zone_low) / (dead_zone_high - dead_zone_low));
    } else if pr == 0.0 {
        // Perfect fit: reward strongly
        score -= 40.0;
    }

    // If next item can fit exactly into the post residual, reward (chain fit)
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item can't use this residual: potential dead space
        score += 6.0;
    }

    // Open bins pressure: discourage spreading across many bins when
    // a reasonable fit exists; encourage closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: penalize if this bin's residual is far below mean
    // (creating an outlier small gap), reward if it stays near the packable mean.
    let res_diff = mean_residual - (bin_residual as f64);
    if res_diff > 0.0 {
        score += 0.3 * res_diff;
    } else {
        score -= 0.15 * (-res_diff);
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    // (high post_residual for empty bin is natural, so add pressure to open
    // new bins only when open bins are congested).
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
