    // Tightness reward: item fills most of the bin's residual
    if post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.9 {
            score -= 45.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        }
    }

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 620.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 300.0 } else if fill > 0.6 { 190.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
