        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 { score -= 85.0 ; }
        if fitting_bins_count > 2 { score += 10.0 ; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 { score -= 30.0 ; }
        if post_residual > 0 {
            let dev = ((pr - mean_residual) / (mean_residual + 1.0)) . abs () ;
            score += 8.0 * dev ;
        }
    }
    if post_residual > 0 && post_residual == item_size { score -= 35.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions (1/8ths).
    let cap = bin_capacity as f64;
    let eighth = cap / 8.0;
    let post = post_residual as f64;
    let class = (post / eighth).floor(); // 0..8

    // Reward tight fits: post_residual landing in low harmonic classes.
    score -= (8.0 - class) * 4.0;

    // Dead-space penalty: residuals in awkward mid-range classes (3..6 eighths)
    // are hard to fill later; penalize them.
    if class >= 3.0 && class <= 6.0 {
        score += 6.0;
    }

    // Perfect fit reward: post_residual exactly divisible by small harmonic units.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 5.0;
        } else if post_residual % 5 == 0 {
            score -= 2.5;
        }
    } else {
        score -= 10.0; // bin closed perfectly
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 12.0;
        } else if next_post <= 10 {
            score -= 8.0;
        } else {
            score -= 3.0;
        }
        // If next item would NOT fit here, check whether it fits worse elsewhere:
        // if this is the only fitting bin, prefer using it rather than opening new bin.
        if next_item_size > post_residual && fitting_bins_count == 1 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor filling it to avoid waste.
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // New-bin candidate handling: empty bin gets a mild handicap so we prefer
    // reusing open bins, but handicap shrinks late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 9.0 - 4.0 * progress;
    }

    // Prefer bins below mean residual (fill emptier bins first keeps
    // tighter bins available for small items).
    let diff = post - mean_residual;
    if diff > 0.0 {
        score += (diff / cap) * 8.0;
    } else {
        score -= (-diff / cap) * 4.0;
    }

    // Open-bin count pressure: many open bins -> consolidate.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Polynomial coupling of post_residual with stream progress
    let progress_coupling = pr_norm * (0.8 + 2.1 * progress * progress);
    score += progress_coupling * cap * 0.5;

    // Dead-zone shaping
    let dead_zone = (1.0 - pr_norm).powi(6);
    score += dead_zone * (10.0 + 42.0 * progress);

    // Perfect / near-perfect fills are extremely valuable
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        // Residual too small for the current item: penalize by wasted fraction
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead: chain the next item into this bin when possible
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
                score -= 32.0;
            }
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        } else {
            // Near-miss lookahead penalty, scaled by gap size
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Reward bins that accept the current item tightly
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.92 {
            score -= 50.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Favor bins tighter than the mean residual (smooth pull)
    score += 0.3 * (mean_residual - pr);

    // Mild encouragement to consolidate into fewer bins
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation pressure grows with progress
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // New-bin candidate: open a fresh bin only for large items or when
    // existing residuals are poor for the upcoming demand
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (smallest item = 1, but tiny slivers < ~10 are
    // practically dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
