    // new bins; when few bins are open, opening a new bin is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * (1.0 - progress));
    score += pressure * 6.0;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
