        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        score -= 0.2 * mean_residual.max(0.0);
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling to progress.
    let mut score = pr
        + 60.0 * norm_pr * norm_pr * (0.5 + progress)
        + 40.0 * norm_pr * norm_pr * norm_pr * (1.0 + progress);

    // Penalize new-bin candidate smoothly, stronger early in the stream.
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    score += is_new_bin * (30.0 + 120.0 * (1.0 - progress));

    // Reward using the last fitting bin (avoid opening a new bin needlessly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 50.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if nxt <= pr {
            score -= 20.0 * (1.0 - gap / cap) * (0.5 + progress);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for placing into bins far from the mean residual (fragmentation control).
    score += 0.1 * (pr - mean_residual).abs() * (1.0 - progress);

    // Slight preference for tighter bins overall as stream progresses.
    score += progress * (bin_residual as f64 - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 10 classes of size 10.
    let class = (post_residual / 10) as f64;
    score += class * 4.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Dead-space penalty: residual that no plausible item (>=10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item lands in same class bucket.
            let next_class = (next_item_size / 10) as f64;
            score -= 25.0 + next_class * 2.0;
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // Next item would have fit before this placement — mild penalty.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it, else a new bin opens.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only
    // open when no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 70.0 + (open_bins_count as f64).sqrt() * 5.0;
        // Early stream: opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 30.0;
    } else {
        // Prefer filling bins with larger residuals slightly less (keep tight bins for small items).
        score += (bin_residual as f64 - mean_residual).abs() * 0.3;
    }

    // Modulo tie-breaker on post_residual to prefer residuals in harmonically
    // useful classes (multiples of 10 align with common item sizes).
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0;
    } else if m >= 5 {
        score += m as f64 * 0.5;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr_norm = pr / cap ;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm) ;
    score += pr_norm * (0.8 + 2.1 * progress * progress) * cap * 0.5 ;
    score += (1.0 - pr_norm) . powi (6) * (10.0 + 42.0 * progress) ;
    score += 0.3 * (mean_residual - pr) ;
    score += 0.5 * open_bins_count as f64 * pr_norm ;

    if post_residual == 0 { score -= 1000.0 ; }
    else if post_residual <= 4 { score -= 260.0 ; }
    else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64 ;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste ;
    }

    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 640.0 ; }
        else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr ;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 } ;
            score -= chain_bonus * fill ;
            let after = post_residual - next_item_size ;
            if after as f64 <= mean_residual { score -= 32.0 ; }
            if after == 0 { score -= 60.0 ; }
            else if after <= 4 { score -= 42.0 ; }
            else if after <= 10 && next_item_size >= after { score -= 25.0 ; }
            if after as f64 > mean_residual * 2.0 { score += 25.0 ; }
        } else {
            let gap = (next_item_size - post_residual) as f64 ;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 } ;
            score += near_miss_scale * gap ;
        }
    }

    if post_residual > 0 && post_residual < 12 && next_item_size > post_residual { score += 20.0 ; }
    if fitting_bins_count <= 1 && post_residual >= item_size { score -= 60.0 ; }

    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / pr ;
        if tight > 0.92 { score -= 50.0 * tight ; }
        else if tight > 0.75 { score -= 20.0 * tight ; }
        else { score -= 8.0 * tight ; }
    }

    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 } ;
    score += 12.0 * frag * frag * (0.5 + progress) ;

    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap ;
        if cap_frac > 0.7 { score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress) ; }
        else { score += 15.0 ; }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 { score -= 85.0 ; }
        if fitting_bins_count > 2 { score += 10.0 ; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 { score -= 30.0 ; }
        if post_residual > 0 {
            let dev = ((pr - mean_residual) / (mean_residual + 1.0)).abs () ;
            score += 6.0 * dev ;
        }
    }

    if post_residual > 0 && post_residual == item_size { score -= 35.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold typical items are wasted.
    // Any post_residual below the minimum plausible item size is pure loss.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // heavy penalty for tiny useless gaps
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Exact-fit lookahead: if the next item exactly fills the post_residual,
    // this placement is ideal.
    if next_item_size == post_residual && next_item_size > 0 {
        score -= 35.0;
    }
    // If next item fits into post_residual, mildly reward leaving usable room.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item cannot fit in the leftover, the leftover is likely dead space
    // (unless a later item is smaller — treat as penalty scaled by gap size).
    else if next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins dilute residuals; penalize spreading.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (fill the fullest-fitting bins first, classic best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin fits well. Base new-bin score near
    // capacity minus a mild discount; poor fits in open bins will beat it
    // only when they leave very little dead space.
    if bin_residual == bin_capacity {
        // Scale new-bin appeal with stream progression: late in the stream,
        // keep fewer bins open; early on, opening bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = (bin_capacity as f64) * (0.85 + 0.15 * progress)
            + (open_bins_count as f64) * 1.5;
    }

    // Tight-fit reward: small positive residual that can still host a small
    // item is fine; reward near-exact fits generally.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 6.0;
    }

    score
}

