        } else if post >= nxt {
            // next item fits here: reward tight match, penalize slack after next placement
            let slack_after_next = post - nxt;
            score -= 12.0 - 0.25 * slack_after_next.min(40.0);
        } else {
            // next item cannot use this bin's residual: penalize proportionally to leftover waste
            score += 0.15 * (nxt - post).min(60.0);
