        // bonus if this bin AND next item both match perfectly (two-step chain)
        if post >= nxt && (post - nxt) as u32 <= 5 {
            score -= 8.0;
        }
    } else {
        // last item: just minimize waste
        score -= 20.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates usefully.
    let mean = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let post = post_residual as f64;
    if post < mean - 5.0 {
        score -= 4.0; // tighter than average: good consolidation
    } else if post > mean + 15.0 {
        score += 3.0; // much looser than average: risky dead space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize very large post_residual (unusable dead space), non-linearly.
    if post > (bin_capacity as f64) * 0.5 {
        score += 0.3 * (post - (bin_capacity as f64) * 0.5);
