    // Prefer reusing open bins over opening new ones as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress; // new-bin candidate penalty grows over time
    } else {
        score -= 5.0;
