        score += 12.0 + 22.0 * waste + 30.0 * waste * waste;
    }

    // Lookahead coupling (k=2) with tiered chain bonuses
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 620.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 300.0 } else if fill > 0.6 { 190.0 } else { 120.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 40.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 22.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 22.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tight-fit reward: item nearly fills the leftover residual
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / pr;
        if tight > 0.92 {
            score -= 50.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Fragmentation control: deviation from mean residual
    if !is_new_bin {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev.abs();
    }
    score += 0.25 * (mean_residual - pr);

    // Large items prefer emptiest bins; small items prefer tight bins
    let item_class = (item_size * 4) / bin_capacity;
    if item_class >= 2 {
        score -= 0.3 * bin_residual as f64;
    } else {
        score += 0.1 * bin_residual as f64;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 80.0;
    }

    // New-bin candidate economics: cost scaled by item size and progress
    if is_new_bin {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 60.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        score -= 0.2 * mean_residual.max(0.0);
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer minimal post residual, with smooth polynomial shaping.
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 30.0;

    // Reward tight fits (small post residual) more strongly as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 40.0 * progress);

    // Smooth non-linear coupling between post residual and stream progress:
    // later in stream, dead space is costlier.
    score += norm_pr * norm_pr * norm_pr * 25.0 * progress;

    // New-bin candidate handling: penalize opening a new bin, more so early,
    // but relax penalty if fit would be very tight elsewhere is impossible.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9 && post_residual == bin_residual - item_size && bin_residual == bin_capacity;
    if is_new_bin {
        let slack = 8.0 + 40.0 * (1.0 - progress);
        score += slack;
        // If item nearly fills a fresh bin, opening is attractive.
        score -= norm_item * norm_item * 30.0;
    }

    // Last-chance bonus: only one bin fits the item.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: penalize leaving a residual that can't hold next item;
    // reward residuals that exactly accommodate the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            let gap_norm = gap / cap;
            score += gap_norm * 10.0;              // wasted gap relative to next item
            score -= (1.0 - gap_norm) * (1.0 - gap_norm) * 8.0; // reward near-exact chaining
        } else {
            score += 5.0 * (1.0 - pr / nxt.max(1.0)); // next item can't follow here
        }
    }

    // Mild dispersion penalty: keep residuals comparable to mean residual
    // to preserve future placement flexibility.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 6.0;

    // Slight preference to consolidate into fewer bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - norm_item);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
