pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity quarters.
    let quarter = (bin_capacity / 4).max(1);
    let residue_class = (post_residual % quarter) as f64;
    score += residue_class * 0.35; // prefer post-residuals near a harmonic class boundary

    // Dead-space penalty: small unusable post-residuals (below min item size 1..=10 band)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward exact/near-exact fits
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainability reward, scaled by how snugly next item nests
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 15.0 + 20.0 * snug;
        } else {
            // next item won't fit here: penalize more if post_residual is tiny
            score += 10.0 + residue_class * 0.5;
        }
        // Harmonic class of next item: reward bins whose post_residual matches next item's class
        let next_class = next_item_size % quarter;
        if post_residual >= next_item_size && (post_residual - next_item_size) % quarter == 0 {
            score -= 12.0;
        }
        let _ = next_class;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive unless
    // no good fit exists among open bins (mean residual low relative to item).
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        score = cap * 0.9 + pressure * 10.0 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0; // opening fresh bin lets next item start clean
        }
    }

    // Mild tightening pressure as stream progresses
    score -= (step_index as f64 / total_items.max(1) as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1..100 interface => treat <10 as near-dead, <20 as risky)
    if post_residual < 10 {
        score -= 60.0; // perfect or near-perfect fill, highly desirable
    } else if post_residual < 20 {
        score += 45.0; // risky dead zone: gap likely unusable
    } else if post_residual < 30 {
        score += 20.0;
    }

    // Tight fit reward: fraction of bin consumed by this item
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Penalize leaving a gap that just barely excludes the next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // next item can't use this residual
        } else if post_residual >= next_item_size {
            score -= 15.0; // residual stays useful for lookahead
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation when open bins are few
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high
        score += 25.0 + 8.0 * pressure + 10.0 * progress;
    } else {
        score -= 5.0 * pressure.min(3.0);
    }

    // Mild alignment with mean residual: prefer bins whose residual is
    // already below average (they are "closable" soon)
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
