    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Large items (>= half capacity) prefer emptiest bins; small items prefer tight bins
    let item_class = (item_size * 4) / bin_capacity;
    if item_class >= 2 {
        score -= 0.3 * bin_residual as f64;
    } else {
