    let mut score = pr;

    // Smooth non-linear penalty on residual size: larger leftovers cost more, quadratically,
    // but this penalty fades as the stream progresses (tight packing matters more early/mid).
    let quad = norm_pr * norm_pr;
    score += 30.0 * quad * (1.0 - progress);

    // Cubic coupling: residuals that are "awkwardly mid-sized" are penalized smoothly.
    let awkward = 4.0 * norm_pr * (1.0 - norm_pr); // peaks at 0.5 residual
    score += 20.0 * awkward * awkward * (0.5 + 0.5 * progress);

    // Reward tight fits: smooth bell around very small post residuals.
    let tightness = (-norm_pr * norm_pr / 0.02).exp();
    score -= 25.0 * tightness;

    // Lookahead coupling: reward residuals that smoothly match the next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (norm_pr - nx).abs();
        let match_bonus = (-gap * gap / 0.01).exp();
        score -= 18.0 * match_bonus;
    } else {
        // Last item: any residual is dead space; penalize smoothly.
        score += 15.0 * norm_pr;
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_item);
    }

    // Fragmentation pressure: when many bins are open with high mean residual,
    // prefer consolidating into bins whose residual is below the mean.
    let mean_norm = mean_residual / cap;
    let below_mean = (mean_norm - norm_pr).max(0.0);
    score -= 8.0 * below_mean * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate handling: empty bin gets a smooth adaptive barrier
    // that shrinks as the stream progresses (late stream favors closing bins out).
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * (1.0 - progress) * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.93;
    score
