pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in a "usable"
    // class (divisible cleanly or large enough for small items) are favored.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // class by integer division: residual bands of size 10
        let band = pr / 10;
        match band {
            0 => score += 25.0,                 // dead space < 10: useless
            1 => score += 10.0,                 // 10-19: fits only tiny items
            2 => score -= 5.0,                  // 20-29: decent
            3 => score -= 12.0,                 // 30-39: good
            4 | 5 => score -= 18.0,             // 40-59: very reusable
            _ => score -= 10.0,                 // large residual, bin mostly empty
        }
        // modulo arithmetic: residuals that are multiples of common item
        // granularity (5/10) are more likely to be exactly filled later
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact or near-exact chain fit is gold
            let slack = (pr - next_item_size) as f64;
            score -= 15.0;
            if slack == 0.0 { score -= 20.0; }
            else if slack < 10.0 { score -= 8.0; }
        } else {
            // next item won't fit here: penalize proportionally
            score += ((next_item_size - pr) as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep fresh bins competitive but not dominant
    if bin_residual == bin_capacity {
        // neutral base: its post_residual already encodes desirability
        // discourage hoarding many open bins when item fits elsewhere well
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            score += 8.0;
        }
        if open_bins_count > 0 && item_size <= 30 {
            score += 12.0; // small items should go into open bins
        }
    }

    // Fractional capacity coupling: reward tight fills relative to capacity
    let fill = (item_size as f64) / cap;
    score -= fill * 20.0;

    // Stream progression: later in the stream, prefer closing bins tightly
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * (mean_residual - post_residual as f64).abs().min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
