pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum item size (1..=8) are pure waste.
    let dead_gap = post_residual < 8;
    if dead_gap {
        score += 60.0 + (8 - post_residual) as f64 * 8.0;
    } else if post_residual <= 15 {
        // Small-but-usable gaps: moderate penalty, scaled by how likely
        // the next item can use them.
        let usable = (next_item_size > 0 && (next_item_size as f64) <= post_residual as f64) as f64;
        score += (15.0 - post_residual as f64) * (3.0 - 2.0 * usable);
    }

    // Reward near-perfect fits strongly (tight packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item exactly fills the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && (next_item_size as u32) < post_residual {
        // Next item fits into the gap: mild reward proportional to fill.
        let fill = next_item_size as f64 / post_residual as f64;
        if fill > 0.7 {
            score -= 25.0 * fill;
        }
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Next item cannot use the residual: penalize large leftover gaps.
        score += (post_residual as f64).min(30.0) * 0.5;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (favor consolidating into existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with open_bins_count.
        score += 55.0 + pressure * 6.0;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a bin.
        score -= 35.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins get packed first).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Mild preference for filling fuller bins overall.
    let fullness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fullness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the new residual -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits into the post residual: moderate reward, scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 50.0 + 150.0 * tightness;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space, worse when leftover is small.
        let dead = post_residual as f64;
        score += 80.0 * (1.0 - dead / bin_capacity as f64);
    }

    // Penalize creating residual far below the smallest plausible item when nothing matches.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual: prefer bins whose residual usage stays balanced,
    // but allow tightening a large-residual bin.
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Opening a new bin is attractive only when no open bin gives a good fit
    // (post residual too small relative to typical items) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_fit_possible = next_item_size > 0 && post_residual >= next_item_size;
        if !good_fit_possible {
            score -= 120.0;
        }
        // Mild preference for consolidating early, spreading late.
        score += 30.0 * (1.0 - progress) - 30.0 * progress;
    }

    // Reward closing bins almost completely (waste < 10).
    if post_residual < 10 {
        score -= 100.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr_norm = pr / cap ;
    // base: prefer tight fits, slightly nonlinear in residual size
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm) ;
    score += 0.3 * (mean_residual - pr) ;
    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 4 {
        score -= 260.0 ;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64 ;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste ;
    }
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0 ;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr ;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 } ;
            score -= chain_bonus * fill ;
            let after = post_residual - next_item_size ;
            if after as f64 <= mean_residual { score -= 32.0 ; }
            if after == 0 { score -= 60.0 ; }
            else if after <= 4 { score -= 42.0 ; }
            else if after <= 10 && next_item_size >= after { score -= 25.0 ; }
            if after as f64 > mean_residual * 2.0 { score += 25.0 ; }
        } else {
            let gap = (next_item_size - post_residual) as f64 ;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 } ;
            score += near_miss_scale * gap ;
        }
    }
    // tightness coupling with mild nonlinearity
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / pr ;
        if tight > 0.92 { score -= 50.0 * tight ; }
        else if tight > 0.75 { score -= 20.0 * tight ; }
        else { score -= 8.0 * tight ; }
    }
    // fragment penalty grows with progress
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 } ;
    score += 12.0 * frag * frag * (0.5 + progress) ;
    // mild preference to consolidate into fewer open bins when residuals are large
    score += 0.5 * open_bins_count as f64 * pr_norm ;
    // new-bin candidate handling
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap ;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress) ;
        } else {
            score += 15.0 ;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 { score -= 85.0 ; }
        if fitting_bins_count > 2 { score += 10.0 ; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 { score -= 30.0 ; }
        // dead-space avoidance: penalize new bins whose post residual deviates from stream mean
        if post_residual > 0 {
            let dev = ((pr - mean_residual) / (mean_residual + 1.0)).abs () ;
            score += 8.0 * dev ;
        }
    }
    if post_residual > 0 && post_residual == item_size { score -= 35.0 ; }
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size
        && (post_residual - next_item_size) as f64 > mean_residual * 2.0 { score += 25.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: leftover with non-linear fill pressure
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Progress-coupled fill pressure: later in stream, prefer fuller bins harder
    score += pr_norm * (0.8 + 2.1 * progress * progress) * cap * 0.5;

    // Dead-zone penalty for large leftovers that will likely never be filled
    let dead_zone = (1.0 - pr_norm).powi(6);
    score += dead_zone * (10.0 + 42.0 * progress);

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead coupling (k=2)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
                score -= 32.0;
            }
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Item fits snugly into leftover
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.92 {
            score -= 50.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Fragmentation control: pull toward mean residual
    score += 0.3 * (mean_residual - pr);

    // Count-aware pressure: more open bins -> prefer tighter fits
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation index
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // New-bin candidate economics
    if is_new_bin {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    } else {
        // Last-chance bin reward (mutated: scaled by progress)
        if fitting_bins_count == 1 {
            score -= 80.0 + 40.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Perfect or near-perfect fit: strong reward.
    if post == 0.0 {
        score -= 1000.0;
    } else if post <= 5.0 {
        score -= 500.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 range).
    // Waste is proportional to how unusable the leftover is.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            // This bin can't take the next item; penalize proportionally to wasted capacity.
            score += (nxt - post) * (1.5 + 2.0 * progress);
        } else {
            // Reward bins that can still host the lookahead item.
            score -= 10.0 + 5.0 * (1.0 - (post - nxt) / cap);
        }
    } else {
        // Last item: only tightness matters.
        score -= (cap - post) * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0 + 80.0 * progress;
    }

    // Many fitting bins: competition is high, mild penalty to prefer the tightest fits
    // (tight fits already rewarded via post_residual, this sharpens discrimination).
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(10.0);
    }

    // Global state coupling: prefer filling bins below the mean residual when mean is low
    // (bins are nearly full overall); prefer high-residual bins when mean is high.
    score += 0.3 * (residual - mean_residual);

    // Late in the stream, consolidation matters more: penalize spreading across many bins.
    score += (open_bins_count as f64).ln().max(0.0) * (5.0 + 20.0 * progress);

    // New-bin candidate handling: it is attractive early (spread items for future flexibility)
    // and when the current bin's fit is poor; otherwise discourage.
    if bin_residual == bin_capacity {
        let poor_fit = (post / cap) > 0.5; // more than half the new bin would remain
        let base = if poor_fit { 40.0 } else { 200.0 };
        // Early stream: opening bins is cheap; late stream: expensive.
        score += base * (1.0 - 0.6 * progress);
        // If many bins are open, opening yet another is worse.
        score += 3.0 * (open_bins_count as f64);
        // But if the new bin would leave a gap exactly matching the next item, reward it.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 150.0;
        }
    }

    // Small non-linear tightness shaping: quadratic reward for small post residuals.
    score -= (cap - post) * (cap - post) / (4.0 * cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear penalty on residual: quadratic coupling with stream progress
    // (late in stream, small residuals are more acceptable; early, prefer tight fits)
    score += 40.0 * norm_pr * norm_pr * (1.0 - progress);
    score += 15.0 * norm_pr * progress;

    // Cubic smooth interaction: penalize medium residuals especially
    let mid = norm_pr * (1.0 - norm_pr);
    score += 30.0 * mid * mid;

    // Lookahead coupling: smooth reward if next item can use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_quality = (pr - nxt).max(0.0) / cap;
        let usable = if pr >= nxt { 1.0 } else { 0.0 };
        score -= 25.0 * usable * (1.0 - fit_quality) * (1.0 - fit_quality);
        // Penalize residual that neither fits next item nor is tiny
        let gap = (nxt - pr).max(0.0) / cap;
        score += 20.0 * gap * gap;
    }

    // Last-chance bin: smooth reward when alternatives are scarce
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - norm_pr * norm_pr);
    }

    // Reward using bins with small residual relative to mean (consolidate)
    let mean_norm = mean_residual / cap;
    score += 10.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm);

    // Mild preference for filling existing bins when many are open
    score += (open_bins_count as f64).ln() * norm_pr * 5.0;

    // New-bin candidate: penalize opening a fresh bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - progress) + 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: modulo arithmetic on capacity fractions ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Items whose residual falls into a "harmonic class" (multiples of quarter/eighth)
    // are more reusable: reward residuals that are exact multiples of small divisors.
    let pr_u = post_residual;
    if pr_u > 0 {
        if pr_u % 25 == 0 {
            score -= 6.0; // perfect quarter-class residual: highly reusable
        } else if pr_u % 20 == 0 {
            score -= 4.0;
        } else if pr_u % 10 == 0 {
            score -= 2.5;
        } else if pr_u % 5 == 0 {
            score -= 1.0;
        }
        // Penalize residuals in "dead zones" that few item sizes can use
        if pr_u < 10 {
            score += 12.0; // dead space below smallest plausible item
        } else if pr_u < 25 && pr_u % 5 != 0 {
            score += 4.0; // awkward small residual, non-harmonic
        }
    }

    // Integer-division threshold: post_residual bucketed into eighths of capacity.
    let bucket = post_residual / 12; // ~capacity/8 granularity
    score -= (bucket as f64) * 0.6;

    // --- Lookahead coupling: does next_item_size fit the post_residual? ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits here: strong reward, scaled by tightness of the fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
            // Harmonic bonus: next item leaves another harmonic residual
            let nn = post_residual - next_item_size;
            if nn > 0 && (nn % 25 == 0 || nn % 10 == 0) {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 3.0 * (over / cap).min(1.0);
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, avoid forcing a bad fit ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This bin is the last chance before opening a new bin: reward using it
        // unless it creates severe dead space.
        if post_residual >= 10 {
            score -= 5.0;
        } else {
            score += 6.0; // forced fit creating dead space — prefer new bin
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // New bin: attractive when current item is large (would fragment open bins)
        // and open bins are already numerous/tight.
        let frag = 1.0 - (item_size as f64) / cap;
        score = cap as f64 * 0.55 + frag * 20.0;
        if open_bins_count == 0 {
            score = -10.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0; // next item also fits a fresh bin alongside
        }
        // Late in stream, prefer closing out open bins rather than spreading
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
        return score;
    }

    // --- Tight-fit reward: item nearly fills the bin ---
    let fill = (item_size as f64) / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 7.0;
    } else if fill > 0.75 {
        score -= 3.0;
    }

    // Prefer bins with residuals near the item (best-fit flavor) modulated by mean residual
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += (gap / cap) * 2.0;
    if (bin_residual as f64) < mean_residual {
        score -= 1.5; // tighter-than-average bin slightly favored
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Progress-coupled dead-space pressure (borrowed from best heuristic).
    score += pr_norm * (0.8 + 2.1 * progress * progress) * cap * 0.5;

    // Dead-zone penalty for near-full bins.
    let dead_zone = (1.0 - pr_norm).powi(6);
    score += dead_zone * (10.0 + 42.0 * progress);

    // Perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        // Gap below current item size is waste for this item.
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead on next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if (next_item_size as u32) < post_residual {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
                score -= 32.0;
            }
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tightness reward relative to current item.
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / pr;
        if tight > 0.92 {
            score -= 50.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Mean-residual alignment and open-bin pressure.
    score += 0.3 * (mean_residual - pr);
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation penalty.
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // New-bin candidate logic (calibrated opening).
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: keep parent's consolidation bonus.
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals below the minimum item size (1..=9)
    // are pure waste; add a strong penalty proportional to how "dead" the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Reward using bins with large residual (waste big gaps first),
    // penalize chipping away at tight bins unless it's a near-perfect fit.
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * residual_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap < 10 {
            score += 20.0; // next item would create dead space here
        } else {
            score -= 5.0;
        }
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, tighten up: waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
