pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good, but emphasize closeness).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 30.0 * (fit_ratio - 0.85) / 0.15;
    }

    // Penalize small dead space that nothing can use (dead space < min item size 10).
    if post_residual < 10 {
        score -= 8.0; // perfect fill, reward
    } else if post_residual < 20 {
        score += 5.0; // awkward dead zone
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 12.0;
        // Extra reward if next item fits almost exactly.
        let leftover = post_residual as f64 - next_item_size as f64;
        if leftover < 10.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        // Next item won't fit here; penalize leaving post_residual just below next size (trapped space).
        let gap = next_item_size as f64 - post_residual as f64;
        if gap < 15.0 {
            score += 6.0;
        }
    }

    // Global residual balance: prefer bins whose residual is near the mean (spread load evenly)
    // unless it's a tight fit situation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it more as the stream progresses.
        score += 15.0 * progress + 0.5 * open_bins_count as f64;
        // But early on, allow new bins when current bins have low residuals.
        if progress < 0.3 && mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Late stream: favor existing bins even more.
        score -= 5.0 * progress;
