    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear penalty on large residuals
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, reward tightness more aggressively
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Non-linear dead-space penalty: quadratic in residual relative to mean residual
    let mean_gap = norm_pr - mean_residual / cap;
    score += 8.0 * mean_gap * mean_gap;

    // Last-chance bonus: strongly favor using the only fitting bin (smoothly scaled)
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward residuals that leave room for the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs() / cap;
        score += 6.0 * fit_gap * fit_gap - 4.0 * (1.0 - fit_gap);
        // Penalize leaving residual slightly larger than next item (dead space)
        if pr >= nxt {
            let waste = (pr - nxt) / cap;
            score += 10.0 * waste * waste;
        }
    } else {
        // Last item: minimize residual as much as possible
        score += 15.0 * norm_pr * norm_pr;
    }

    // Mild penalty for spreading across too many open bins
    score += (open_bins_count as f64).ln() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

