    } else {
        // Modulo-10 harmonic bonus: residuals divisible by 10 are reusable.
        if pr % 10 == 0 {
            score -= 12.0;
        }
        // Modulo-5 secondary class.
        if pr % 5 == 0 {
            score -= 4.0;
        }
        // Small dead space (1..=9) is nearly unusable: penalize proportionally.
        if pr < 10 {
