        // Penalize residuals in the awkward 61..80 band (too big to waste, too
        // small to host a large item comfortably).
        if pr > 60 && pr <= 80 && next_item_size > pr {
            score += 6.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
