            let fill_ratio = next_item_size as f64 / pr as f64;
            score -= 15.0 * fill_ratio;
            if pr % next_item_size.max(1) == 0 {
                score -= 8.0; // harmonic divisibility: future splits stay clean
            }
        } else {
            // next item won't fit here: mild penalty for fragmenting
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual; keep it
    // attractive only when current bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline; discourage unless open bins are tight.
        score += 10.0;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 25.0; // open bins nearly full -> prefer new bin
        }
    }

    // Progress-adaptive tightness: late in the stream, waste hurts more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.3 * progress;

    // Prefer filling bins that are already relatively full (low residual).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min size 1, but practically < ~12 are near-useless) are heavily penalized.
    let dead_zone = 12.0;
    if post_residual >= 1 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }

    // Perfect / near-perfect fits are rewarded strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward tight fits relative to residual (waste fraction penalty).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 10.0;

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage scattering across many bins,
    // but a brand-new bin (residual == capacity) escapes this pressure.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 0.8;
    } else {
        // New bin: mildly discourage unless it avoids dead space.
        score += 3.0 + 0.3 * (open_bins_count as f64);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item would leave yet another dead gap, penalize.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && (gap as f64) < dead_zone {
            score += (dead_zone - gap as f64) * 2.0;
        }
    }

    // Slight preference early in stream to keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    // Mean residual coupling: prefer bins deviating below mean residual
    // (i.e., fuller bins) when many bins are open.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05 * (open_bins_count as f64).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Progress-coupled residual weight (mutated constant)
    let progress_coupling = pr_norm * (0.8 + 2.4 * progress * progress);
    score += progress_coupling * cap * 0.5;

    // Dead-zone penalty near-full bins
    let dead_zone = (1.0 - pr_norm).powi(6);
    score += dead_zone * (10.0 + 45.0 * progress);

    // Perfect / dead-space rewards and penalties
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead chaining on next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
                score -= 32.0;
            }
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tight-fit reward for placements that fill the residual well
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / pr;
        if tight > 0.92 {
            score -= 50.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Mean-residual balancing (mutated sign/scale)
    score += 0.35 * (mean_residual - pr);

    // Open-bin pressure scaled by residual fraction (mutated)
    score += 0.6 * open_bins_count as f64 * pr_norm;

    // Fragmentation term
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // NEW-BIN CANDIDATE logic (mutated with lookahead-aware opening)
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        // If next item is large relative to mean residual, opening a fresh bin is good
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // Mutated: late-stream new-bin discount to consolidate early
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item fits comfortably after this placement (good chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual as f64 - next_item_size as f64);
    }
    // Placement leaves dead space smaller than the next item (wasted gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 80.0;
    }

    // Compare post_residual against mean residual: leaving more than average space is good.
    score -= 0.3 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Early in the stream, prefer consolidating into open bins over spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 50.0 * (1.0 - progress);
    } else {
        // New-bin candidate: penalize unless it looks like the only viable option.
        score += 60.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 40.0;
        }
    }

    // Penalize very tight leftover slivers that no future item (>=1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a gap it could have used elsewhere.
            score += 4.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
