        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // Penalize creating small unusable dead space (below typical minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= 1.5 * pressure.min(10.0);

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 25.0 * progress;
        // But early on with few bins, opening is cheap.
        score -= 8.0 * (1.0 - progress) * (1.0 - (open_bins_count as f64 / 10.0).min(1.0));
    } else {
        // Existing bin: reward more as stream progresses.
        score -= 6.0 * progress;
    }

    // Coupling: prefer bins whose residual deviates below the mean (waste-aware).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.3 * dev.min(30.0);
    }

    score
}

