pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual, non-linearly.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 40.0 * tight * tight;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space: post_residual too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_ratio = (next_item_size as f64 - post_residual as f64) / cap;
        score += 20.0 * waste_ratio * cap * (0.5 + progress);
    }

    // Reward perfect lookahead fit: next item exactly fills the new residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 + progress);
