    // penalized when open bins have plenty of room (mean_residual high).
    if bin_residual == bin_capacity {
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        score += 15.0 + 30.0 * openness * (1.0 - progress);
        score -= 10.0 * progress;
