pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: modulo arithmetic on capacity ---
    // Residuals divisible by 10 are "harmonic" slots: future items (1..100)
    // frequently land well on them. Reward low-harmonic, penalize awkward ones.
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 0.9; // awkward remainder -> penalty

    // Integer-division thresholds on post_residual (capacity fractions)
    let frac = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect closure is excellent
    } else if post_residual <= bin_capacity / 10 {
        score -= 25.0; // near-closed: tiny dead space
    } else if post_residual <= bin_capacity / 4 {
        score -= 8.0;  // small usable slot
    } else if frac >= 0.5 {
        score += 6.0;  // half-empty bin: wasteful placement of a big item
    }

    // Dead-space penalty: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // --- Lookahead coupling with harmonic classes ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward exact / harmonic matches
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 40.0; // chain closure
            } else {
                score -= (20.0 - slack as f64 * 0.2).max(0.0);
            }
            // reward if next item lands on a multiple-of-10 boundary too
            if (post_residual % 10) as u32 == next_item_size % 10 && post_residual >= next_item_size {
                score -= 5.0;
            }
        } else {
            // Next item cannot fit here: penalize, scaled by how close it was
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0; // only fitting bin: strongly prefer it over new bin
    } else if fitting_bins_count == 0 {
        score += 50.0; // shouldn't happen, safety
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // New bin starts with residual = capacity. Score it relative to
        // mean residual of open bins: prefer new bin only if open bins are tight.
        score = 100.0 - mean_residual * 0.5;
        if fitting_bins_count <= 1 {
            score -= 20.0; // few alternatives -> new bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin has room for lookahead
        }
    }

    // --- Stream progression: tighten late in the stream ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - frac);

    // Mild preference to fill already-open bins when many are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // even the smallest plausible item (<=10) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small unusable-ish gaps: penalize proportionally to how close
        // they are to the dead zone.
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

