    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        // Post residual can't host next item and is dead space: extra penalty.
        score += 20.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing
    // ones (penalize the new-bin candidate implicitly via residual, but add
    // pressure term so tight fits in open bins beat opening new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.5;

    // Last chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's one of the tighter bins — filling tight bins first keeps loose
