    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.1;
    }

    // New-bin candidate: empty bin should only win when it's genuinely
    // better; add a fixed opening cost.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

