    score -= (bin_capacity as f64 - post_residual as f64) * 0.9;

    // Lookahead: penalize creating dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if post_residual == next_item_size {
            score -= 8.0; // perfect two-item pairing
        } else {
            score -= 2.0; // next item still fits here
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Penalize opening new bins when plenty of bins already fit the item.
    if bin_residual == bin_capacity {
        score += 10.0 + (fitting_bins_count as f64) * 2.0;
        // Early in the stream, be more willing to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
