            score -= 50.0 * t;
        } else if t > 0.75 {
            score -= 20.0 * t;
        } else {
            score -= 8.0 * t;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
