    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize mildly so we prefer good existing fits,
    // but keep it attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        score += 12.0 - 0.15 * mean_residual;
    }

    // Stream progression: as stream ends, tighten bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    // Many open bins: prefer consolidation into fuller bins.
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs();
    }

    score
}

