        // Fresh bin baseline: mid-range score. Prefer reusing bins with good
        // fits (perfect fits score far below this), but prefer a new bin over
        // sloppy placements that leave large dead space.
        score = 50.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // new bin can serve the stream well
        }
        return score;
    }

    // --- Open-bin pressure ---
    // Too many open bins: encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Slight preference for bins tighter than the average residual.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.97;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit relative to capacity.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Aggressive 2-step lookahead: strongly reward when next item fits
    // the post residual exactly or nearly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let gap = post - next;
            // Perfect 2-step match: post_residual == next_item_size.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Reward proportional to how well next item fills leftover.
                score -= 40.0 * (next / post);
                // Penalize small unusable remainder after the pair.
                if gap < 10.0 {
                    score += 15.0;
                }
            }
        } else {
            // Next item won't fit here; penalize large dead space.
            score += 10.0 + 0.2 * post;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably from the fleet mean (below mean = tighter bin).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive late in the stream or
    // when item is huge and would leave tiny dead space in any bin.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste_elsewhere = 100.0 - item_size as f64;
        let mut new_score = 30.0 * progress + 0.5 * waste_elsewhere;
        if next_item_size > 0 && (100 - item_size as u32) >= next_item_size {
            new_score -= 20.0; // fresh bin accommodates the next item too
        }
        score = new_score;
    }

    // Mild penalty for leaving very small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) with extra bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            // Perfect chain fit: strongly reward.
            score -= 8.0;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Penalize opening new bins when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let slack = mean_residual - item_size as f64;
        if slack > 0.0 {
            score += 0.15 * slack + 2.0 * (open_bins_count as f64).ln().max(0.0);
        }
        // Early in the stream, new bins are cheap; late, expensive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * progress;
    }

    // Mild penalty for leaving residuals that are hard to fill (small odd gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic penalty on wasted post residual (dead space), weighted by progress
    let mut score = post * (1.0 + 1.5 * progress * post / cap);

    // Smooth non-linear coupling: post residual interacts with mean residual
    let mean_norm = mean_residual / cap;
    score += 2.0 * post * mean_norm * (1.0 - mean_norm);

    // Reward tight fits (small post residual) with a smooth sigmoid-like bonus
    let tight = (1.0 - post / cap).powi(6);
    score -= 8.0 * tight;

    // Last-chance bin: strongly favor using it when few bins fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits in post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fill = nxt / cap;
            score -= 4.0 * fill * (1.0 - fill);
        } else {
            // penalize leaving residual that cannot host next item
            score += 3.0 * (post / cap) * (nxt / cap);
        }
    }

    // New-bin candidate handling: neutral-ish, slightly penalized unless current bins are tight
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln_1p();
        score = 0.5 * post + 10.0 + 5.0 * openness * (1.0 - progress) - 15.0 * progress;
    }

    // Mild crowding penalty: prefer bins among many with spreading residuals
    score += 0.5 * (open_bins_count as f64).ln_1p() * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse buckets via integer division (class width 10).
    let post_class = post_residual / 10;
    score += (post_class as f64) * 2.5; // larger class = more dead space, penalize

    // Perfect/near-perfect fits are gold: post_residual 0 gets big reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Harmonic residue: post_residual mod 10 — small remainders are more
    // likely to be fillable by future small items; reward low residues.
    let residue = post_residual % 10;
    score -= (10 - residue as i64) as f64 * 0.4;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly-ish: strong reward
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 45.0;
            } else if slack <= 10 {
                score -= 20.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; leftover will be dead unless small
            if post_residual < 10 {
                score += 12.0; // tiny dead space, mildly penalize
            } else {
                score -= 3.0; // big leftover may still serve later items
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make an empty bin moderately attractive
    // only when current fit is poor (large post_residual) or few fitting bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 0.35 * bin_capacity as f64;
        if poor_fit || fitting_bins_count == 0 {
            score -= 18.0 + 10.0 * progress;
        } else {
            score += 25.0; // discourage opening new bins when fits exist
        }
    }

    // Mean residual pressure: if open bins are generally loose, prefer
    // consolidating into tight ones (this bin's residual below mean).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Modulo threshold on item_size: items in "harmonic" sizes (multiples
    // of 25) pack well with complements; slight reward for placing them.
    if item_size % 25 == 0 {
        score -= 2.0;
    }
    if item_size % 10 == 0 && post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0; // aligned harmonic classes, leftover stays divisible
    }

    // Tie-breaker noise-free nudge toward bins with residual close to item
    let tightness = 1.0 - ((bin_residual - item_size) as f64 / bin_capacity as f64);
    score -= tightness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Tightness reward: strongly favor small post_residual, non-linearly.
    let tight = 1.0 - pr_norm;
    score -= 40.0 * tight * tight;

    // Exact / near-exact fit bonuses.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Penalize dead space: post_residual too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
        score += near_miss_scale * gap * (0.5 + progress);
    }

    // Reward perfect lookahead fit: next item exactly fills the new residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 640.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        let fill = next_item_size as f64 / pr;
        let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
        score -= chain_bonus * fill;
        let after = post_residual - next_item_size;
        if after == 0 {
            score -= 60.0;
        } else if after as f64 <= mean_residual {
            score -= 32.0;
        } else if after <= 4 {
            score -= 42.0;
        } else if after <= 10 && next_item_size >= after {
            score -= 25.0;
        }
        if after as f64 > mean_residual * 2.0 {
            score += 25.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: penalized when open bins have room, but opened eagerly
    // for large items when few bins fit them.
    if bin_residual == bin_capacity {
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        score += 15.0 + 30.0 * openness * (1.0 - progress);
        score -= 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Mild penalty for spreading across many bins late in the stream.
    score += (open_bins_count as f64).ln() * 1.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to ever hold the next item
    // (or a minimum plausible item) are heavily penalized.
    let min_item = 1u32.max(next_item_size.min(10));
    if post_residual > 0 && post_residual < min_item {
        score += 40.0 + 0.5 * post_residual as f64;
    }

    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item if it still fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // creating a gap that the next item cannot use
            score += 8.0;
        }
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.6 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: default mild penalty so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 10.0;
        // but if the item fits snugly in a fresh bin, make it attractive
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 12.0;
        }
    }

    // Align with mean residual: bins far below mean residual are "wasted" space holders;
    // prefer bins whose residual is close to what we consume.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * residual_gap;

    // Slight stream-progress awareness: late in the stream, be more conservative
    // about creating small gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
