pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 120.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // exact 2-step chain completion: residual == next item
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // penalize leaving residual that no small item can use (dead space)
        if post_residual < 10 {
            score += 200.0;
        }
    }

    // Compare residual against mean residual: prefer tighter-than-average bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 150.0;
        // but a new bin is fine if it enables a good 2-step chain with the next item
        if next_item_size > 0 && bin_capacity.saturating_sub(item_size) >= next_item_size {
            score -= 100.0;
        }
    }

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize leftover space (primary waste signal).
    let mut score = post;

    // Tight-fit reward: strongly favor small post_residual, non-linearly.
    let tightness = 1.0 - (post / cap);
    score -= 60.0 * tightness * tightness * tightness;

    // Perfect or near-perfect fit gets an extra big bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills remainder
            let fill = nxt / post.max(1.0);
            score -= 40.0 * fill;
        } else {
            // next item won't fit here: mild penalty scaled by overshoot
            let over = (nxt - post) / cap;
            score += 25.0 * over;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // Global state: when many bins are open with large mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = mean_residual / cap;
    score -= 30.0 * consolidation * (1.0 + open_bins_count as f64 / 10.0);

    // Time horizon: late in the stream, waste matters more (fewer future
    // items to fill gaps), so penalize residual harder as we progress.
    score += post * (0.5 + 0.5 * progress);

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and would leave a very fragmented fit elsewhere.
    if bin_residual == bin_capacity {
        // New bin baseline: its post_residual already penalizes it.
        // Make it more attractive early (amortization) and for large items.
        let amortize = 1.0 - progress;
        score -= 70.0 * amortize;
        score -= 25.0 * (item / cap);
        // Discourage new bins when a decent existing fit exists.
        if fitting_bins_count > 0 && post > 40.0 {
            score += 40.0;
        }
    }

    // Mild penalty for creating medium dead space that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny gaps are nearly useless
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
