    if next_item_size > 0 {
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += 2.5 * waste;
    }

    // smooth coupling: waste-tolerance grows with stream progress
    score -= 30.0 * progress * pr_norm * (1.0 - pr_norm);

    // last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // mild preference to fill bins when many are open
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr_norm);

    // new-bin candidate: neutral-ish, slightly penalized unless tight fit impossible
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    // align residual with mean residual structure
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
