    if post_residual > 0 && post_residual < 12 && next_item_size > post_residual { score += 20.0 ; }
    if fitting_bins_count <= 1 && post_residual >= item_size { score -= 60.0 ; }
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / pr ;
        if tight > 0.92 { score -= 50.0 * tight ; }
        else if tight > 0.75 { score -= 20.0 * tight ; }
        else { score -= 8.0 * tight ; }
    }
    score += 0.3 * (mean_residual - pr) ;
    score += 0.5 * open_bins_count as f64 * pr_norm ;
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 } ;
    score += 12.0 * frag * frag * (0.5 + progress) ;
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap ;
        if cap_frac > 0.7 { score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress) ; }
        else { score += 15.0 ; }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 { score -= 85.0 ; }
        if fitting_bins_count > 2 { score += 10.0 ; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 { score -= 30.0 ; }
        if post_residual > 0 {
            let dev = ((pr - mean_residual) / (mean_residual + 1.0)) . abs () ;
            score += 8.0 * dev ;
        }
    }
    if post_residual > 0 && post_residual == item_size { score -= 35.0 ; }
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 > mean_residual * 2.0 { score += 25.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual falls into
    // "small" residue classes are near-perfect, reward them strongly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries via integer division thresholds on post_residual
    let class = post_residual / 10; // 0..=10 harmonic classes
    match class {
        0 => score -= 40.0,            // near-perfect fit (0..9)
        1 => score -= 28.0,            // excellent
        2 => score -= 18.0,            // good
        3 => score -= 10.0,            // decent
        4 => score -= 4.0,             // fair
        _ => {}                        // large leftovers: no reward
    }

    // Modulo-10 resonance: leftover that is itself a "typical" item size
    // (multiple of 10) is reusable; reward it.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this is a harmonic pair — strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize proportional to overshoot class
            score += 4.0 + ((next_item_size - post_residual) / 20) as f64 * 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only open a new bin when the current item is large
    // and no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin
        score = (bin_capacity - item_size) as f64;
        // prefer new bin early in stream or when open bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        // if existing fits are poor (mean residual small relative to item), new bin wins
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        // large items start fresh bins to avoid fragmenting small-capacity bins
        if item_size >= 60 {
            score -= 12.0;
        }
    }

    // Mild pressure against accumulating many open bins with fat residuals
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize post_residual that cannot fit the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward post_residual that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    } else {
        // Mild reward for using existing bins, scaled by open bins count.
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // Early stream: slightly favor filling existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual) via non-linear shaping.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item does NOT fit here: penalize relative to how far off we are.
        let miss = (next_item_size - post_residual) as f64;
        score += 15.0 + 25.0 * (miss / bin_capacity as f64);
    }

    // Compare post_residual against mean residual of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so we only open new bins when fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, discourage opening new bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer filling bins among many open bins (bin consolidation).
    if open_bins_count > 3 {
        score -= 2.0 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
