}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize creating small, hard-to-use dead space (post_residual in the awkward 1..=20 zone).
    if post_residual > 0 && post_residual <= 20 {
        score += 8.0 * (21.0 - post_residual as f64) / 21.0;
    }
    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Extra reward if post-residual is a near-perfect match for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / 50.0).clamp(0.0, 1.0);
        } else {
            score += 2.0;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, keep it attractive.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier, prefer the tightest fit via fill ratio (already applied).
        score += 1.5;
    }

    // Time horizon: early in the stream, be more conservative about fragmenting bins;
    // late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (post_residual == 0) as i32 as f64;
    score += 3.0 * (1.0 - progress) * (post_residual > 0 && post_residual < 10) as i32 as f64;

    // Global state: if mean residual across open bins is high, we have slack everywhere,
    // so prefer filling existing bins rather than opening new ones.
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: it's only attractive when nothing fits well
    // (large item vs. all residuals, or no existing bin can take it).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty: default to existing bins.
        score += 18.0;
        // If few bins fit and the item is large, opening a fresh bin is reasonable.
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && item_size >= 60) {
            score -= 30.0;
        }
        // If the next item is large too, a fresh bin wastes capacity; penalize more.
        if next_item_size >= 60 {
            score += 8.0;
        }
        // Late in the stream, avoid opening bins that will end mostly empty.
        if progress > 0.85 {
            score += 10.0 * progress;
        }
    } else {
        // Existing bins get a mild global preference over opening new bins.
        score -= 2.0;
    }

    // Mild preference for bins with less residual overall (consolidate waste).
    score += 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
