    let poly = norm_pr * (1.0 + 0.8 * progress + 0.6 * progress * progress);
    let mut score = poly * cap;

    // Dead-space penalty: quadratic in unusable space (can't fit a typical small item)
    let dead = if pr > 0 && pr < 10 { (10.0 - pr) * (10.0 - pr) } else { 0.0 };
    score += 0.05 * dead;

    // Reward tight fits smoothly (cubic decay of post-residual)
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64;

    // Lookahead: penalize if next item fits poorly in resulting residual (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let kernel = (-gap / 20.0) * (-gap / 20.0);
        score -= 5.0 * kernel;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild consolidation pressure relative to mean residual
    score += 0.02 * (pr - mean_residual);

    // New-bin candidate: slightly penalize opening a bin mid-stream, more later
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress;
    }

    score
}

