        // Next item fits: reward proportional to tightness of the pair.
        let pair_waste = (r - next_item_size) as f64;
        score -= 10.0 * (1.0 - pair_waste / bin_capacity as f64);
    } else if next_item_size > r && r > 0 {
        // Next item cannot use this residual: penalize dead space creation.
        score += 4.0 + 0.05 * r as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the stream is early or all existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its "residual" equals capacity, so the
        // raw score is already high; add a fixed opening penalty that decays
        // as the stream progresses (late in the stream, prefer consolidation).
        score += 30.0 - 20.0 * progress;
        // If many bins are open and mean residual is large, opening new bins
