    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Small tie-breaker favoring earlier-opened bins implicitly through
    // open_bins_count: many open bins -> prefer reusing any bin.
    score -= 0.1 * open_bins_count as f64;

    score
}

