pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr <= 12 {
        // dead space: gap too small for typical items
        score += (13 - pr) as f64 * 40.0;
    } else if pr > 12 && pr <= 30 {
        score += (30 - pr) as f64 * 2.5;
    }

    // Exact fit is the ideal outcome.
    if pr == 0 {
        score -= 200.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && pr == next_item_size {
        score -= 60.0;
    }
    // Penalize if the leftover gap cannot fit the next item (dead space for lookahead).
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += next_item_size as f64 * 1.5;
    }

    // Tight fit reward: item fills most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        score += 80.0;
        score += open_bins_count as f64 * 0.5;
        // If mean residual is large, prefer existing bins.
        score += mean_residual * 1.2;
    }

    // Open-bin pressure: mild reward for consolidating into fewer bins when many are open.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Late in the stream, avoid opening bins and squeeze more into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item's size (perfect chained fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match: big reward; near match: proportional reward.
        score -= 40.0 / (1.0 + diff);
        if diff == 0.0 {
            score -= 60.0;
        }
        // Penalize post_residuals that are too small to fit the next item
        // (dead space) but only mildly if diff is small.
        if (post_residual as f64) < next_item_size as f64 {
            score += 0.5 * diff;
        }
    }

    // Prefer bins tighter than the mean residual (good fits reduce waste).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, consolidate: favor bins with small residual overall.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    // Slight penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // offers a good chained fit; default slightly above well-matched bins.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).unsigned_abs() <= 5 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
