            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to wasted lookahead potential.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the fullest (smallest residual).
        score += 2.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins that are already well-filled relative to the fleet mean.
    score += 1.5 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

