        if fitting_bins_count > 0 {
            score += 6.0;
        }
    }

    // Slight preference to balance load across many open bins late in stream.
    score += 0.5 * (open_bins_count as f64).ln() * (bin_residual as f64 / bin_capacity as f64);

    score
}

