            score -= 600.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 300.0 } else if fill > 0.6 { 190.0 } else { 120.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after as f64 <= mean_residual {
                score -= 28.0;
            } else if after as f64 > mean_residual * 2.0 {
                score += 22.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let scale = if gap <= 8.0 { 0.5 } else { 0.3 };
            score += scale * gap;
        }
    }

    // Tightness of current fit.
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / pr;
        if tight > 0.92 {
            score -= 45.0 * tight;
        } else if tight > 0.75 {
            score -= 18.0 * tight;
        } else {
            score -= 7.0 * tight;
        }
    }

    // Mean-residual balancing.
    score += 0.3 * (mean_residual - pr);

    // Open-bin pressure scaled by residual share.
    score += 0.45 * open_bins_count as f64 * pr_norm;

    // Fragmentation penalty.
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // Last-chance bin: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate evaluation.
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 60.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 18.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 80.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Late-stream tightening.
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);

        // Perfect two-item fill: strong reward
        if post_residual as i64 == next_item_size as i64 {
            score -= 25.0;
        }
        // Next item fits exactly with some slack
        else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 10.0;
        }
        // Next item won't fit: penalize proportionally to wasted lookahead
        else {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Penalize dead space relative to mean residual of open bins
    let mean_res = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) > mean_res {
        score += (post_residual as f64 - mean_res) * 0.3;
    } else {
        score -= (mean_res - post_residual as f64) * 0.1;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild pressure to consolidate into fewer bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Slight penalty when many bins are already open (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr_norm = pr / cap ;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm) ;
    let progress_coupling = pr_norm * (0.8 + 2.1 * progress * progress) ;
    score += progress_coupling * cap * 0.5 ;
    let dead_zone = (1.0 - pr_norm) . powi (6) ;
    score += dead_zone * (10.0 + 42.0 * progress) ;
    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 4 {
        score -= 260.0 ;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64 ;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste ;
    }
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0 ;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / post_residual as f64 ;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 } ;
            score -= chain_bonus * fill ;
            let after = post_residual - next_item_size ;
            if after as f64 <= mean_residual {
                score -= 32.0 ;
            }
            if after == 0 {
                score -= 60.0 ;
            } else if after <= 4 {
                score -= 42.0 ;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0 ;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0 ;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64 ;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 } ;
            score += near_miss_scale * gap ;
        }
    }
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64 ;
        if tight > 0.92 {
            score -= 50.0 * tight ;
        } else if tight > 0.75 {
            score -= 20.0 * tight ;
        } else {
            score -= 8.0 * tight ;
        }
    }
    score += 0.3 * (mean_residual - pr) ;
    score += 0.5 * open_bins_count as f64 * pr_norm ;
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 } ;
    score += 12.0 * frag * frag * (0.5 + progress) ;
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap ;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress) ;
        } else {
            score += 15.0 ;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0 ;
        }
        if fitting_bins_count > 2 {
            score += 10.0 ;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0 ;
        }
        if fitting_bins_count == 1 {
            score += 6.0 * progress ;
        }
    }
    if post_residual > 0 {
        let usable_after = if post_residual >= item_size { post_residual - item_size } else { post_residual } ;
        let waste_frac = 1.0 - (usable_after as f64 / cap) ;
        let dead_penalty = waste_frac * waste_frac * (18.0 + 30.0 * progress) ;
        score += dead_penalty ;
        if next_item_size > 0 && usable_after > 0 {
            let reuse = next_item_size as f64 / usable_after as f64 ;
            if reuse > 1.0 {
                score += 14.0 * (reuse - 1.0).min (2.0) ;
            } else if reuse > 0.9 {
                score -= 18.0 ;
            }
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Lookahead: if next item fits in post_residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use: penalize proportionally.
        score += 0.4 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins with smaller current residual among fitting bins (best-fit coupling).
    score += 0.3 * bin_residual as f64;

    // Time horizon: early in stream, be more willing to open new bins (penalize tight fits less);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 12.0;

    // Global state: many open bins -> discourage spreading; penalize high mean residual mismatch.
    score += 0.05 * open_bins_count as f64;
    score -= 0.1 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when item is large or all fits are terrible.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.7 * bin_capacity as f64;
        if poor_fit && open_bins_count > 0 {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress.
    let p = progress;
    let quad = p * p;
    let cubic = quad * p;
    score += 14.0 * cubic * (post / cap) * (post / cap);
    score -= 9.0 * (1.0 - cubic) * (post / cap);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    let tightness = 1.0 - post / cap;
    score -= (2.0 + 10.0 * quad) * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 0.6 * (nxt - post);
        } else {
            // Smooth reward when post_residual can host the next item.
            let fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 1.5 * fit_quality * fit_quality;
        }
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 6.0 * quad;
    }

    // Mild penalty for spreading across many open bins early on.
    score += 0.25 * (open_bins_count as f64).sqrt() * (1.0 - p);

    // Encourage consolidation toward mean residual.
    score += 0.15 * (post - mean_residual).abs();

    // New-bin candidate: keep it neutral-high unless current placement is bad.
    if bin_residual == bin_capacity {
        score = cap * 0.55 - 8.0 * quad + 0.4 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
