pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Stream progression: slightly prefer compacting early, opening bins later
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: integer division into capacity-fraction bands.
    // Bands closer to zero (tight fills) get a small extra reward.
    let band = (post_residual / 10).min(9) as f64;
    score += band * 2.0;

    // Reward residual classes that are "harmonically clean" (multiples of 10)
    if post_residual % 10 == 0 {
        score -= 3.0;
    }
    // Penalize awkward dead-space classes (1..9 residual = unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: exact harmonic match is a perfect pairing
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0; // perfect next-item fit
        } else if post_residual >= next_item_size {
            score -= 5.0;  // can still host next item
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3; // next item won't fit here
        }
    } else {
        // Last item: just fill anything as tightly as possible
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate (bin_residual == bin_capacity, post_residual = C - item)
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin can host the item: opening a new bin is forced
            score -= 100.0;
        } else {
            // Some bin fits: opening a new bin wastes its residual; penalize,
            // more so early in the stream when compaction is cheap
            score += 40.0 + t * 20.0;
            // If the next item is larger than what this fresh bin would leave,
            // opening is even less attractive
            if next_item_size > post_residual {
                score += 10.0;
            }
        }
    }

    // Mild penalty for bins already far below mean residual (outliers)
    if (post_residual as f64 - mean_residual).abs() > bin_capacity as f64 * 0.5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Tightness reward: strongly favor small post_residual, non-linearly.
    let tight = 1.0 - pr_norm;
    score -= 40.0 * tight * tight;

    // Exact / near-exact fit bonuses.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead: reward perfect chain fit, penalize blocking the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Reward placing large items into proportionally matching residual space.
    if post_residual > 0 && post_residual >= item_size {
        let fill_tight = item_size as f64 / pr;
        if fill_tight > 0.92 {
            score -= 50.0 * fill_tight;
        } else if fill_tight > 0.75 {
            score -= 20.0 * fill_tight;
        } else {
            score -= 8.0 * fill_tight;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: acceptable early or when open bins are nearly full,
    // penalized when open bins have plenty of room (mean_residual high).
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0 + 30.0 * openness * (1.0 - progress);
        }
        score -= 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Mild penalty for spreading across many bins late in the stream.
    score += (open_bins_count as f64).ln() * 1.5 * progress;
    score += 0.3 * (mean_residual - pr);

    // Fragmentation penalty grows with progress.
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (size 1..=3)
    // are permanently wasted; penalize them heavily.
    if post_residual > 0 && post_residual < 4 {
        score += 60.0;
    }
    // "Awkward gap" zone: residual too small for typical mid-size items but not zero.
    if post_residual >= 4 && post_residual <= 12 {
        score += 18.0;
    }

    // Reward tight fits (wasting little of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open, but allow opening a new bin when few are open.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless dead space would be created).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 4 {
            score += 60.0; // still refuse unusable dead space
        }
    }

    // New-bin candidate handling: a fresh empty bin should only win when no open bin
    // gives a good fit. Give it a mild bonus so it beats bad fits, but a penalty so
    // decent existing fits win.
    if bin_residual == bin_capacity {
        score -= 10.0;
        // If the next item could combine with the current one in a fresh bin, boost it.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0;
        }
        // Late in the stream, opening new bins is less costly to hedge.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * progress;
    }

    // Lookahead: if the post-residual exactly accommodates the next item, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If next item fits in the post-residual, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., tighter bins) to keep loose bins available for future large items.
    let dev = mean_residual - post_residual as f64;
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        // Perfect match: post_residual exactly fits next item -> big reward.
        let match_gap = (post - nxt).abs();
        if !is_new_bin {
            score -= 30.0 * (1.0 - match_gap / bin_capacity as f64).max(0.0);
        }
        // Penalize leaving post_residual that is slightly too small for next item
        // (dead space trap), but reward post_residual that can fit it.
        if post < nxt && post > 0.0 {
            score += 15.0 + 0.5 * (nxt - post);
        } else if post >= nxt {
            score -= 10.0;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // --- Relative-to-mean-residual shaping ---
    if !is_new_bin {
        // Prefer bins with residual already below average (consolidating fuller bins),
        // penalize dipping into large-residual bins unnecessarily.
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    } else {
        // Opening a new bin: make it costly unless it's truly necessary.
        // Cost decreases when few bins fit the item (last-chance situations).
        let last_chance = fitting_bins_count <= 1;
        let tight_open_bins = open_bins_count <= 1;
        let mut new_bin_penalty = 40.0;
        if last_chance { new_bin_penalty -= 35.0; }
        if tight_open_bins { new_bin_penalty -= 10.0; }
        // Early in the stream, opening bins is cheaper (build a pool).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty *= (1.0 - 0.5 * progress);
        score += new_bin_penalty;

        // Slight bonus for new bin when next item is huge relative to typical residual.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 8.0;
        }
    }

    // --- Dead-space penalty: small unusable leftovers ---
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Mild tie-breaking: prefer fewer open bins when fitting elsewhere.
    if !is_new_bin && fitting_bins_count > 1 {
        score -= 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill * fill;

    // Penalize small post residuals that cannot hold typical items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // Next item won't fit here; mild penalty proportional to leftover.
            score += 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with below-average residual (more filled bins) to consolidate.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, be more conservative (favor new bins less);
    // late in the stream, squeeze into existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * fill;

    // Discourage opening new bins when many bins are already open and this is an empty-bin candidate.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr_norm = pr / cap ;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm) ;
    let progress_coupling = pr_norm * (0.8 + 2.1 * progress * progress) ;
    score += progress_coupling * cap * 0.5 ;
    // refined dead-zone: steeper early, softer late — targets residual dead space
    let dead_zone = (1.0 - pr_norm) . powi (7) ;
    score += dead_zone * (8.0 + 38.0 * progress) ;
    if post_residual == 0 { score -= 1000.0 ; }
    else if post_residual <= 4 { score -= 260.0 ; }
    else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64 ;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste ;
    }
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0 ;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / post_residual as f64 ;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 } ;
            score -= chain_bonus * fill ;
            let after = post_residual - next_item_size ;
            if after as f64 <= mean_residual { score -= 32.0 ; }
            if after == 0 { score -= 60.0 ; }
            else if after <= 4 { score -= 42.0 ; }
            else if after <= 10 && next_item_size >= after { score -= 25.0 ; }
            if after as f64 > mean_residual * 2.0 { score += 25.0 ; }
            // new: penalize leaving a residual that no typical item can use
            if after as f64 > mean_residual * 1.3 && after > item_size as u32 {
                score += 18.0 * (after as f64 / cap) ;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64 ;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 } ;
            score += near_miss_scale * gap ;
        }
    }
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64 ;
        if tight > 0.92 { score -= 50.0 * tight ; }
        else if tight > 0.75 { score -= 20.0 * tight ; }
        else { score -= 8.0 * tight ; }
    }
    score += 0.3 * (mean_residual - pr) ;
    score += 0.5 * open_bins_count as f64 * pr_norm ;
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 } ;
    score += 12.0 * frag * frag * (0.5 + progress) ;
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap ;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress) ;
        } else {
            score += 15.0 ;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 { score -= 85.0 ; }
        if fitting_bins_count > 2 { score += 10.0 ; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 { score -= 30.0 ; }
        // new: opening a fresh bin for a large item early is cheap; late it is costly
        score += 20.0 * progress * (1.0 - cap_frac) ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits (low post residual), with non-linear penalty on large residuals.
    let mut score = post_norm * (1.0 + 1.5 * post_norm * post_norm);

    // Stream-progress coupling: late in stream, tolerate residual differently —
    // reward tight packing more strongly as we approach the end.
    let progress_coupling = 1.0 + 2.0 * progress * (1.0 - progress);
    score *= progress_coupling;

    // Smooth interaction: residual vs mean residual (prefer bins below/at mean residual,
    // i.e., tighter than average, with smooth quadratic term).
    let mean_norm = mean_residual / cap;
    let diff = post_norm - mean_norm;
    score += 0.35 * diff * diff;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 0.6 + 0.5 * progress;
    }

    // Lookahead: reward if next item fits into post residual (smooth reward).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_slack = post - nxt;
        if fit_slack >= 0.0 {
            score -= 0.4 * (1.0 - fit_slack / cap);
        } else {
            score += 0.15 * (-fit_slack / cap);
        }
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.002 * open_bins_count as f64 * post_norm;

    // New-bin candidate (empty bin): make it unattractive unless residuals are hopeless.
    if bin_residual == bin_capacity {
        score += 1.2 + 0.8 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class 1: perfect fit -> strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class 2: post_residual is an exact divisor class (modulo arithmetic)
    // Treat residuals divisible by 10 as "harmonic" (likely reusable by future items)
    let harmonic = post_residual % 10 == 0 && post_residual > 0;
    if harmonic {
        score -= 40.0;
    }
    // Semi-harmonic: divisible by 5
    else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Integer division thresholds: bucket post_residual into 20-wide bands
    let band = post_residual / 20;
    score += band as f64 * 3.0; // larger residuals mildly penalized (waste potential)

    // Dead-space penalty: residual too small for the minimum item size (1..100, min ~10 typical)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Coupling with next item size: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // extra reward for tight chained fit
            if post_residual - next_item_size < 10 {
                score -= 20.0;
            }
        } else {
            // next item cannot use the leftover: penalize proportionally to leftover
            score += (pr - next_item_size as f64).max(0.0) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): make it attractive only when no good open fit exists.
    if bin_residual == bin_capacity {
        // Base neutral score for a fresh bin
        score = cap - item_size as f64;
        // Prefer new bin if open bins are heavily fragmented
        if fitting_bins_count > 0 {
            let avg_fit_residual = mean_residual;
            if avg_fit_residual < item_size as f64 * 1.3 {
                score -= 30.0; // open bins are tight; open fresh one
            } else {
                score += 20.0; // open bins have room; discourage new bin
            }
        }
        // Late in stream, prefer closing out with new bins less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Fragmentation pressure: many open bins -> prefer filling existing ones
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if this bin's residual is far below mean, it's a tight fit (good)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Harmonic class of item size vs capacity: items that are exact fractions of C
    let ifrac = item_size as f64 / cap;
    if (ifrac * 4.0).round() / 4.0 == ifrac {
        score -= 10.0; // quarter/half-capacity items pack harmonically
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range,
    // but small gaps < ~10 are near-waste) get a strong nonlinear penalty.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Penalize gaps that can't fit the lookahead item but could have fit more.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (post_residual near zero but not wastefully small).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
