    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to pressure and existing usable space.
        score += 40.0 + bin_pressure;
        if mean_residual >= item_size as f64 {
            score += 15.0; // an open bin can already fit; new bin is wasteful
        }
    } else {
        // Slight preference for bins with residuals close to the item (best-fit flavor).
        score += (bin_residual as f64 - item_size as f64) * 0.1;
    }

    // Mild coupling with mean residual: prefer bins whose residual is below average
    // (i.e., closer to being filled) when many bins are open.
    score += (mean_residual - post_residual as f64) * 0.05 * (open_bins_count.min(20) as f64);

    score
}

