        // Mild penalty for leaving a bin very close to empty residual
        // (hard-to-fill sliver) relative to global mean residual.
        if (post_residual as f64) < mean_residual * 0.25 && post_residual > 0 {
            score += 2.0;
        }
        // Prefer bins whose residual is above average when item is small
        // (save tight bins for big items).
        let size_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score += 3.0 * size_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Harmonic residual classes (kept from parent, tuned)
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 40.0;
    } else if post_residual > 0 && post_residual % 5 == 0 {
        score -= 15.0;
    }
    let band = post_residual / 20;
    score += band as f64 * 3.0;

    // Waste penalty when item cannot even leave a usable residual
    if post_residual > 0 && post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead coupling with next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
            if after as f64 <= mean_residual {
                score -= 32.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tightness of placing item into this bin
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.92 {
            score -= 50.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Last-chance bin: strongly prefer filling it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Mean residual deviation: tighter-than-average fit rewarded
    score += 0.3 * (mean_residual - pr);

    // Fragmentation pressure
    score += 0.5 * open_bins_count as f64 * pr_norm;
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // Harmonic item sizes relative to capacity
    let ifrac = item_size as f64 / cap;
    if (ifrac * 4.0).round() / 4.0 == ifrac {
        score -= 10.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        // Big next item with no room in open bins -> open fresh bin
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // Open bins are tight on average -> fresh bin attractive
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 1.3 {
            score -= 30.0;
        }
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    // Early on, prefer filling bins tightly (low post_residual); later, be more
    // tolerant of residual since dead space matters less in the long run.
    let mut score = pr * (1.0 + 0.35 * progress * pr_norm) - 6.0 * progress * pr_norm * (1.0 - pr_norm);

    // Smooth penalty for very small residuals (dead space) via polynomial term.
    score += 8.0 * (1.0 - pr_norm).powi(4) * (1.0 - progress);

    // Lookahead coupling: reward if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = pr - nx;
        if fit_gap >= 0.0 {
            let closeness = 1.0 - (fit_gap / cap);
            score -= 5.0 * closeness * closeness * (0.5 + 0.5 * progress);
        } else {
            score += 2.0 + 0.05 * (-fit_gap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - 0.5 * progress);
    }

    // Mild pressure toward consolidation when many bins are open.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // Nudge toward bins near mean residual for balanced packing.
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize slightly so it's chosen only when it beats
    // genuinely poor fits, more so early in the stream.
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by common item sizes
    // (or by capacity fractions) is "usable" dead space -> reward it.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional harmony: residuals at clean capacity fractions (0, 25, 50, 75)
    // are reusable by typical items.
    for f in [0.0f64, 0.25, 0.5, 0.75] {
        let target = f * cap;
        if (pr - target).abs() < 1e-9 {
            score -= 6.0;
        }
    }

    // Modulo harmony: post_residual divisible by next_item_size means the
    // lookahead item can tile the leftover perfectly.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual % next_item_size == 0 {
            score -= 4.0;
        } else if post_residual >= next_item_size {
            // leftover after hypothetically placing next item
            let r2 = post_residual % next_item_size;
            score -= 2.0 * (1.0 - r2 as f64 / next_item_size as f64);
        }
    }

    // Integer-division threshold classes on post_residual: classify leftover
    // into dead-space buckets. Small leftovers (<10) are near-perfect.
    if post_residual < 10 {
        score -= 8.0;
    } else if post_residual < 20 {
        score -= 3.0;
    } else if post_residual > 60 {
        // large leftover: bin is mostly empty, mild penalty unless it's new
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: opening a bin is expensive unless nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 15.0;
        // If many bins fit the item, opening a new one is usually wasteful.
        if fitting_bins_count > 1 {
            score += 5.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit) beyond raw
    // post_residual: harmonic alignment of bin_residual with item_size.
    if bin_residual > item_size && bin_residual % item_size == 0 {
        score -= 1.5;
    }

    // Penalize creating residual that no plausible item (>=10) can use:
    // dead space in (0, 10) is fine, but residual in [10, item_size) bands
    // that mismatch common sizes is wasted.
    if post_residual > 0 && post_residual < 10 {
        // already rewarded above
    } else if post_residual >= 1 && post_residual < 10 {
        score -= 5.0;
    }

    // Coupling with mean residual: if this bin's residual is far below the
    // mean, it's already crowded -> good to fill it.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
