    if post_residual > 0 && post_residual == item_size { score -= 35.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A residual gap is "dead" if no plausible future item can use it.
    let min_item = 1u32;
    if post_residual < min_item.max(next_item_size) && post_residual > 0 {
        // Unusable gap: heavy penalty, worse the smaller the gap relative to capacity.
        score += 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 8.0 * ((bin_capacity - post_residual) as f64 / bin_capacity as f64).powi(3);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
