    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Keeping room for the next item is valuable.
            score -= 6.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        }
        // If placing here makes next item unable to fit anywhere reasonable, penalize mildly.
        if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // --- Open bins pressure ---
    // Many open bins: discourage opening new bins, encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + 2.0 * pressure;
    } else {
