pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward a residual that exactly matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item fits perfectly here
            score -= 3.0 * (bin_capacity as f64 - diff) / bin_capacity as f64;
        } else {
            // next item won't fit; penalize dead space relative to mean residual
            score += 0.5 * (post_residual as f64 / mean_residual.max(1.0));
        }
        // coupling: if this bin is the only one fitting, it's last chance
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 2.0;
        }
    }

    // prefer tight fits now
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 1.5 * tightness;

    // penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64;
    }

    // slight early-stream exploration bonus
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
