        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let mut penalty = 60.0;
        if fitting_bins_count == 0 {
            penalty = -10.0;
