    // Base: non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * t * t) + 35.0 * norm_pr * norm_pr * (1.0 - t);

    // Reward tight fits more strongly as stream progresses
    score -= 40.0 * fit * fit * (0.5 + t);

