    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);

    // New-bin candidate handling: penalize opening a new bin, more so early
    if bin_residual == bin_capacity {
        score += 55.0 * (1.2 - t) + 10.0 * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worst when it falls in
    // "unusable" residue classes (too small for typical items 1..100).
    let pr = post_residual;
    if pr > 0 {
        // dead-space penalty grows quadratically for tiny residuals
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
        // modulo-class logic: residuals divisible by common item sizes are reusable
        let reusable = (pr % 10 == 0) as i32 as f64
            + (pr % 20 == 0) as i32 as f64
            + (pr % 25 == 0) as i32 as f64
            + (pr % 50 == 0) as i32 as f64;
        score -= reusable * 4.0;
    } else {
        // perfect fill is excellent
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // reward tight fits, penalize leaving awkward classes
            score -= (20.0_f64.min(20.0 - slack as f64 * 0.25)).max(-5.0);
            if slack < 10 {
                score += (10 - slack) as f64 * 2.0; // dead space after next item too
            }
        } else {
            // next item cannot fit here; residual must serve later items
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // but if current best-fit would strand a tiny residual, new bin is attractive
        if pr > 0 && pr < 10 {
            score -= 25.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
        score += (open_bins_count as f64) * 0.5;
    }

    // Tightness reward: filling most of the bin now
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * 10.0;

    // Mean-residual coupling: penalize placing into bins far below mean residual
    // (keeps large residuals concentrated for large future items)
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score += (mean_residual - res_f) * 0.15;
    } else {
        score -= (res_f - mean_residual) * 0.05;
    }

    // Integer-division threshold: prefer post_residual in [50,100) halves over scraps
    if pr >= 50 {
        score -= 5.0;
    } else if pr >= 25 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
