pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space avoidance: post_residual that is too small to be useful
        // (cannot hold even a small item) is heavily penalized.
        if post_residual < 10 {
            score += 250.0;
        } else if post_residual < 20 {
            score += 60.0;
        }

        // Coupling with lookahead: if the next item fits exactly into the
        // post_residual, reward strongly; if next item barely misses, penalize.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 400.0;
            } else if next_item_size > post_residual {
                // post_residual too small for next item -> dead space risk
                score += (post_residual as f64) * 1.5;
            } else {
                // next item fits; prefer leaving a residual close to next size
                score -= (post_residual as f64 - next_item_size as f64).min(50.0) * 2.0;
            }
        }

        // Waste ratio shaping: quadratic penalty on relative waste.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 120.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., existing residuals are large / many fitting bins means poor fit).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 200.0;
        // Pressure from number of open bins: many open bins -> discourage new bin.
        score += open_bins_count as f64 * 15.0;
        // If several bins fit, opening a new one is likely wasteful.
        score += fitting_bins_count as f64 * 80.0;
        // If this is the last chance bin anyway, new bin is less bad.
        if fitting_bins_count == 1 {
            score -= 150.0;
        }
    } else {
        // Mild pressure to consolidate into fewer bins when many are open.
        score += open_bins_count as f64 * 2.0;
        // Prefer bins with residual below mean (tighter packing).
        score -= (mean_residual - bin_residual as f64) * 1.5;
    }

    // Slight early-stream conservatism: keep bins open longer at the start.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        // Item can't be followed by same-size reuse; penalize waste ratio
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Harmonic residuals (divisible by 10/5) are reusable by typical items
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Dead sliver penalty
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling with next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0; // exact chain fit
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
                score -= 32.0;
            }
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        } else {
            // Near miss: penalize gap softly
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tight fit reward based on how well item fills pre-residual
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.92 {
            score -= 50.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Last-chance bin: strongly prefer filling it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Mean residual deviation: tight bins (below mean residual) favored
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Fragmentation pressure scaled by normalized residual
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation quadratic term
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // Harmonic item fractions of capacity
    let ifrac = item_size as f64 / cap;
    if (ifrac * 4.0).round() / 4.0 == ifrac {
        score -= 10.0;
    }

    // New-bin candidate (empty bin)
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        // If next item is large relative to mean residual, opening fresh bin is good
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits snugly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack * 0.15);
    }
    // Penalize leaving space smaller than next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.6;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, unless current bin would waste a lot.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 15.0 + waste * 0.1;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin also good for the next item
        }
    }

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    // Small residuals are nearly dead space; slight extra penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
