    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize dead space that is too small to be useful for typical future items,
    // but reward residuals that could still hold a mid-size item.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0; // unusable sliver
    } else if dead >= 10.0 && dead <= 40.0 {
        score -= 10.0; // reusable window
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty for leaving awkward gap
            score += 5.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Opening a new bin is penalized normally, but less so when open bins are full-ish.
        score += 40.0 * (1.0 - fragmentation);
        if post_residual == bin_capacity - item_size && post_residual <= 20 {
            score -= 25.0; // near-perfect first placement into fresh bin
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    } else {
        // Reward using already-open bins (bin consolidation).
        score -= 8.0;
    }

    // Time horizon: early in the stream, be more selective (higher score for loose fits);
    // late in the stream, just close out bins efficiently.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Slight tie-break noise-free determinism: prefer bins with residual close to mean
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
