    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Penalize divergence from mean residual across open bins
    score += 0.1 * (pr - mean_residual).abs() / cap;

    // Mild pressure against accumulating many open bins early
    score += 0.05 * (open_bins_count as f64) * (1.0 - t);

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * t;
    }

    score
}

