pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: how "usable" is the leftover?
    // Residuals that are multiples of small divisors pair well with common item sizes.
    let pr = post_residual as u32;
    let mut harmony = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmony += 6.0; }
        if pr % 20 == 0 { harmony += 4.0; }
        if pr % 25 == 0 { harmony += 3.0; }
        if pr % 50 == 0 { harmony += 5.0; }
        // dead zones: residuals too small to host typical items
        if pr < 10 { harmony -= 15.0; }
        else if pr < 20 { harmony -= 8.0; }
        else if pr < 30 { harmony -= 3.0; }
    } else {
        // perfect closure is ideal
        harmony += 12.0;
    }
    score -= harmony;

    // Lookahead coupling: does post_residual exactly accommodate the next item?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as f64) >= nxt && (pr as f64) - nxt < 10.0 {
            score -= 10.0; // next item closes this bin nicely
        } else if (pr as f64) == nxt {
            score -= 14.0;
        } else if (pr as f64) < nxt && pr > 0 {
            score += 4.0; // next item won't fit here; leftover likely wasted
        }
        // modulo coupling: next item in same harmonic family
        if next_item_size % 10 == 0 && pr % 10 == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

