    // when open bins are crowded or the fit would be poor anyway.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = (open_bins_count as f64) * 0.7;
        score = cap * (1.0 + 0.25 * progress) + crowding;
        // opening a new bin is attractive if item is large and would leave tiny residue elsewhere
        if item_size >= 70 { score -= 20.0; }
        if item_size <= 20 { score += 15.0; }
