    score -= 0.05 * (cap - post_residual as f64);

    // Penalize divergence from mean residual (keep bin loads balanced)
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Slight preference for bins that are already fairly full
    score += 0.1 * (bin_residual as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
