pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize moderately small gaps that few future items could use.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Lookahead coupling: reward residual that can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item cannot use leftover: dead space risk
            score += 8.0;
        }
    }

    // Last-chance bin: strong bonus to use the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when waste is similar.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate: only attractive when current fit is bad (large post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral base for fresh bin; it becomes attractive if existing bins score poorly.
        score += 15.0;
        if post_residual >= 90 {
            score -= 20.0; // item small relative to capacity
        }
    }

    // Penalize wasting a large residual on a tiny item (bad tightness ratio).
    if bin_residual > item_size * 3 && !is_new_bin {
        score += 10.0;
    }

    // Mild stream-progression tightening: pack harder later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty on large dead space, superlinear to prefer tight fits.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 120.0;

    // Perfect-fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if the next item can exactly fill the post residual,
    // or at least fit tightly into it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            score -= 80.0; // chain completion: next item closes this bin
        } else if post_residual >= next_item_size {
            // next item fits; reward tightness of the follow-up fit
            score -= 40.0 * (1.0 - (post - nxt) / bin_capacity as f64);
        } else {
            // next item cannot fit here -> dead space likely; penalize
            score += 25.0 * (nxt - post) / 100.0;
        }
    }

    // Reward bins whose residual is already below mean (tight bins), penalize loose bins.
    score += (mean_residual - post_residual as f64) * 0.35;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Mild pressure against opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 2.0;
        // But if nothing else fits well, new bin is fine: cancel penalty when item is small
        if item_size <= 25 {
            score -= 20.0;
        }
    }

    // Early in the stream, be more conservative about filling bins loosely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
