pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small residuals are hard to reuse).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward if next item would then leave a near-perfect fill
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // penalize bins that become unusable for the known next item
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (high fit_ratio waste) or when few bins are open.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 20.0 + 15.0 * (1.0 - progress);
        // If many open bins exist with plenty of room, discourage new bins more.
        if mean_residual > item_size as f64 * 1.5 {
            new_bin_score += 10.0;
        }
        // Perfect-fill items justify a fresh bin less often.
        if item_size == bin_capacity {
            new_bin_score -= 60.0;
        }
        score = score.max(0.0) + new_bin_score;
        return score;
    }

    // Mild preference for bins already below average residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Time-horizon coupling: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    // Slight penalty when many bins are open: encourage consolidation.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit -> strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    }

    // Harmonic residuals (divisible by 10 / 5) are reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 40.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Band penalty on large residuals, scaled by progress
    let band = post_residual / 20;
    score += band as f64 * 3.0 * (0.6 + progress);

    // Dead-space sliver
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Tightness of the fit itself
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.92 {
            score -= 50.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Lookahead coupling with next item
    if next_item_size > 0 {
        if next_item_size as f64 == pr {
            score -= 640.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
                score -= 32.0;
            }
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate (empty bin)
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        score = cap - item_size as f64;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if fitting_bins_count > 0 {
            if mean_residual < item_size as f64 * 1.3 {
                score -= 30.0;
            } else {
                score += 20.0;
            }
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        score += progress * 10.0;
    }

    // Fragmentation pressure
    score += open_bins_count as f64 * 1.5 * frac.max(0.05);

    // Mean residual deviation coupling
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Harmonic item fraction of capacity
    let ifrac = item_size as f64 / cap;
    if (ifrac * 4.0).round() / 4.0 == ifrac {
        score -= 10.0;
    }

    // Fragmentation quadratic term
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // Smooth non-linear reward for tight fits (quartic coupling with progress)
    score -= 24.0 * fill.powi(4) * (0.5 + progress);

    // Penalize dead space that no plausible item can use, smoothed polynomial
    let dead = if next_item_size > 0 && pr > next_item_size as f64 { 0.0 } else { 1.0 };
    score += 10.0 * pr_norm.powi(2) * (1.0 + dead);

    // Lookahead coupling: reward leaving room for the next item, smooth kernel
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 8.0 * (-gap / 30.0).powi(2).exp() * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the single fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many bins, coupled to mean residual
    score += 0.05 * open_bins_count as f64 * (1.0 - (mean_residual / cap).powi(2));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residual space into capacity/8 buckets.
    let class_width = bin_capacity / 8;
    let post_class = post_residual / class_width.max(1);
    let next_class = (next_item_size as u32) / class_width.max(1);

    // Reward when post_residual class matches next item class (perfect harmonic pairing).
    if next_item_size > 0 && post_class == next_class && post_residual >= next_item_size as u32 {
        score -= 25.0;
    }

    // Penalize small dead space (waste), reward residual in usable mid-classes.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // tiny unusable sliver
    }
    if post_residual >= 10 && post_residual <= 30 {
        score -= 5.0; // still fillable by small items
    }

    // Integer division threshold: residual divisible into next item's size
    if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual >= next_item_size as u32 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins mildly, unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If item is large, fresh bin is attractive (avoid fragmentation).
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Fraction of capacity: reward tight fills (post_residual small fraction of capacity).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 30.0;

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;
    score -= (bin_residual as f64 - mean_residual).max(0.0) * 0.05;

    // Lookahead: if next item cannot fit post_residual, mild penalty for wasting the pairing.
    if next_item_size > 0 && (post_residual as u32) < next_item_size as u32 {
        score += 8.0;
    }

    // Stream progression: early on, be conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any future item
    // (min item size 1, but typical items larger) are heavily penalized.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 50.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 25.0; // tiny unusable gap -> dead space
    } else if post_residual < 30 {
        score += 8.0;  // marginal gap
    } else {
        // usable residual: reward proportionally to how well next item fits
        if next_item_size > 0 && next_item_size as f64 <= pr {
            score -= 6.0; // this bin can also host the lookahead item
        }
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: penalize opening a new bin when good
    // alternatives exist, but allow it when all open fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of a fresh bin
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual < 15) {
            score -= 45.0; // opening a new bin is justified
        }
    }

    // Mild preference for fuller bins relative to fleet mean residual.
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
