        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 { score -= 85.0 ; }
        if fitting_bins_count > 2 { score += 10.0 ; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 { score -= 30.0 ; }
        if post_residual > 0 {
