    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 6.0; // dead space for the known next item
        }
    }

    // Global state: many open bins -> prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 2.0 * open_pressure.log2().max(0.0);

    // Time horizon: early in the stream, be more willing to open new bins (keep residuals large);
    // late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * fit_ratio;

    // New-bin candidate: open a fresh bin only when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && fit_ratio > 0.6;
        if good_fit_exists || (fitting_bins_count == 1) {
            score += 100.0; // keep item in an existing bin
        } else {
            score += 20.0 * (1.0 - progress); // early stream: new bins are cheap-ish
        }
        // Discourage excessive bin count when residuals are still large on average.
        if mean_residual > 0.5 * bin_capacity as f64 && open_bins_count > 2 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear penalty on small-but-nonzero residuals
    let mut score = pr + 40.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Tight fits rewarded more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= (1.0 + 6.0 * progress) * 25.0 * tightness * tightness * tightness;

    // Interaction: post_residual vs next item lookahead
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 12.0 * (1.0 - (diff / cap).min(1.0)) * (0.5 + progress);
        } else {
            score += 8.0 * (-diff / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus (smoothly scaled by scarcity)
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when bin residual far above mean residual (imbalance)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Slight preference for reusing bins over opening new ones as bins accumulate
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
