pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize into capacity fractions (eighths)
    let eighth = (cap / 8.0).ceil();
    let post_class = (post_residual as f64 / eighth).floor();
    let next_class = (next_item_size as f64 / eighth).floor();

    // Reward if next item exactly fits a harmonic class of post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        // Perfect fill reward (next item closes the bin)
        if gap == 0 {
            score -= 60.0;
        } else {
            // Reward closeness of next item to post_residual, stronger when same class
            score -= 20.0 * (1.0 - gap as f64 / cap);
            if (gap as f64 / eighth).floor() == 0.0 {
                score -= 10.0;
            }
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's remainder: penalize dead space, worse for small residuals
        score += 8.0 + 12.0 * (1.0 - post_residual as f64 / cap);
    }

    // Penalize creating residuals in "awkward" harmonic classes (1/8..3/8 of capacity)
    if post_residual > 0 {
        let frac = post_residual as f64 / cap;
        if frac > 0.125 && frac < 0.375 {
            score += 15.0 * (0.375 - frac);
        }
        // Reward near-full residuals (tight packing)
        if frac < 0.125 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin early or when open bins have large messy residuals
        let mess = (mean_residual - post_residual as f64).abs();
        score = cap * 0.35 + 10.0 * progress + (open_bins_count as f64).sqrt() * 2.0 - mess.min(30.0);
        // If next item is large, a fresh bin is valuable
        if next_item_size > (cap as u32) / 2 {
            score -= 15.0;
        }
    }

    // Mild preference for bins tighter than the mean residual (concentrate filling)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Integer-division threshold: residuals divisible into halves/quarters are reusable
    if post_residual % (bin_capacity / 2) == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % (bin_capacity / 4) == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below min item size 1..=12)
    // are the worst outcome. Penalize post_residual in [1, 12] heavily.
    if post_residual >= 1 && post_residual <= 12 {
        score += 30.0 + (13 - post_residual as f64) * 4.0;
    } else if post_residual > 12 && post_residual < 20 {
        // Moderately risky gap: could fit only tiny items.
        score += 8.0;
    }

    // Reward tight fits (waste < 10) strongly.
    if post_residual < 10 {
        score -= 20.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize spreading out; few bins -> more freedom.
    let pressure = (open_bins_count as f64) / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += pressure * 0.5;

    // Last-chance bin: if this is the only bin that fits, prefer it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the
    // current item would leave a bad gap in every open bin, or the item
    // is large and the lookahead also large (reserve fresh capacity).
    if bin_residual == bin_capacity {
        let gap_bad = post_residual >= 1 && post_residual <= 12;
        let big_pair = item_size >= 50 && next_item_size >= 50;
        if gap_bad || big_pair {
            score -= 25.0;
        } else {
            // Default: prefer reusing open bins.
            score += 12.0 + (open_bins_count as f64) * 0.2;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score -= 12.0;
    }

    // Mild stream progression term: later in the stream, be slightly more
    // conservative about leaving gaps (fewer chances to repair them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: exact fill leaves no dead space.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let match_quality = 1.0 - (post - next) / bin_capacity as f64;
            score -= 120.0 * match_quality * match_quality;
        } else {
            // Next item can't follow into this bin: penalize proportionally to overshoot.
            score += 0.5 * (next - post);
        }
        // Small post_residual that still fits next item is ideal (tight two-item packing).
        if post > 0.0 && next <= post && post - next <= 5.0 {
            score -= 40.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.6 * (post_f - mean_residual).abs().signum() * (post_f - mean_residual);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: make it attractive only when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 25.0;
        // But if item is large relative to capacity, a fresh bin is fine.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 60.0 * frac * frac;
        // Early in stream, opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Mild preference for filling fuller bins.
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64).recip() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Tightness reward: strongly favor small post_residual, non-linearly.
    let tight = 1.0 - pr_norm;
    score -= 40.0 * tight * tight;

    // Exact / near-exact fit bonuses.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    }

    // Penalize dead space: post_residual too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        let scale = if gap <= 8.0 { 0.5 } else { 0.35 };
        score += scale * gap * (1.0 + progress);
    }

    // Reward perfect lookahead fit and strong chain fits.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 640.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size as u32;
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        }
    }

    // Tightness relative to item size.
    if post_residual > 0 && post_residual >= item_size {
        let t = item_size as f64 / pr;
        if t > 0.92 {
            score -= 50.0 * t;
        } else if t > 0.75 {
            score -= 20.0 * t;
        } else {
            score -= 8.0 * t;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate: acceptable early or when open bins are nearly full,
    // penalized when open bins have plenty of room (mean_residual high).
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0 + 30.0 * openness * (1.0 - progress);
        }
        score -= 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild penalty for spreading across many bins late in the stream.
    score += (open_bins_count as f64).ln() * 1.5 * progress;

    // Fragmentation penalty.
    if post_residual > 0 {
        let frag = pr / (pr + item_size as f64);
        score += 12.0 * frag * frag * (0.5 + progress);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr_norm = pr / cap ;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm) ;
    // dead-zone penalty: strongly discourage leaving large leftover late in the stream
    let dead_zone = (1.0 - pr_norm) . powi (6) ;
    score += dead_zone * (10.0 + 42.0 * progress) ;
    score += 0.3 * (mean_residual - pr) ;
    score += 0.5 * open_bins_count as f64 * pr_norm ;
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 } ;
    score += 12.0 * frag * frag * (0.5 + progress) ;

    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 4 {
        score -= 260.0 ;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64 ;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste ;
    }

    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0 ;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / post_residual as f64 ;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 } ;
            score -= chain_bonus * fill ;
            let after = post_residual - next_item_size ;
            if after as f64 <= mean_residual { score -= 32.0 ; }
            if after == 0 { score -= 60.0 ; }
            else if after <= 4 { score -= 42.0 ; }
            else if after <= 10 && next_item_size >= after { score -= 25.0 ; }
            if after as f64 > mean_residual * 2.0 { score += 25.0 ; }
        } else {
            let gap = (next_item_size - post_residual) as f64 ;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 } ;
            score += near_miss_scale * gap ;
        }
    }

    if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
        score += 20.0 ;
    }

    if fitting_bins_count <= 1 && post_residual >= item_size {
        score -= 60.0 ;
    }

    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64 ;
        if tight > 0.92 {
            score -= 50.0 * tight ;
        } else if tight > 0.75 {
            score -= 20.0 * tight ;
        } else {
            score -= 8.0 * tight ;
        }
    }

    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap ;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress) ;
        } else {
            score += 15.0 ;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0 ;
        }
        if fitting_bins_count > 2 { score += 10.0 ; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0 ;
        }
        if post_residual > 0 {
            let dev = ((post_residual as f64 - mean_residual) / (mean_residual + 1.0)).abs () ;
            score += 8.0 * dev ;
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 35.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Dead-space shaping: small-but-nonzero residuals are the least reusable.
    if post_residual > 0 && post_residual <= 12 {
        score += 6.0 * (1.0 - pr / 12.0);
    }

    // Lookahead: reward bins that can also host the next item, penalize those that cannot.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - t * 0.5);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / cap).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating into existing space.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0 * ((mean_residual - item_size as f64) / cap).min(1.0);
    }

    // New-bin candidate: baseline slightly below cap so only genuinely poor fits in open bins lose to it.
    if bin_residual == bin_capacity {
        score = cap - 4.0 - 6.0 * t;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
