    score += 0.6 * open_bins_count as f64 * (mean_residual / cap);

    // Prefer bins whose residual is close to the item (tight fit), smooth form
    let tightness = 1.0 - ((bin_residual as f64 - item_size as f64) / cap).abs();
    score -= tightness * tightness * 8.0;

    // New-bin candidate: penalize opening a new bin unless current residuals are badly fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).abs();
        score += 25.0 - 30.0 * frag;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0;
        }
    }

    score
}

