pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (0, 25, 33, 50, 66, 75) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward residuals that align with common divisor classes (mod 10, mod 25, mod 50)
    let pr_u = post_residual;
    if pr_u % 50 == 0 && pr_u > 0 {
        score -= 12.0;
    } else if pr_u % 25 == 0 && pr_u > 0 {
        score -= 7.0;
    } else if pr_u % 10 == 0 && pr_u > 0 {
        score -= 4.0;
    }

    // Perfect fit is best
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead space penalty: tiny residuals that few item sizes can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score += slack as f64 * 0.3;
            // harmonic class of the double-fit leftover
            if slack % 25 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover; mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer existing bins unless the item is large
    // and current bins are fragmented (mean residual low relative to item size).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so existing decent bins win
        score += 10.0;
        // if open bins are fragmented, opening fresh is attractive
        if (mean_residual < item_size as f64 + 5.0) && open_bins_count > 2 {
            score -= 18.0;
