        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Mild fragmentation pressure: many open bins -> prefer tight fits
    score += (post_residual as f64) * (open_bins_count as f64).ln().max(1.0) * 0.05;

    // Small tie-break on mean residual alignment
    score += (mean_residual - pr).abs() * 0.02;

    score
}

