    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // the lookahead item needs space or current bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let lookahead_pressure = if next_item_size > 0 && next_item_size <= post_residual {
            1.0 // new bin could host next item too
        } else {
            0.0
        };
        // Prefer new bin when open bins are nearly full on average,
        // or when this item leaves a large dead space in existing bins.
        let dead_space_penalty = (post_residual as f64) / 10.0;
        score -= 25.0 * lookahead_pressure + 15.0 * progress - dead_space_penalty;
