        if mean_residual > (item_size as f64) {
            score += 20.0;
        }
        if open_bins_count > 0 && mean_residual > 40.0 {
            score += 25.0;
        }
    }

    // Encourage keeping residuals that can host typical future items.
    if post_residual >= 10 && post_residual <= 50 {
        score -= 5.0;
    }

    // Slight time-varying tightening: later in stream, be greedier.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual - item_size.min(bin_residual)) as f64 * 0.05 * progress;

    score
}

