        // Integer-division thresholds: which "harmonic slots" does the residual fill?
        let quarter = bin_capacity / 4;
        let eighth = bin_capacity / 8;
        let sixteenth = bin_capacity / 16;
        if pr < sixteenth {
            score -= 40.0; // near-perfect: tiny unusable sliver
