            score -= 6.0;
        } else if m == 5 {
            score -= 3.0;
        } else {
            score += (m as f64) * 0.4;
        }
        // Harmonic classes of post_residual relative to capacity fractions
        let class = (pr * 8) / bin_capacity; // 0..7
        score += (7 - class) as f64 * 2.0;
    }

