    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // rather than spreading items out
    let pressure = (open_bins_count as f64).ln() * 3.0;
    score += pressure;

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make opening a new bin costly unless the current bin
    // would leave a very poor fit (large dead space)
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 15.0;
        // But if placing here would waste a lot of space in an existing bin
        // (post_residual tiny but nonzero), opening new bin is relatively better
        if post_residual > 0 && (post_residual as f64) < dead_threshold {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper (need parallel capacity)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Mild tie-break: prefer bins whose residual is already small (tight fit)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Prefer bins where the item fills a large fraction of the residual
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 4.0;
    }

    score
}

