pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr_norm = pr / cap ;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm) ;
    let progress_coupling = pr_norm * (0.8 + 2.1 * progress * progress) ;
    score += progress_coupling * cap * 0.5 ;
    let dead_zone = (1.0 - pr_norm) . powi (6) ;
    score += dead_zone * (10.0 + 42.0 * progress) ;
    if post_residual == 0 { score -= 1000.0 ; }
    else if post_residual <= 4 { score -= 260.0 ; }
    else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64 ;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste ;
    }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 640.0 ; }
