pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (modulo arithmetic on capacity) ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap; // fraction of capacity left as residual

    // Dead-space penalty: residuals that cannot accommodate typical items
    // (harmonic classes: post_residual in [1,9] is nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post) / 10.0;
    }
    // Residuals in 10..=19: usable only for the smallest class of items.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // --- Lookahead coupling: does the next item fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: the residual is a "harmonic partner" for the next item.
            // Reward proportionally to how well it matches (tight chain fit).
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; penalize more when residual is just
            // barely too small (wasted near-fit), less when far too small.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / cap).min(1.0);
        }
    }

    // --- Tightness reward: reward small post_residual in general ---
    score -= 30.0 * (1.0 - post_frac) * (1.0 - post_frac);

    // --- Last-chance logic: this is the only bin that fits the item ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0; // strongly prefer placing here over opening a new bin
    }
    // If many bins fit, mild penalty for consuming a scarce-fit bin unnecessarily
    if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count.min(10) as f64 - 3.0);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin fits well:
        // base cost plus pressure from number of open bins and mean residual.
        let mut nb = 55.0;
        nb += 2.0 * open_bins_count as f64;
        // If mean residual across open bins is large, reusing them is better.
        nb += 0.5 * mean_residual;
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += 20.0 * progress;
        // If the item is huge relative to capacity, a fresh bin is fine.
        nb -= 0.2 * item_size as f64;
        score += nb;
    }

    // --- Integer-division threshold on post_residual: prefer residuals that
    // are clean multiples of common item classes (10, 20, 25, 50) ---
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harshly (dead space 1..=15 is nearly worthless)
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0;
    } else if post_residual > 15 && post_residual <= 30 {
        score += 12.0;
    }

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    }

