    // New-bin candidate: prefer it only when residual would be large enough to be reusable,
    // or when placing in an open bin would leave a tiny dead gap.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened by stream progression
        let progress = step_index as f64 / (total_items.max(1) as f64);
