        score += 55.0 + open_bins_count as f64 * 0.5;
    }

    // Prefer filling fuller bins (waste minimization).
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
