pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 8.0;

    // Penalize dead space that no future item can plausibly fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here: waste grows if post_residual is small.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer packing tight bins.
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual / bin_capacity as f64);
