    // Prefer bins with residual below mean (denser bins) when many bins are open.
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.08 * (open_bins_count as f64).ln().max(1.0);
    }

