        let mut new_bin_cost = 30.0;
        if fitting_bins_count == 0 {
            new_bin_cost -= 25.0; // no alternative anyway
        } else if fitting_bins_count == 1 {
            new_bin_cost -= 10.0; // last chance elsewhere: keep some competition
        }
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_cost -= 5.0; // fresh bin helps future large items
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer low post-residual, with smooth polynomial shaping.
    let mut score = pr;

    // Non-linear coupling: quadratic reward for tight fits, modulated by stream progress.
    let tight = (norm_post - 0.5) * (norm_post - 0.5);
    score += 60.0 * tight * (1.0 + progress);

    // Cubic term: strong penalty for mid-range residual, favoring near-zero or well-used space.
    let cubic = norm_post * norm_post * norm_post;
    score -= 40.0 * cubic * (0.5 + progress);

    // Penalize opening new bins early; encourage reuse as stream progresses.
    if bin_residual == bin_capacity {
        score += 25.0 + 60.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Mean-residual coupling: prefer bins deviating from mean residual to preserve diversity.
    score += 5.0 * (pr - mean_residual).abs() / cap * (1.0 - progress);

    // Small polynomial noise-free regularizer based on bin count pressure.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
    score += 10.0 * pressure * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers divisible into small
    // classes (<= 10) are near-perfect fits; large leftovers waste capacity.
    let leftover_class = post_residual / 10;
    match leftover_class {
        0 => score -= 30.0,                       // near-perfect fit
        1 => score -= 18.0,                       // good
        2 => score -= 8.0,                        // decent
        3 => score -= 2.0,                        // neutral
        4 => score += 6.0,                        // wasteful
        _ => score += 12.0,                       // very wasteful
    }

    // Modulo structure: leftover that is a multiple of 10 can host many
    // future item sizes exactly -> reward divisibility of post_residual.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 10.0;
    }
    // Leftover divisible by 5 is also flexible.
    if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a chained perfect fit -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after that placement matters
            let chained = post_residual - next_item_size;
            score -= 12.0 - (chained as f64) * 0.15;
            if chained <= 5 {
                score -= 8.0; // near-exact chain
            }
        } else {
            // next item cannot reuse this leftover; penalize large stranded space
            let stranded = post_residual as f64;
            if stranded > 20.0 {
                score += (stranded - 20.0) * 0.3;
            }
        }
    }

    // Integer-division threshold on item_size: large items (>50) should
    // preferentially go into bins with large residuals (pairing logic).
    let item_class = item_size / 20; // 0..4
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score -= item_class as f64 * residual_frac * 8.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 40 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when no good fit
    // exists among open bins. Base it on mean residual pressure.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If open bins are mostly full (low mean residual), a fresh bin is fine;
        // otherwise discourage opening a new bin when fitting bins exist.
        if fitting_bins_count > 0 {
            score += 25.0 * (1.0 - pressure);
        } else {
            score -= 5.0;
        }
        // Late in the stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Slight preference for fuller bins overall (best-fit bias).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Tie-break: fewer open bins is better (bin consolidation).
    score += open_bins_count as f64 * 0.01;

    score
}

