pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap that no plausible future item (>= 1) can use well is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Prefer bins whose residual is close to mean residual (balanced packing),
    // slightly penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size && (post_residual - next_item_size) < 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate: opening a new bin should only win when fits elsewhere are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins already fit the item.
        score += 45.0 + 20.0 * (fitting_bins_count as f64);
        // Late in the stream, opening new bins is more acceptable (less future to waste).
        score -= 30.0 * progress;
        // If next item is large and current fits are poor, new bin may be better.
        if next_item_size > 60 && post_residual < 20 && bin_residual == bin_capacity {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr_norm = pr / cap ;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm) ;
    score += 6.0 * pr_norm * pr_norm * cap ;
    let dead_zone = (1.0 - pr_norm) . powi (6) ;
    score += dead_zone * (10.0 + 42.0 * progress) ;
    if post_residual == 0 { score -= 1000.0 ; }
    else if post_residual <= 4 { score -= 260.0 ; }
    else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64 ;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste ;
    }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 640.0 ; }
        else if next_item_size < post_residual {
            let fill = next_item_size as f64 / post_residual as f64 ;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 } ;
            score -= chain_bonus * fill ;
            let after = post_residual - next_item_size ;
            if after as f64 <= mean_residual { score -= 32.0 ; }
            if after == 0 { score -= 60.0 ; }
            else if after <= 4 { score -= 42.0 ; }
            else if after <= 10 && next_item_size >= after { score -= 25.0 ; }
            if after as f64 > mean_residual * 2.0 { score += 25.0 ; }
        } else {
            let gap = (next_item_size - post_residual) as f64 ;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 } ;
            score += near_miss_scale * gap ;
        }
    }
    if post_residual > 0 && post_residual < 12 && next_item_size > post_residual { score += 20.0 ; }
    if fitting_bins_count <= 1 && post_residual >= item_size { score -= 60.0 ; }
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64 ;
        if tight > 0.92 { score -= 50.0 * tight ; }
        else if tight > 0.75 { score -= 20.0 * tight ; }
        else { score -= 8.0 * tight ; }
    }
    if post_residual > 0 {
        let dev = ((pr - mean_residual) / (mean_residual + 1.0)) . abs () ;
        score += 8.0 * dev * (0.5 + progress) ;
    }
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap ;
        if cap_frac > 0.7 { score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress) ; }
