        if fitting_bins_count > 2 { score += 10.0 ; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 { score -= 30.0 ; }
    }
    if post_residual > 0 && post_residual == item_size { score -= 35.0 ; }
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 > mean_residual * 2.0 { score += 25.0 ; }
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 } ;
    score += 12.0 * frag * frag * (0.5 + progress) ;
    score += 0.3 * (mean_residual - pr) ;
    score += 0.5 * open_bins_count as f64 * pr_norm ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nx).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect 2-step match
        } else if pr >= nx {
            score -= 30.0 * (1.0 - diff / bin_capacity as f64); // next item still fits
        } else {
            score += 10.0 + diff; // dead space relative to lookahead
        }
    }

    // Penalize small unusable residuals (dead space) unless perfectly matched.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Mild pressure to open new bins when many bins are open and residual is large.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Reward bins whose post_residual exactly accommodates the next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Reward leaving room for large upcoming items.
        score += 0.05 * next_item_size as f64 * (post_residual as f64 / bin_capacity as f64);
    } else {
        // Last item: prefer the emptiest bin to keep waste minimal.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Mild spread penalty: many fitting bins means flexibility is high.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Penalize bins far above/below the mean residual to consolidate similar bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev * dev;

    // Time horizon: early in stream, be conservative (favor balanced fills);
    // late in stream, squeeze aggressively into tight bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 25.0 * progress * fit_ratio;

    // When many bins are open, discourage opening new ones; the new-bin candidate
    // (bin_residual == bin_capacity) gets penalized so it only wins on true misfits.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But allow a new bin when the item barely fits nowhere well.
        if fit_ratio > 0.9 && fitting_bins_count <= 1 {
            score -= 60.0;
        }
    }

    // Small global pressure: fewer open bins is better, mildly reward packing
    // into existing bins when congestion is high.
    score += 0.02 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);

    score
}

