}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    let mut score = pr * (1.0 + 0.8 * progress * poly * 4.0);

    // Penalize large dead space more aggressively as stream progresses (smooth cubic)
    score += progress * pr_norm * pr_norm * pr_norm * 30.0;

    // Reward tight fits (small post residual) with smooth exponential falloff
    score -= (1.0 - progress) * (1.0 - pr_norm) * 6.0;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty scaled by wasted potential
        score += 3.0 * pr_norm;
    }

    // Mean residual alignment: prefer bins near the mean (smooth quadratic)
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Mild penalty for spreading across many open bins early on
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // New-bin candidate: only attractive when existing bins would leave bad dead space
    if bin_residual == bin_capacity {
        score = pr + 10.0 + 20.0 * progress * pr_norm;
    }

    score
}

