pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: residual divisible by common item sizes (10/20/25/50)
    // keeps residual "reusable" by typical item sizes -> reward.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
            if post_residual % 20 == 0 {
                score -= 4.0;
            }
            if post_residual % 50 == 0 {
                score -= 6.0;
            }
        }
        if post_residual % 25 == 0 {
            score -= 5.0;
        }
    }

    // Dead-space penalty: tiny unusable leftovers (1..=9) are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // this is a chain fit -> big reward; if next item cannot use post residual
    // at all, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer tighter bins when many are open (best-fit bias).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Mild preference for reusing bins over opening new ones as stream matures.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening unless current fit is bad.
        score += 15.0 + 0.05 * (open_bins_count as f64);
        if post_residual as f64 > mean_residual {
            score += 10.0;
