}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items are "dead space". Penalize small nonzero post_residual hard.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable gap
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            score -= 10.0; // large usable leftover is good
        }
    } else {
        // perfect fit: strongly reward
        score -= 80.0;
    }

    // Prefer bins whose residual is close to item size (tight fit)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Open-bin pressure: with many open bins, avoid spreading; favor filling
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a
    // very poor fit (large post_residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 2.0;
        if post_residual >= item_size as u32 {
            // empty bin trivially satisfies; keep penalty high
            score += 10.0;
        }
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // blocking next item into dead space
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Tightness reward, non-linear (borrowed dead-zone idea from best).
    let tight = 1.0 - pr_norm;
    let dead_zone = tight.powi(6);
    score -= 40.0 * tight * tight;
    score -= dead_zone * (10.0 + 42.0 * progress);

    // Exact / near-exact fit bonuses.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead chain logic.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if (next_item_size as u64) < (post_residual as u64) {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
                score -= 32.0;
            }
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Dead-space penalty: residual too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_ratio = (next_item_size as f64 - pr) / cap;
        score += 20.0 * waste_ratio * cap * (0.5 + progress);
    }

    // Tightness relative to the placed item.
    if post_residual > 0 && post_residual >= item_size {
        let tight_i = item_size as f64 / pr;
        if tight_i > 0.92 {
            score -= 50.0 * tight_i;
        } else if tight_i > 0.75 {
            score -= 20.0 * tight_i;
        } else {
            score -= 8.0 * tight_i;
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0 + 30.0 * openness * (1.0 - progress);
        }
        score -= 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Spread / fragmentation penalties.
    score += (open_bins_count as f64).ln() * 1.5 * progress;
    score += 0.5 * open_bins_count as f64 * pr_norm;
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Strongly discourage opening a new bin unless it's the only option.
        score += 60.0;
        // If this bin is the last chance among open bins, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        // Lookahead: if next item would fit nicely in the fresh bin's post residual,
        // opening a new bin gains value.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        }
        // Late in the stream, new bins are less useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // 2-step lookahead matching: perfect match of next item into post residual.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 45.0; // perfect chain fit
            } else if post_residual > next_item_size {
                let slack = (post_residual - next_item_size) as f64;
                // reward proportional to tightness of the follow-up fit
                score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            } else {
                // next item won't fit here; penalize relative to overshoot
                let over = (next_item_size - post_residual) as f64;
                score += 0.3 * over;
            }
        } else {
            // last item: prefer minimal post residual
            score -= 10.0;
        }

        // Reward using bins with below-average residual (fill emptier space wisely),
        // penalize consuming scarce residual when other bins are roomier.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 0.1 * ((post_residual as f64) - mean_residual);
        }

        // Last-chance bonus: if this is the only fitting bin, use it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }

        // Penalize creating dead space that no plausible item (>=1) can use.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: favor bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 4.0;
        }
        // Penalize leaving a gap that neither this item nor next fits well
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when open bins are crowded or the item is large
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = mean_residual / bin_capacity as f64;
        // Prefer new bin when mean residual across open bins is low (all bins tight)
        score += 35.0 + 20.0 * crowding - 15.0 * progress - (item_size as f64 / bin_capacity as f64) * 10.0;
        // Encourage opening a fresh bin for large items that would leave slivers
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0;
        }
    }

    // Mild penalty for scattering across many bins when mean residual is high
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 2.0 * (1.0 - mean_residual / bin_capacity as f64);
    }

    // Slight time-horizon adaptation: later in stream, prefer consolidation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
