    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 + progress * (1.0 - progress) * 4.0);
    score += 6.0 * coupling * coupling;

    // Penalize small dead space that wastes capacity; reward tight fits
    if pr > 0.0 {
        score += 12.0 / pr.sqrt();
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (1.0 - ((pr - nxt) / cap).abs()) * (1.0 + progress);
        } else {
            score += 3.0 * (nxt / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses
    score -= 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
