pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is the best possible outcome.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic reward: tighter fits (small post_residual) get large bonuses.
        score -= 40.0 / post_residual as f64;

        // Modulo-10 harmonic class: residuals in "round" classes are more reusable
        // by future items; odd/awkward classes get a small penalty.
        let cls = post_residual % 10;
        score += cls as f64 * 0.6;

        // Integer-division thresholds: classify residual into coarse buckets.
        let bucket = post_residual / 10;
        score += bucket as f64 * 1.5;

        // Lookahead coupling: reward residuals that can host the next item,
        // penalize residuals that strand dead space relative to it.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 6.0;
            } else {
                score += (next_item_size - post_residual) as f64 * 0.35;
            }
        }

        // Dead space: residual below the smallest possible item (1) is impossible,
        // but residuals below a practical minimum are nearly dead.
        if post_residual < 3 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): it should only win when
    // existing fits are poor, so add a fixed opening penalty.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Never open a new bin when this is the only fitting option.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Fraction-of-capacity residual term: large leftover fractions are wasteful.
    score += (post_residual as f64 / bin_capacity as f64) * 12.0;

    // Coupling with mean residual: placing into a bin far below the mean residual
    // balances the pool of open bins.
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // Mild pressure to close out many open bins.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

