    // Align with global state: bins far below mean residual are less
    // attractive targets (keep residuals balanced across open bins).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Late-stream tightening: as the stream progresses, waste becomes
    // harder to amortize, so penalize leftover space slightly more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

