            score -= 50.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Mean residual coupling: prefer tighter bins
    score += 0.3 * (mean_residual - pr);

    // Open-bin consolidation pressure
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation penalty grows with progress
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // New-bin candidate decision
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Last-chance bin bonus retained from parent
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space: post_residual that is too small to hold typical future items.
    if post_residual < 10 {
        score += 15.0; // near-perfect fit is fine, but tiny residue is wasted
    } else if post_residual < 20 {
        score += 5.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item nearly fills the leftover too.
        let next_fill = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * next_fill;
    }
    // If next item cannot fit here, slight penalty proportional to leftover waste.
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 40.0;
        // If few bins fit the item, opening a new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If open bins have large mean residual, prefer using them.
        score += mean_residual * 0.2;
        // Opening new bin is better if item is large (hard to fit later).
        score -= item_size as f64 * 0.15;
    }

    // Prefer bins whose residual is below the mean (consolidate fuller bins first).
    let residual_diff = mean_residual - bin_residual as f64;
    score += 0.1 * residual_diff;

    // Mild penalty for having many open bins already (encourage packing into fewer bins).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 2.0 * t * t + 1.5 * t * t * t * t;
    score += 0.05 * pr * pr / cap * poly;

    // Reward tight fits, stronger later in the stream
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space relative to mean residual (wasted capacity)
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + t);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (1.0 - (pr - nx) / cap) * (0.3 + 0.7 * t);
        } else {
            score += 3.0 * (nx - pr) / cap * (0.3 + 0.7 * t);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.02 * open_bins_count as f64 * t;

    // New-bin candidate: prefer opening a fresh bin early, penalize late
    if bin_residual == bin_capacity {
        score += 6.0 * t - 3.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it fall into?
    // Bands: (0,10], (10,25], (25,50], (50,100] — smaller bands are more "dead".
    let band = if post_residual == 0 { 0.0 }
        else if post_residual <= 10 { 1.0 }
        else if post_residual <= 25 { 2.0 }
        else if post_residual <= 50 { 3.0 }
        else { 4.0 };

    // Dead-space penalty: residual too small for the smallest plausible item (>=1) is worst;
    // residual below next_item_size is likely unusable for the lookahead item.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64) / 10.0; // tiny slivers
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward placements that leave a residual in a "usable harmonic class"
    // (divisible-friendly chunks: exact zero, or >= next item so lookahead still fits).
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * post_residual as f64;
    }

    // Modulo-style coupling: residuals near multiples of common item sizes are reusable.
    let r = post_residual as f64;
    let mut reuse_bonus = 0.0;
    for m in [10u32, 20, 25, 50] {
        let d = (r - m as f64).abs();
        if d <= 5.0 { reuse_bonus += 8.0 * (1.0 - d / 5.0); }
    }
    score -= reuse_bonus;

    // Band-based tilt: prefer filling high-fragmentation bins (small band) when several fit.
    score += band * (fitting_bins_count as f64).max(1.0).log2() * 3.0;

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish base, but discourage when the item fits an open bin
    // with decent post-residual (>= next_item_size), encourage when all fits are bad.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.1 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 10.0; }
        // early stream: opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Mild tie-break toward bins with residual close to item (tight fit).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);
    let progress_coupling = pr_norm * (0.8 + 2.1 * progress * progress);
    score += progress_coupling * cap * 0.5;
    let dead_zone = (1.0 - pr_norm).powi(6);
    score += dead_zone * (10.0 + 42.0 * progress);
    // new: penalize dead space relative to remaining stream volume
    let remaining = (total_items - step_index).max(1) as f64;
    let dead_ratio = pr / (pr + item);
    score += dead_ratio * dead_ratio * (6.0 + 18.0 * (1.0 - remaining / total_items.max(1) as f64));

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 640.0;
        } else if next_item_size < post_residual {
            let fill = nxt / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
                score -= 32.0;
            }
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        } else {
            let gap = nxt - pr;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
            // lookahead: if gap is small and next item likely to fit elsewhere, mild penalty
            if gap <= 3.0 {
                score += 12.0;
            }
        }
    }

    if post_residual > 0 && post_residual >= item_size {
        let tight = item / pr;
        if tight > 0.92 {
            score -= 50.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    score += 0.3 * (mean_residual - pr);
    score += 0.5 * open_bins_count as f64 * pr_norm;
    let frag = if post_residual > 0 { pr / (pr + item) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    if bin_residual == bin_capacity {
        let cap_frac = item / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // refine: open new bin preferentially for large items early when open bins are fragmented
        let avg_open_res = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if cap_frac > 0.5 && avg_open_res < item * 1.3 && fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (gaps that few items can fill).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Zero residual is a perfect fit: heavy reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still host a typical next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize when post_residual is just barely below next item (awkward gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let pressure = open_bins_count as f64 * 0.8;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when current bins are tight.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when justified.
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        } else if mean_residual < item_size as f64 * 1.5 {
            score -= 30.0; // existing bins are poor fits anyway
        }
    }

    // Slight progression tilt: later in stream, prefer tighter packing.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 800.0; // next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            // next item still fits; reward tight coupling, penalize large leftovers
            let slack = pr - nxt;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
            score += 0.5 * slack;
        } else {
            // next item cannot fit here; penalize proportional to unusable gap
            let gap = nxt - pr;
            score += 1.5 * gap;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 2.0 * (pr - mean_residual);
    }

    // Penalize leaving small unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: keep it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin still supports lookahead
        }
    }

    // Early stream: be slightly more conservative (keep flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
