pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight superlinearity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Dead-space penalty: residual too small for ANY future item (min size 1 => use 1..=100 unknown;
    // treat residual < next_item_size as likely dead for the lookahead)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // this bin cannot host the lookahead item -> penalize proportionally
            score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else {
            // lookahead fits: reward, more so if the fit is snug
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / (bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else. New bin has post_residual == capacity - item_size.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening a new bin by default
        score += 15.0;
        // but if existing bins would leave huge post_residual, new bin becomes relatively OK
        let waste_elsewhere = mean_residual - item_size as f64;
        if waste_elsewhere > 0.0 {
            score -= 0.5 * waste_elsewhere.min(50.0);
        }
        // early in the stream, having a fresh bin is cheap; later it is costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // many open bins -> discourage yet another one
        score += 1.5 * open_bins_count as f64;
    } else {
        // reusing an open bin reduces bin count; reward more when many bins are open
        score -= 1.0 + 0.2 * open_bins_count as f64;
        // reward using bins whose residual is far above the mean (drain large-residual bins)
        let diff = bin_residual as f64 - mean_residual;
        score -= 0.15 * diff;
    }

    // Global pressure: when mean residual is high, prefer consolidating into fullest bins
    if mean_residual > 0.0 {
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fill_ratio * (mean_residual / bin_capacity as f64);
    }

    // Time-horizon modulation: late in the stream, prioritize minimizing bins now (tight fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
