pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;
    let next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 + progress * 2.0);
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= progress * 20.0 * fit_ratio * fit_ratio;

    // Penalize residuals that cannot host the lookahead item (smooth logistic-like term)
    let gap = next - norm_pr;
