    }

    // Slight preference for consolidating when many bins are open
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // Deviation from mean residual: prefer bins near/below mean residual usage
    score += 0.1 * (mean_residual - pr).abs();

    // New-bin candidate: penalize mildly unless current fits are poor
    if bin_residual == bin_capacity {
