pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common
    // item sizes are more reusable. Classify post_residual into "good"
    // classes via modulo arithmetic on small integers.
    let pr = post_residual;
    let mut reusability = 0.0f64;
    for m in [10u32, 20, 25, 50, 100].iter() {
        if pr % m == 0 && pr > 0 {
            reusability += 6.0;
        }
    }
    // Fine-grained divisibility bonus
    if pr % 5 == 0 { reusability += 2.0; }
    score -= reusability;

    // Penalize dead space in awkward classes (post_residual not expressible
    // as sum of typical item sizes): quadratic penalty on large leftovers.
    if pr > 0 && pr < 10 {
        score += 40.0; // tiny unusable sliver
    } else if pr > 0 && pr < 30 {
        score += (30 - pr) as f64 * 0.8;
    }

    // Perfect fit is ideal
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
            // harmonic class match between leftover and next item
            if post_residual % 10 == 0 && next_item_size % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // leftover too small for next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we prefer reusing
    // open bins, unless residuals are all large/wasteful.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If open bins are heavily fragmented (mean residual small relative
        // to item), opening fresh is fine.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 45.0;
