    // Prefer bins whose residual is close to the item (tight fit) beyond
    // raw post_residual ordering: reward small relative waste.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 20.0;

    // Prefer filling bins with lower mean residual among many open bins
    // (keeps a diverse residual portfolio).
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

