    // but practically gaps < 10 are near-dead; gaps < next_item_size are dead for lookahead).
    if post_residual < 10 {
        score += 40.0; // near-dead gap
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
