    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * (1.0 - progress) * 2.0;

    // New-bin candidate handling: baseline attractiveness depends on how bad existing fits are.
    if bin_residual == bin_capacity {
