pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover divides the capacity
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward post_residuals that belong to "useful" harmonic classes:
    // multiples of small divisors (e.g. 10, 20, 25, 50) are easier to fill later.
    let useful = if post_residual == 0 {
        3.0
    } else if post_residual % 50 == 0 {
        2.5
    } else if post_residual % 25 == 0 {
        2.0
    } else if post_residual % 20 == 0 {
        1.8
    } else if post_residual % 10 == 0 {
        1.5
    } else if post_residual % 5 == 0 {
        1.2
    } else {
        0.0
    };
    score -= useful;

    // Penalize dead space: leftover too small for typical items (1..100 unknown,
    // but small leftovers < 10 are nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Coupling with next item: reward if next item fits exactly or nearly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect lookahead fit
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post.max(1.0));
        } else {
            // leftover smaller than next item: penalize proportionally to waste
            score += 3.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly discourage opening new bins unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64) / (mean_residual.max(1.0) / cap);
        score += 12.0 + 10.0 * progress - 2.0 * crowded.min(5.0);
        // but if this bin is the only fit and residual would be tiny, allow it
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.7 {
        score -= 4.0;
    }

    // Mean residual alignment: prefer bins whose residual is close to the mean
    // (keeps bin states homogeneous, easier to combine later)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Integer-division threshold: classify post_residual into capacity-eighths
    let eighth = post_residual * 8 / bin_capacity;
    score -= match eighth {
        0 => 4.0,   // nearly full bin: excellent
        1 => 3.0,
        2 => 2.0,
        3 => 1.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items . max (1) as f64 ;
