    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    score += open_bins_count as f64 * 0.4;

    // Prefer bins tighter than the mean residual (better fill harmony).
    score += (post - mean_residual) * 0.5;

