    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // New-bin candidate logic: attract only for large items with few fitting bins
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // Waste-aware new-bin gate: avoid opening bins for small items late
        if cap_frac < 0.35 && progress > 0.7 && fitting_bins_count >= 1 {
            score += 40.0;
        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New: penalize residual much larger than next item (dead space for the chain)
    if next_item_size > 0 && post_residual > 0 {
        let slack = pr - next_item_size as f64;
        if slack > 0.0 && slack > mean_residual {
            score += 0.12 * slack;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact/near match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match for the next item is a huge reward.
        if post_residual == next_item_size {
            score -= 200.0;
        } else {
            // Penalize proportionally to how far post_residual is from next_item_size.
            score += diff * 0.8;
            // If next item cannot fit here but could fit if we leave more room, mild penalty.
            if next_item_size > post_residual {
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
        // Bonus if this bin plus next item fills the bin almost perfectly (>= 95% total).
        let two_step_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if two_step_fill >= 0.95 && post_residual <= next_item_size {
            score -= 120.0;
        }
    }

    // Prefer bins whose residual is tight relative to the mean residual (good fits).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Penalize creating large unusable dead space (nothing small may fit later).
    if post_residual > 0 && post_residual < 10 {
        score -= 30.0; // near-perfect fill
    }
    if post_residual > 40 {
        score += 15.0; // large leftover is wasteful unless matched by lookahead
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Late in the stream, consolidate: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: cost grows with progress and with number of open bins.
        score += 40.0 + 80.0 * progress + 2.0 * open_bins_count as f64;
        // But if no open bin fits well (post_residual large), opening new bin is fine.
        if next_item_size > 0 && post_residual > next_item_size as f64 * 1.5 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Progress-coupled residual weight: later in stream, prefer fuller bins
    score += pr_norm * (0.8 + 2.1 * progress * progress) * cap * 0.5;

    // Dead-space avoidance with progress-scaled dead zone (sharpened)
    let dead_zone = (1.0 - pr_norm).powi(7);
    score += dead_zone * (10.0 + 46.0 * progress);

    // Exact fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead chain bonus (refined with two-step anticipation)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual { score -= 32.0; }
            if after == 0 { score -= 60.0; }
            else if after <= 4 { score -= 42.0; }
            else if after <= 10 && next_item_size >= after { score -= 25.0; }
            else if after as u32 == next_item_size { score -= 18.0; } // perfect split -> repeatable
            if after as f64 > mean_residual * 2.0 { score += 25.0; }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tight-fit reward relative to item size
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.92 { score -= 50.0 * tight; }
        else if tight > 0.75 { score -= 20.0 * tight; }
        else { score -= 8.0 * tight; }
    }

    // Mean residual coupling: prefer tighter-than-mean bins, scaled by spread
    let spread = (mean_residual.max(1.0) * 0.2626).max(2.0); // residual variance proxy
    let dev = (mean_residual - pr) / spread;
    score += 0.3 * (mean_residual - pr) + 6.0 * dev.tanh();

    // Open-bin pressure scaled by how empty the bin is
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation penalty, stronger late in stream
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // New-bin candidate logic: attract only for large items with few fitting bins
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // Avoid opening a bin that would strand a large residual when the
        // item fits an open bin nearly exactly
        if fitting_bins_count >= 1 {
            let best_possible = item_size as f64;
            if best_possible / cap > 0.85 && progress > 0.5 {
                score += 12.0;
            }
        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Late-stream hoarding: keep large residuals available when many small items remain
    let remaining = (total_items - step_index) as f64;
    if remaining > 0.0 && pr > 0.0 {
        let small_left = next_item_size as f64 <= pr && next_item_size > 0;
        if small_left && remaining / total_items.max(1) as f64 > 0.3 {
            score += 4.0 * (pr / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progression through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual near zero gets a strong bonus
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * tightness * tightness; // quadratic penalty for wasted space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement is excellent; if next item almost fits, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 30.0; // chain of perfect fits
            } else {
                score += 0.1 * slack;
            }
        } else {
            // next item won't fit here regardless; prefer smaller post_residual
            score += 0.05 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Global state: penalize placements into bins whose residual deviates far
    // from the mean residual (keeps the pool of usable residuals homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Early in the stream, prefer spreading items across bins (keep residuals
    // flexible); later, prefer consolidating into fewer bins.
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Many open bins with high mean residual -> encourage filling existing bins
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0;
    }

    // New-bin candidate: only attractive when no decent alternative exists,
    // i.e., when this empty-bin call would otherwise waste a lot of space elsewhere
    if bin_residual == bin_capacity {
        // Opening a new bin is a fresh 100 residual; make it costly but competitive
        // when the item fits poorly in every open bin (post_residual large there).
        score += 20.0 + 0.2 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 25.0; // opening a new bin is fine when alternatives are scarce
        }
    }

    score
}

