pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space decays as it gets smaller
    let class_size = bin_capacity / 5; // classes: (0..20],(20..40],(40..60],(60..80],(80..100]
    let post_class = post_residual / class_size;
    let class_penalty = match post_class {
        0 => -18.0, // tiny residue: near-perfect fit
        1 => -6.0,
        2 => 0.0,
        3 => 5.0,
        _ => 12.0, // huge residue: wasteful placement
    };
    score += class_penalty;

    // Exact-fill reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item can fit into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty, worse if residue is medium-sized
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a new bin only when current fits are poor
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = 55.0;
        // cheap items leave room; slightly encourage new bin for tiny items
        score -= (item_size as f64) * 0.2;
        // many open bins with high mean residual -> prefer packing into existing ones
        score += open_bins_count as f64 * 0.5 + mean_residual * 0.15;
        // lookahead: if next item is large, a fresh bin is valuable
        if next_item_size > 0 {
            score -= (next_item_size as f64) * 0.25;
        }
    }

    // Modulo arithmetic on post_residual: residues divisible by small classes are more reusable
    if post_residual % 10 == 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    }

    // Integer-division threshold: post_residual divisible by next item's class is good
    if next_item_size > 0 {
        let next_class = (next_item_size / class_size).max(1);
        if post_residual / next_class >= 1 && post_residual % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
    }

    // Progression: tighten tolerance as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

