    // Harmonic class of post_residual: dead space quality depends on modulo classes
    let pr = post_residual;
    let m10 = pr % 10;
    let m25 = pr % 25;

    // Perfect fit: huge reward
    if pr == 0 {
        score -= 1000.0;
    }
    // Post-residual that is itself a common small-item size class (10,20,25,50) is reusable
    if pr == 10 || pr == 20 || pr == 25 || pr == 50 {
        score -= 60.0;
    }
    // Dead space: unusable residue below smallest item (1..=9) is worthless
    if pr >= 1 && pr <= 9 {
        score += 45.0;
    }
    // Awkward mid classes (11..=19 not multiples of 5) are hard to fill
    if pr >= 11 && pr <= 19 && m10 != 0 {
        score += 18.0;
    }
    // Class of 5s: multiples of 5 are decent
    if m10 == 5 && pr > 5 {
        score -= 8.0;
    }
    // Quarter classes relative to capacity
    if m25 == 0 && pr > 25 {
        score -= 12.0;
    }

    // Tightness reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.8 {
        score -= 30.0 * (fill - 0.8);
    } else if fill < 0.3 {
        score += 15.0 * (0.3 - fill);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be wrecked
    if bin_residual == bin_capacity {
        // Prefer new bin only if no open bin fits well and item is large
        let pressure = (open_bins_count as f64) * 0.5;
        score += 70.0 - pressure;
        if item_size > 60 {
            score -= 25.0;
        }
    } else {
        // Mildly prefer reusing existing bins as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 90.0;
        } else if next_item_size <= pr {
            // next item fits: residual class quality matters less
            score -= 10.0;
        } else {
            // next item won't fit here: leftover should be a harmonic class
            score += 6.0;
        }
    }

    // Alignment with mean residual: prefer bins near the mean to keep balance
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    score
}

