    let fit_ratio = item / cap;                       // how much of the bin the item consumes
    let tightness = 1.0 - (post / cap);               // 1.0 = perfect fill now

    // Base: reward consuming more of the bin's space (lower score for tight fits)
    let mut score = cap - post;

    // Strong reward for very tight fits (post_residual near 0)
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: small leftovers that are hard to reuse later.
    // A leftover is "dead" if it's small relative to typical item sizes.
    let dead_threshold = 20.0;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 2.5;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // reward leaving space usable by the next item, scaled by how well it fits
            let lookahead_fit = 1.0 - ((post - nxt) / cap);
            score -= 25.0 * lookahead_fit;
        } else {
            // next item won't fit in the leftover: mild penalty for wasting the gap
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the current item
    // is large and would leave a very awkward residual everywhere else.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = cap * 0.9;
        // if no open bin fits (fitting_bins_count==0 means only the new bin was called),
        // this is mandatory: make it attractive
        if fitting_bins_count == 0 {
            score -= 200.0;
