        // large items pack well into fresh bins early in the stream
        if fit_ratio > 0.6 {
            score -= 30.0 * (fit_ratio - 0.6);
        }
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    // to avoid spreading waste; few open bins -> slightly favor new bins for flexibility.
    let residual_pressure = mean_residual / cap;      // 0..1 average wasted space
    if bin_residual != bin_capacity {
        score -= 15.0 * residual_pressure;            // reward using bins with lots of space
        // mild penalty for spreading across many bins when residuals are already small
        if residual_pressure < 0.15 {
            score += 0.5 * open_bins_count as f64;
        }
    }

