    // tightness matters more (endgame packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * tightness * progress;

    // Small tie-breaker: prefer bins with residual close to item (exact-ish fits)
    let slack = (bin_residual as f64 - item).abs();
    score += slack * 0.05;

    score
}

