        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // New: avoid opening bins late when the item fits reasonably well somewhere
        if progress > 0.7 && cap_frac < 0.5 && fitting_bins_count >= 1 {
            score += 22.0 * progress;
        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New: penalize leaving residuals that no plausible next item can use
    if post_residual > 0 && next_item_size > post_residual {
        score += 6.0 * (1.0 - pr_norm) * (1.0 - progress);
    }

    score
}

