    // Early in the stream, be more willing to open new bins (score new bin better);
    // late in the stream, consolidate into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // Penalize many open bins slightly to discourage bin proliferation.
    score += 0.5 * open_bins_count as f64;

    // New empty bin candidate: neutral base, plus a bonus that grows when
    // item is large (hard to place later) or no good fit exists.
    if bin_residual == bin_capacity {
        score = 0.5 * (bin_capacity - item_size) as f64;
        if next_item_size > item_size && next_item_size > 0 {
            score += 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Progress-coupled residual weight: later in stream, prefer fuller bins
    score += pr_norm * (0.8 + 2.1 * progress * progress) * cap * 0.5;

    // Dead-space avoidance with progress-scaled dead zone
    let dead_zone = (1.0 - pr_norm).powi(6);
    score += dead_zone * (10.0 + 42.0 * progress);

    // Exact fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead chain bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual { score -= 32.0; }
            if after == 0 { score -= 60.0; }
            else if after <= 4 { score -= 42.0; }
            else if after <= 10 && next_item_size >= after { score -= 25.0; }
            if after as f64 > mean_residual * 2.0 { score += 25.0; }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tight-fit reward relative to item size
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.92 { score -= 50.0 * tight; }
        else if tight > 0.75 { score -= 20.0 * tight; }
        else { score -= 8.0 * tight; }
    }

    // Mean residual coupling: prefer tighter-than-mean bins
    score += 0.3 * (mean_residual - pr);

    // Open-bin pressure scaled by how empty the bin is
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation penalty, stronger late in stream
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // NEW: residual-square dead-space term, punishes mid-range leftovers
    if post_residual > 0 && post_residual < item_size {
        score += 0.15 * pr;
    }

    // NEW: two-item lookahead — reward bins where the next item leaves a
    // residual close to a typical small item, punish awkward leftovers
    if next_item_size > 0 && next_item_size < post_residual {
        let after = post_residual - next_item_size;
        let after_frac = after as f64 / cap;
        if after_frac < 0.03 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // New-bin candidate logic: attract only for large items with few fitting bins
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // NEW: avoid opening a fresh bin when the current item would leave
        // near-perfect residual in an existing bin
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 6 {
            score += 120.0;
        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that can never hold typical items (residual < 10 means dead).
    if post_residual < 10 {
        score += 8.0; // small dead space is fine (bin nearly full)
    } else {
        // dead space weighted by how unlikely it is to be filled later
        let waste = post_residual as f64;
        score += 0.15 * waste * (1.0 - (waste / cap));
    }

    // Lookahead: reward if the next item fits into the post residual (chaining).
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else if post_residual > 0 {
            // partial chaining: next item partially uses leftover
            let frac = post_residual as f64 / next_item_size.max(1) as f64;
            score += 5.0 * (1.0 - frac.min(1.0));
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
        if fill_ratio > 0.5 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a bin is only good when existing
    // residuals are large/fragmented or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // base cost of a fresh bin
        score += 20.0;
        // more open bins -> keep consolidating, penalize new bin more
        score += 1.2 * open_bins_count as f64;
        // if open bins are fragmented (mean residual high), a new bin is attractive
        score -= 0.20 * mean_residual;
        // late in the stream, avoid opening bins for small items
        score += 10.0 * progress * (1.0 - item_size as f64 / cap);
    }

    // Mild preference for bins whose residual is below the mean (use fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

