pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: classify leftover space ---
    // Classes keyed on multiples of 10 (capacity quantum) and small dead zones.
    let post = post_residual;
    let class = post / 10; // integer division: harmonic bucket 0..=10
    let rem = post % 10;

    // Perfect fit (class 0): heavily reward.
    if post == 0 {
        score -= 1000.0;
    } else if post <= 5 {
        // near-perfect: dead space too small for any item (min size 1..100, but
        // tiny leftovers are the least harmful). Mild reward.
        score -= 60.0;
    } else if post <= 10 {
