        score += 25.0 + (10 - post) as f64;
    } else {
        // Usable leftover: reward proportionally to how well it matches
        // harmonic classes of typical item sizes (multiples of 10).
        let harmonic_bonus = if rem == 0 {
            40.0 + class as f64 * 3.0 // exact multiple of 10: great target
        } else if rem <= 3 {
            20.0 // near-harmonic
        } else {
            -5.0 // off-harmonic waste
        };
        score -= harmonic_bonus;
    }

    // --- Lookahead coupling: does post_residual fit the next item? ---
    if next_item_size > 0 {
        if post >= next_item_size {
            // bin remains reusable for the next item: strong reward,
            // scaled by how snugly the next item would fit.
