            score -= 45.0 - slack.min(30.0) * 0.5;
        } else {
            // bin dies after this item; penalize if next item is large
            // (we would rather have saved a roomier bin).
            score += (next_item_size - post) as f64 * 0.6;
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // --- New-bin candidate handling: opening a fresh bin should only win
    // when no open bin offers a decent (harmonic) fit. ---
    if bin_residual == bin_capacity {
        // Base cost of a new bin; make it attractive only when alternatives
        // are poor. Compare against mean residual of open bins.
        score = 100.0;
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        } else if fitting_bins_count == 0 {
            score -= 150.0; // nothing fits: new bin is forced
        } else {
            // If open bins are fragmented (low mean residual), a new bin is good.
            let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
            score -= frag * 120.0;
