    // late, prioritize closing bins out (small post residual). ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post as f64) * 0.15;
    score -= progress * (post == 0) as i32 as f64 * 50.0;

