    // from the mean residual by a large margin (dead-space homogenization)
    let dev = (pr - mean_residual).abs() / (mean_residual.max(1.0));
    score += 6.0 * dev * dev * (0.4 + 0.6 * progress);

    // NEW: two-item lookahead — reward residuals that can hold next item plus a
    // small companion (chain-of-two fillability)
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
