        let awkward = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
        if awkward < 0.15 {
            score -= 8.0 * (1.0 - awkward / 0.15) * (0.4 + progress);
        }
    }

    // New-bin candidate logic: attract only for large items with few fitting bins
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // NEW: late-stream, a fresh bin with room for the next item is valuable
        if progress > 0.6 && next_item_size > 0 && next_item_size as u32 <= bin_residual {
            score -= 18.0 * progress;
        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 22.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes mod 10.
    let post_class = post_residual % 10;
    // Perfect-fit classes are heavily rewarded (residual exactly 0, or leaving a "harmonic" gap
    // like 10, 20, 30 ... that future small items can still fill).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always take it
    } else if post_class == 0 {
        score -= 40.0;   // residual is a multiple of 10: highly reusable harmonic slot
    } else if post_class == 5 {
        score -= 20.0;   // half-harmonic gap
    } else {
        // Non-harmonic dead space: penalize proportionally to how small the gap is
        // (tiny unusable slivers are worse than moderate gaps).
        score += (10 - post_class) as f64 * 3.0;
    }

    // Integer-division thresholds on post_residual: does the leftover still admit a
    // "useful" item? Items are 1..=100; a residual below ~10 is nearly dead.
    let useful_quotient = post_residual / 10;
    score -= useful_quotient as f64 * 5.0;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item cannot fit, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: it has full residual. It should only win when no open bin
    // gives a decent fit. Penalize opening new bins progressively as the stream
    // advances and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0
            + 150.0 * progress
            + 8.0 * open_bins_count as f64;
        // But if the item is large relative to mean residual space, new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 100.0;
        }
    }

    // Mild global pressure: prefer bins whose residual is far from the mean
    // (keeps residual distribution balanced).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
