    score += 12.0 * frag * frag * (0.5 + progress);

    // Residual-sigma coupling: penalize leaving residuals near the mean spread,
    // which tends to be the hardest space to reuse later
    let sigma = (mean_residual * (1.0 - mean_residual / cap)).max(1.0);
    let near_mean = (-((pr - mean_residual).powi(2)) / (2.0 * sigma * sigma)).exp();
    score += 9.0 * near_mean * (0.4 + progress);

    // New-bin candidate logic: attract only for large items with few fitting bins
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // Late-stream new bins are rarely worth it unless item is huge
        if progress > 0.75 && cap_frac < 0.85 {
            score += 35.0 * progress;
        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Two-bin squeeze: when few bins fit, reward the emptiest fitting bin harder
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 18.0 * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale residual by how full the bin already is.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score *= 1.0 + 0.6 * fill_ratio;

    // Penalize large dead space relative to capacity, especially small residuals
    // that become unusable for typical items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // small residuals (< 10) are worthless dead space -> strong penalty
        if dead < 10.0 {
            score += 25.0 * (10.0 - dead) / 10.0;
        }
        // moderate residuals that can't fit a "typical" chunk
        if dead < item_size as f64 {
            score += 4.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // good chaining: reward proportional to how much of residual is used
            score -= 6.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += 3.0 * ((next_item_size as f64 - post_residual as f64) / 100.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins with high mean residual -> encourage consolidation into
    // bins already holding space; discourage opening new bins when open bins linger.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.15 * consolidation;
        // penalize new-bin candidate more when many bins are open
        if bin_residual == bin_capacity {
            score += 2.0 * (open_bins_count as f64).ln();
        }
    }

    // New-bin candidate baseline: should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        // early in stream, opening bins is cheaper; late in stream, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Time-horizon coupling: as stream progresses, prioritize exact exhaustion.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual == 0 {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
