        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // MUTATION: harmonic alignment bonus — post residuals that are exact
    // multiples of 10 are more reusable targets for typical item sizes.
    if post_residual > 0 && post_residual % 10 == 0 && item_size % 10 == 0 {
        score -= 18.0 + 6.0 * (post_residual / 10) as f64;
    }

    // MUTATION: near-miss lookahead guard — if next item just barely misses
    // this post residual, discourage leaving a bin that will strand it.
    if next_item_size > post_residual && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if miss < 0.15 { score += 45.0 * (1.0 - miss / 0.15); }
    }

    // MUTATION: dual-fit lookahead — reward bins whose post residual fits both
    // the next item and leaves room near the mean residual (two-item chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= next_item_size && (after as f64) <= mean_residual * 1.4 {
            score -= 55.0;
        }
    }

    score
