    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New: mild penalty when the chosen bin leaves a residual no plausible item can use
    if post_residual > 0 && post_residual < item_size && (next_item_size == 0 || next_item_size > post_residual) {
        score += 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap; // 0..1

    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual) mildly;
    // later, penalize wasted space super-linearly.
    let phase = 0.5 + 0.5 * (std::f64::consts::PI * progress).sin();
    score += 8.0 * phase * norm_post * norm_post * cap;

    // Dead-space penalty: residual too small to be useful is smoothed via sigmoid-like term.
    let dead_threshold = 0.15 * cap;
    let deadness = 1.0 / (1.0 + (post / dead_threshold).powi(3));
    score += 6.0 * deadness * post;

    // Reward near-perfect fits smoothly (quadratic dip around post=0).
    score -= 10.0 * (-post / (0.1 * cap)).exp() * cap * 0.1;

    // Lookahead coupling: if next item fits smoothly in post_residual, reward.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 5.0 * (-gap / (0.2 * cap)).exp();
