    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual - post).abs() / cap;

    // New-bin candidate: make empty bin less attractive as stream progresses
    // unless current bin residual is genuinely poor.
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * (1.0 - progress);
        score += 4.0 * (1.0 - (-norm_post * 4.0).exp());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
