    // Dead-space penalty grows super-linearly for awkward leftover classes.
    // Class 1: (0,10]  — nearly unusable slivers -> heavy penalty
    // Class 2: (10,30] — fits only small items -> moderate penalty
    // Class 3: (30,60] — useful mid-range -> mild bonus
    // Class 4: (60,100] — wide-open -> small bonus
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0;
        } else if post_residual <= 30 {
            score += 12.0;
        } else if post_residual <= 60 {
            score -= 4.0;
        } else {
            score -= 8.0;
        }
    }

    // Modulo-class coupling: does post_residual align with typical item-size classes?
    // Items 1..100: leftover divisible into common chunks (10, 20, 25, 50) is reusable.
    let residue = post_residual % 10;
    score += residue as f64 * 1.5; // penalize non-multiple-of-10 leftovers
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but check double-fit potential (next + another small)
            let after_next = post_residual - next_item_size;
            if after_next >= 10 {
                score -= 15.0;
            } else if after_next > 0 {
                score -= 5.0;
            } else {
                score -= 60.0; // perfect two-item sequence
            }
        } else {
            // next item won't fit here: leftover becomes dead space for next step
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are poor fits for the current item.
    if bin_residual == bin_capacity {
        // New bin: base score = capacity - item (large leftover). Make it competitive
        // only when mean residual is small or item is large.
        score += 30.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress; // late in stream, consolidating is cheaper
        if item_size >= 70 {
            score -= 10.0; // large items pair well in fresh bins
        }
        if mean_residual < item_size as f64 {
            score -= 15.0; // open bins can't help anyway
        }
    }

    // Mild pressure against bin sprawl.
    score += open_bins_count as f64 * 0.05;

    // Small tie-break: prefer bins whose residual is close to mean (balance).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.02;

    score
}

