        score -= 10.0;
    }

    // Prefer filling bins that are already relatively full (low residual).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fullness;

    // Time horizon: early in the stream, be more willing to open new bins
    // (spread items out); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or when open bins are fragmented,
        // unattractive late in the stream.
        score -= 20.0 * (1.0 - progress);
        score += 25.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // If many bins but none fit well, opening fresh can help.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
