pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on post_residual (waste), modulated by stream progress.
    let mut score = pr * (1.0 + 0.6 * progress) + 40.0 * norm_pr * norm_pr;

    // Smooth coupling: post_residual interacts with item size ratio.
    score += 30.0 * norm_pr * norm_item * (1.0 - norm_item);

    // Favor tight fits: reward small post_residual more as the stream progresses.
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - 0.3 * progress);
    } else if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: reward bins whose post-residual can fit the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_next = ((pr - next_item_size as f64) / cap).max(0.0);
        let usable = (fit_next * (1.0 - nxt)).max(0.0);
