    // Mild pressure to consolidate when many bins are open.
    score += 3.0 * (open_bins_count as f64).ln() * (0.3 + 0.7 * progress);

    // Mean residual coupling: prefer bins near the mean (balanced packing).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin, more so early on.
    if bin_residual == bin_capacity {
        score += 55.0 - 20.0 * progress + 15.0 * norm_item;
    }

    score
}

