    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small is good, but dead space that
    // cannot fit the smallest plausible item (<= 1) is wasted.
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 10 {
        // Harmonic class: residuals < 10 are nearly dead space
        score += 12.0;
    }

