    score += 12.0 * frag * frag * (0.5 + progress);
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual is good, but post_residual that is
    // too small to ever fit a future item (min size ~1..100 unknown, assume >=10
    // legacy band) is wasted. Non-linear penalty on unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into the resulting
    // residual (perfect chain), penalize if next item would be stranded.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size < post_residual {
            // next item fits: mild reward scaled by how well it fills leftover
            let chain_fill = nx / post_residual as f64;
            score -= 15.0 * chain_fill;
        } else {
            // next item won't fit here: slight penalty, worse if this bin is the
            // only fitting option (we'd strand both item and next item).
            score += 8.0;
            if fitting_bins_count <= 1 {
                score += 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global residual pressure: when mean residual across open bins is high,
    // prefer filling existing bins rather than spreading; when low, opening a
    // new bin is less costly.
    let mean_r = mean_residual;
    score += 0.15 * (mean_r - post_residual as f64);

    // Time horizon: early in the stream, be more conservative (favor new bins
    // for large residual preservation); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Congestion: many open bins -> prefer consolidating into existing ones.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when the item is large relative to typical residuals or
    // when open bins would be left with hopeless slivers.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > mean_residual;
        let few_fits = fitting_bins_count <= 1;
        if big_item || few_fits {
            score -= 18.0;
        } else {
            score += 15.0; // prefer existing bins for small/medium items
        }
        // Late in the stream, opening new bins is wasteful.
        score += 20.0 * progress;
    }

    score
}

