pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 buckets
    let r_mod = post_residual % 10;
    let r_class = match r_mod {
        0 => 0.0,          // perfectly reusable decade
        1..=3 => -2.0,     // near-decade: still usable for small items
        4..=7 => 3.0,      // awkward middle dead space
        _ => 1.0,
    };
    score += r_class;

    // Reward tight fits: post_residual small relative to capacity
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize leaving residual that no typical item can use:
    // dead zone: post_residual in (0, 10) is nearly unusable for items >= 10
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // residual that only tiny items can fill (10..20) is half-dead
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // integer-division harmonic: how many future fits remain
            let fits_left = post_residual / next_item_size.max(1);
            score -= 3.0 * fits_left as f64;
            // bonus if next item fits exactly (perfect chain)
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: this bin becomes dead after placement
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier-first
    // keeps tight bins tight? No: prefer bins ABOVE mean to consolidate usage)
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Harmonic fraction of capacity consumed
    let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    // integer division threshold on consumed quarters
    let quarter = (used_frac * 4.0) as u32;
    score -= match quarter {
        3 => 10.0,  // bin already 75%+ full: push it closed
        2 => 4.0,
        1 => 0.0,
        _ => 2.0,   // nearly empty bin: mild penalty to avoid bin sprawl
    };

    // New-bin candidate handling: empty bin gets baseline so it wins only
    // when all open bins are poor fits
    if bin_residual == bin_capacity {
        score = 55.0 - 0.3 * (open_bins_count as f64);
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if next item is large, a fresh bin preserves flexibility
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Stream progression: as stream ends, close bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

