}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residual gaps that no item (min size 1, but practically small)
    // can ever use are heavily penalized. A gap is "dead" if it's tiny.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver: penalize heavily (waste zone).
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Penalize post_residual relative to capacity more when the gap is
    // large but awkward (just below typical item sizes).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 30.0 {
        score += (30.0 - pr) * 0.6;
    }

    // --- Fit tightness: reward using most of the bin's residual ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // --- Open-bins pressure: discourage spreading across many bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.8;

    // --- Mean residual coupling: if mean residual is low, bins are
    // nearly full; prefer consolidating into the emptier context.
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 15.0;
    }

    // --- Lookahead (k=2): if next item could use the post_residual,
    // reward leaving exactly that gap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            // next item can't use the sliver we'd leave: extra penalty
            score += 12.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only when no good fit exists:
        // if any fitting bin leaves a small post-residual, penalize the
        // new bin; if fits are all bad (large post-residuals), favor it.
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // There is at least one fitting bin; make new bin costly,
            // but slightly cheaper when open-bin count is very high and
            // residuals are fragmented.
            score += 40.0 - (open_bins_count as f64).min(20.0);
        }
    }

    score
}

