pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall in?
    let post = post_residual as f64;
    let frac = post / cap;

    // Penalize residuals that fall into "dead zones" — small slivers nothing can use.
    // Harmonic bands: (0,10], (10,20], (20,50], (50,100] weighted by usability.
    if post_residual == 0 {
        score -= 30.0; // perfect fit, strongly reward
    } else if post_residual <= 10 {
        score += 25.0; // near-dead sliver
    } else if post_residual <= 20 {
        score += 12.0;
    } else if post_residual <= 50 {
        score += 3.0;
    }

    // Integer-division thresholds: post_residual / 10 class
    let post_class = post_residual / 10;
    score += (post_class as f64) * 0.5;

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) are more reusable.
    if post_residual > 0 {
        let reusable = (post_residual % 10 == 0)
            || (post_residual % 20 == 0)
            || (post_residual % 25 == 0)
            || (post_residual % 50 == 0);
        if reusable {
            score -= 8.0;
        }
        // Odd slivers that break mod-10 alignment are slightly worse
        if post_residual % 10 != 0 && post_residual < 30 {
            score += 6.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            // reward leaving a harmonic residual for the next step
            if new_post % 10 == 0 {
                score -= 10.0;
            }
            score -= (next_item_size as f64) * 0.15;
        } else {
            // next item cannot use this bin's remainder; penalize more if residual tiny
            if post_residual < next_item_size && post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin starts at full residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins with good fits...
        score += 20.0;
        // ...but if all existing fits are poor (large post_residual among fittings),
        // opening fresh is fine. Estimate via mean residual.
        if !fitting_bins_count == 0 {} // no-op guard for type stability
        if fitting_bins_count <= 1 && mean_residual < cap * 0.3 {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild preference for tighter bins overall (waste-avoidance pressure)
    score += (bin_residual as f64) * 0.05;

    // Small stream-position modulation for exploration stability
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

