    // Harmonic divisibility rewards: post_residual divisible by next item or common sizes
    if next_item_size > 0 {
        if pr >= next_item_size && pr % next_item_size == 0 {
            score -= 15.0;
        }
        // If next item fits exactly into post_residual, strong reward
        if next_item_size == pr {
            score -= 30.0;
        }
        // If next item would NOT fit here but fits elsewhere, mild penalty for wasting slot
        if next_item_size > pr && fitting_bins_count <= 2 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin
    if bin_residual == bin_capacity {
        // Prefer new bin only if existing fits are terrible (large post_residual)
        // Base offset so a decent existing fit beats opening a new bin
        score = cap * 0.75 + (open_bins_count as f64) * 1.5;
        if fitting_bins_count == 0 {
