        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // stacking similar items in fresh bin is fine
        }
        // Late in stream, avoid opening bins unnecessarily
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    }

    // Waste fraction coupling: penalize high fraction of capacity wasted
    let waste_frac = post_residual as f64 / cap;
    score += waste_frac * waste_frac * 20.0;

