pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Residuals that are exact multiples of common item sizes (10..=80 buckets)
    // are more likely to be filled by future items.
    let pr = post_residual;
    let class_score: f64 = if pr == 0 {
        -40.0 // perfect fit, best possible outcome
    } else if pr >= 1 && pr <= 9 {
