    } else if pr % 10 == 0 {
        -15.0 // round residual, aligns with item grid
    } else if pr % 5 == 0 {
        -8.0 // half-aligned residual
    } else {
        5.0 + (pr % 5) as f64 * 2.0 // awkward residual, penalize by remainder
    };
    score += class_score;

    // Lookahead coupling: reward residuals that can exactly host the next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 30.0; // chains perfectly into next item
        } else if pr > next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 12.0; // next item leaves a round residual again
        } else if pr < next_item_size && pr >= 10 {
            score += 4.0; // next item can't use this bin's leftover
        }
        // integer-division harmonic: how many times next_item_size divides pr
        if next_item_size > 0 && pr >= next_item_size {
            let k = pr / next_item_size;
            score -= (k.min(4) as f64) * 3.0;
        }
    } else {
        // last item: strongly prefer exact closure
        score -= 10.0;
    }

    // Last-chance bin before opening a new bin: reward using it.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 3 {
        score += 2.0; // plenty of options, less pressure to use this one
    }

    // New-bin candidate handling: penalize opening a new bin unless the
