        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // if mean residual across open bins can host the item comfortably,
        // opening a new bin is wasteful
        if (mean_residual - item_size as f64) >= 15.0 {
            score += 15.0;
        }
    }

