            if after as f64 > mean_residual * 2.0 { score += 25.0; }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tight-fit reward relative to item size
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.92 { score -= 50.0 * tight; }
        else if tight > 0.75 { score -= 20.0 * tight; }
        else { score -= 8.0 * tight; }
    }

    // Mean residual coupling: prefer tighter-than-mean bins
    score += 0.3 * (mean_residual - pr);

    // Open-bin pressure scaled by how empty the bin is
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation penalty, stronger late in stream
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Exact residual match with next item (two-step lookahead)
    if post_residual > 0 && next_item_size > 0 && post_residual == item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more than linearly.
    let fit_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item (size >= 10) could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < item_size.min(40) {
        score += 3.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose residual after placement can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many fitting bins: mild preference to keep large-residual bins flexible.
    if fitting_bins_count > 1 {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Prefer filling bins with small residual relative to mean (consolidate).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Time horizon: early in stream, be pickier about wasting space; late, just close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: default penalty; relax when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = (item_size as f64 / bin_capacity as f64) < 0.5
            && post_residual > 0
            && post_residual < 15;
        let crowded = open_bins_count == 0 || mean_residual < item_size as f64 * 0.6;
        if bad_fit || crowded {
            score -= 20.0;
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
