pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-capacity classes
    let quarter = bin_capacity / 4; // 25
    let item_class = item_size / quarter;          // 0..3 (0=small,1=med,2=large,3=huge)
    let next_class = (next_item_size as u32).min(bin_capacity) / quarter;

    // Dead-space penalty: residuals below smallest plausible item are nearly unusable
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit
    } else if post_residual <= 10 {
        score += (11 - post_residual) as f64 * 0.8; // small dead space, mildly bad
    }

    // Reward tight fits: post_residual small relative to item class
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 12.0 / (1.0 + tightness * 4.0);

    // Harmonic pairing: does next item fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size as u32 == post_residual {
            score -= 40.0; // perfect chain fit
        } else if (next_item_size as u32) < post_residual {
            // reward if next item leaves another harmonic residual
            let chain_post = post_residual - next_item_size as u32;
            score -= 15.0 * (1.0 - chain_post as f64 / bin_capacity as f64);
            // penalize wasting a big residual on a small next item
            if chain_post > quarter * 2 {
                score += 6.0;
            }
        } else {
            // next item won't fit here; keeping residual divisible by class helps future items
            if post_residual % quarter == 0 {
                score -= 8.0;
            }
        }
    }

    // Integer-division threshold on post_residual: prefer residuals that split into
    // useful classes (>= quarter*2 keeps two medium slots)
    if post_residual >= quarter * 2 {
        score -= 5.0;
    } else if post_residual >= quarter {
        score += 1.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a bin is good early or when current bin
    // would be left with awkward residue
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // prefer new bin when few bins open or item is huge and fit is poor elsewhere
        score = 30.0 + 20.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0) * 2.0;
        if item_class == 3 {
            score += 4.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
