        // wasting a nearly full bin's space on a small item when bins are plentiful
        if open_bins_count > 3 {
            score += 8.0;
        }
    }

    // Mild consolidation pressure: prefer bins with below-mean residual (fill laggards)
    score += ((post_residual as f64) - mean_residual) * 0.05;

    score
}

