    }

    // 2-step lookahead: strongly favor bins whose leftover exactly hosts the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Good if next item fits with little slack left over.
            score -= 150.0 - slack * 1.5;
        } else {
            // Next item won't fit here: penalize by the shortfall, worse when
            // this bin is the only fitting option (last-chance bin).
            let shortfall = (next_item_size - post_residual) as f64;
            let last_chance = if fitting_bins_count <= 1 { 2.5 } else { 1.0 };
            score += shortfall * last_chance;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer filling bins with below-average residual (tight bins first).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.8;
    } else {
        score += (res - mean_residual) * 0.4;
    }

    // Last-chance bonus: if this is the only bin that fits, use it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a decent fit (i.e., item is large relative to all residuals). Make the
    // empty bin moderately attractive so it wins only when fits are bad.
    if bin_residual == bin_capacity {
