pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: integer division into capacity-eighth buckets.
    // Small post_residual = tight fit = good; but post_residual that can't hold
    // typical next items is "dead space". Classify dead space severity.
    let eighth = (bin_capacity / 8).max(1) as f64;
    let post_class = (post_residual as f64 / eighth).floor(); // 0..=8
    // Dead-space penalty grows superlinearly for mid-range wasted classes
    // (too small for items >=10, too big to ignore).
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post };
        score += 0.35 * dead * (post_class as f64 / 4.0).min(2.0);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Exact harmonic match: post_residual is a multiple of a capacity fraction
    // and can host the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt = next_item_size as f64;
        // reward if post_residual == next_item_size (perfect lookahead fit)
        if post_residual == next_item_size {
            score -= 45.0;
