            // penalize leaving residue that is awkwardly larger than next item
            let leftover = post - nxt;
            score += 0.15 * leftover;
            // bonus if leftover itself is a "useful" small class (< 10 dead)
            if leftover < 10.0 {
                score -= 12.0;
            }
        }
    } else if next_item_size > 0 {
        // next item cannot fit here afterwards: post_residual is pure dead space
        score += 0.5 * post + 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Modulo arithmetic on capacity: residues near multiples of 100/k are
    // structurally reusable classes.
    let mod_penalty = (post_residual % 25) as f64;
    if post_residual > 0 && mod_penalty > 0.0 {
        score += 0.1 * (25.0 - mod_penalty); // closer to a quarter-class boundary = worse
    }

