}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post_residual
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score -= (1.0 - post / cap) * (1.0 - post / cap) * 8.0;

    // Exact fill jackpot
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize post residuals that are too small for the smallest plausible item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + (post_residual - next_item_size) as f64 * 0.05;
    }
    // If next item would fit this bin only if we DON'T place here, penalize slightly
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 3.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins could fit
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * fitting_bins_count as f64;
        // But if this is a big item and open bins have small residuals, opening fresh is fine
        let mean_res = mean_residual;
        if item_size as f64 > mean_res {
            score -= 10.0;
        }
        // Late in stream, prefer consolidating
        let t = step_index as f64 / total_items.max(1) as f64;
        score += t * 8.0;
    }

    // Prefer fuller bins: reward placing into bins with small residual relative to mean
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
