        3 => score -= 5.0,
        4 => score += 2.0,                       // awkward mid-range dead space
        5 => score += 6.0,
        6 => score += 8.0,
        7 | 8 => score += 3.0,                   // large residual still useful
        _ => score -= 2.0,                       // near-empty bin, very flexible
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes are valuable
    if post_residual > 0 {
