    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Progress-coupled residual weight: later in stream, prefer fuller bins
    score += pr_norm * (0.8 + 2.2 * progress * progress) * cap * 0.5;

    // Dead-space avoidance with progress-scaled dead zone
    let dead_zone = (1.0 - pr_norm).powi(6);
    score += dead_zone * (10.0 + 45.0 * progress);

    // Exact fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 34.0 * waste * waste;
    }

    // Lookahead chain bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual { score -= 32.0; }
            if after == 0 { score -= 60.0; }
            else if after <= 4 { score -= 42.0; }
            else if after <= 10 && next_item_size >= after { score -= 25.0; }
            if after as f64 > mean_residual * 2.0 { score += 25.0; }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tight-fit reward relative to item size
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.92 { score -= 50.0 * tight; }
        else if tight > 0.75 { score -= 20.0 * tight; }
        else { score -= 8.0 * tight; }
    }

    // Mean residual coupling: prefer tighter-than-mean bins
    score += 0.3 * (mean_residual - pr);

    // Open-bin pressure scaled by how empty the bin is
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation penalty, stronger late in stream
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // New residual variance reduction: penalize bins whose post-residual
    // deviates strongly above the running mean (dead-space concentration)
    if post_residual > 0 {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += 0.12 * dev * (1.0 + progress);
        }
    }

    // New-bin candidate logic: attract only for large items with few fitting bins
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // Refinement: new bin only attractive if item nearly fills it alone
        if cap_frac > 0.9 && fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    score
}

