pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (1..15) are nearly useless
    // for future items (sizes 10..80), so penalize them heavily.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }
    // Medium dead space (15..35) is mildly penalized.
    else if post_residual >= 15 && post_residual < 35 {
        score += 10.0 * (1.0 - (post_residual as f64 - 15.0) / 20.0);
    }
    // Comfortable residual (>=35) is rewarded: bin stays reusable.
    else if post_residual >= 35 {
        score -= 8.0;
    }

    // Perfect / near-perfect fits are excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving exactly enough room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 12.0; // leaves a sliver unusable by next item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills
    // (i.e., small post_residual) and discourage new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // New-bin candidate handling: only open a new bin when all open bins would
    // leave bad dead space or residuals are fragmented.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 * 5.0;
        let mean_frag = mean_residual; // average leftover in open bins
        // Opening a bin is attractive when existing residuals are small/fragmented
        // and can't host the item well.
        let attract = (mean_frag * 0.3) + open_pressure * 0.5;
        score = 70.0 - attract;
        // Late in the stream, closing out bins is better: make new bins costly.
        score += progress * 30.0;
        // If lookahead fits typical residual, keep new bin as fallback.
        if next_item_size > 0 && next_item_size <= mean_residual as u32 {
            score += 15.0;
        }
    }

    // Mild preference for bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    score
}

