pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills (post_residual close to 0).
    if post_residual <= 10 {
        score -= 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Aggressive 2-step lookahead: strongly reward post_residual matching next_item_size exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item fits perfectly after this placement.
            score -= 45.0 * (1.0 - gap / 100.0);
        } else {
            // Next item would not fit; penalize proportionally to the shortfall.
            score += 20.0 * (gap / 100.0);
        }
    }

    // Compare post_residual against mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless this bin is a bad fit.
    if bin_residual == bin_capacity {
        let waste = bin_residual as f64 - item_size as f64;
        score += 25.0 + 0.3 * waste;
        if next_item_size > 0 && next_item_size <= post_residual {
            // Opening fresh bin lets the next item land perfectly too.
            score -= 15.0;
        }
    }

    // Late in the stream, prefer tighter packing (consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

