pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, keep bins tight; late, be greedy about closure.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward bins whose post-residual can still host the next item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The next item can also go here: chain placement is valuable.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + 0.15 * next_item_size as f64 - 0.05 * slack;
        } else {
            // Dead space relative to the lookahead item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste * (0.5 + progress);
            // Extra penalty if the residual becomes unusably small for typical items.
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Penalize creating awkward mid-range residuals that few item sizes can use.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 25.0 {
        score += 6.0 * (25.0 - pr) / 25.0;
    }

    // Reward near-exact closure of a bin.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Compare against global state: prefer bins that are below-average fullness
    // only when they fit well; otherwise push toward consolidating fullness.
    let fit_quality = item_size as f64 / bin_residual.max(1) as f64;
    if fit_quality > 0.85 {
        score -= 10.0 * fit_quality;
    } else if fit_quality < 0.4 {
        score += 5.0 * (0.4 - fit_quality);
    }

    // Dampen preference for very empty bins when many bins are already open
    // (encourage consolidation under bin proliferation).
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64 - 4.0) * (1.0 - fit_quality);
    }

    // Mean-residual coupling: if the average residual across open bins is large,
    // slightly discourage this bin unless it is a very good fit (avoid fragmentation).
