    // Penalize residuals in "dead zones": too small to fit typical items (1..100 unknown, use harmonic classes)
    // Class boundaries via integer division thresholds on post_residual
    let class = post_residual / 10; // harmonic class 0..=10
    match class {
        0 => score -= 8.0,        // near-perfect fill: excellent
        1 => score -= 4.0,        // very good
        2 => score -= 2.0,
        3 => score -= 0.5,
        4 => score += 1.0,        // awkward mid zone
        5 => score += 2.5,        // half-full residual: mediocre
        6 => score += 1.0,
        7 => score -= 1.5,        // fits large items again
        8 => score -= 2.0,
        9 => score -= 3.0,
        _ => score -= 5.0,        // empty-ish bin: very reusable
    }

    // Modulo arithmetic: residuals divisible by common item sizes are harmonically valuable
    if post_residual > 0 {
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                score -= 1.5;
                break;
            }
        }
        // Penalize odd primes-ish residuals that rarely match
        if post_residual % 2 == 1 && post_residual < 15 {
            score += 2.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.05;
