    // New-bin candidate: prefer opening a new bin only when existing residuals are poor
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; attractive if mean residual is fragmented
        score = cap_f * 0.55 - mean_residual * 0.3;
        if fitting_bins_count == 0 {
