    }

    // Progress pressure: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0 * (frac - 0.5);

    // Spread across many open bins: encourage filling fuller when many bins open
    if open_bins_count > 4 {
        score += (post_residual as f64) * 0.02 * (open_bins_count.min(20) as f64) * 0.1;
    }

    score
}

