    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining: this bin will be closed by next item
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // next item fits but leaves more waste: mild reward proportional to tightness
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + gap);
        } else {
            // next item cannot use the leftover space: penalize dead space
            score += 10.0;
        }
    }

    // Compare against mean residual: placing into a bin with large residual
    // (above average) is good; squeezing into already-tight bins is worse.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize creating very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Neutral base for a fresh bin; becomes attractive if all open bins
        // would leave large waste.
        let best_possible_waste = (bin_capacity - item_size) as f64;
        if post_residual as f64 > mean_residual && fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: open a new one
        } else {
            score += 8.0 + 0.05 * open_bins_count as f64; // slight preference to reuse bins
        }
        let _ = best_possible_waste;
    }

    // Mild late-stream tightening: as the stream progresses, prefer closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

