pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let mean_res = mean_residual.clamp(0.0, capacity);
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let is_new_bin = bin_residual == bin_capacity;
    let new_post = (capacity - item).max(0.0);
    let next_scarcity = if next > 0.0 {
        ((next - mean_res) / next).clamp(0.0, 1.0)
    } else {
        0.0
    };
    let open_pressure = 1.0 / (1.0 + 0.06 * open);
    let new_pair_possible = next > 0.0 && new_post + 0.5 >= next;
    let small_edge = (0.12 * capacity).max(6.0);

    let mut score = post;

    if post <= 0.5 {
        score -= capacity * (2.0 + 0.6 * progress) + 4.0 * open;
    } else {
        if post < small_edge {
            let dead_depth = (small_edge - post) / small_edge;
            score += dead_depth * dead_depth * (0.30 * capacity + 1.5 * open + 15.0 * progress);
        }

