        let mut last_chance_bonus = capacity * (0.45 + 0.25 * progress);

        if next > 0.0 && post + 0.5 < next && new_pair_possible {
            last_chance_bonus *= 1.0 - 0.80 * next_scarcity * open_pressure;
        }

        score -= last_chance_bonus;
    }

    if is_new_bin {
        let mut new_bin_penalty = capacity * (0.85 + 0.15 * progress)
            + 2.0 * open
            + 0.15 * mean_res;

        if fitting > 0.5 {
            new_bin_penalty += 12.0 + 10.0 * (fitting - 1.0).min(4.0);
