pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual < 10 {
        score -= 100.0;
    }

    // 2-step lookahead: strongly favor bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 800.0; // perfect 2-step match
        } else if post >= nxt {
            let gap = post - nxt;
            if gap <= 5.0 {
                score -= 400.0;
            } else {
                score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // post_residual too small for next item: penalize dead space
            score += 120.0 + 0.5 * (nxt - post);
        }
    }

    // Penalize bins with large residual relative to mean (wasteful bins) mildly,
    // but favor tight bins (small residual) when fitting bins are scarce.
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    score += 0.3 * (post_residual as f64 - mr);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: make it attractive only when current bin would leave big waste
    // or when many bins already open. Empty bin has post_residual == capacity - item_size.
    if bin_residual == bin_capacity {
        // neutral base; add slight penalty so it's chosen only when clearly better
        score += 40.0;
        if open_bins_count > 20 {
            score -= 20.0;
        }
    }

    // Progress-based tightening: later in stream, be greedier about exact fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

