    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Exact residual match with next item across all bins (chain perfection)
    if post_residual > 0 && post_residual == item_size {
        score -= 35.0;
    }

    score
}

