            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // NEW: late-stream, opening a fresh bin is cheaper than scattering
        if progress > 0.8 { score -= 20.0 * (progress - 0.8) * 5.0; }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does it land in?
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap;

    // Integer-division thresholds: post_residual in "dead zones" (small leftovers)
    // are hard to fill later -> penalize via modulo classes.
    let dead_class = post_residual % 10; // residue mod 10 (harmonic granularity)
    if post_residual == 0 {
        score -= 60.0; // perfect fit, strongly favored
    } else {
        // Penalize tiny unusable leftovers (<10) heavily, scaled by class
        if post_residual < 10 {
            score += 45.0 + dead_class as f64;
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
    }

    // Fractional band coupling: mid-range residuals are valuable
    let band = (post_residual * 4) / bin_capacity; // 0..3 integer division threshold
    score -= match band {
        0 => 2.0,
        1 => 8.0,
        2 => 12.0,
        _ => 5.0,
    };

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match via modulo
            let m = post_residual % next_item_size.max(1);
            if m == 0 {
                score -= 30.0; // next item will fill exactly
            } else if m < 10 {
                score -= 15.0;
            } else {
                score -= 8.0;
            }
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good open fit exists
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // open new bin if existing residuals are large relative to next item
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.5 {
            score -= 20.0;
        } else {
            score += 30.0 + 40.0 * (1.0 - pressure);
        }
    }

    // Progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_frac);

    // Many open bins -> prefer filling existing ones
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 3.0 * (1.0 - post_frac);
    }

    score
}

