    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins;
    // the new-bin candidate (full residual) gets a surcharge proportional to pressure.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
