    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // NEW: residual-size-aware consolidation — bins whose leftover can still
    // host typical upcoming items are more valuable than tiny leftovers.
    let res_var_proxy = (mean_residual - pr).abs() / (mean_residual + 1.0);
