        // in an existing bin, that beats a new bin (handled by tight-fit rewards).
        if post_residual == 0 {
            score += 100.0; // never open a new bin for a perfect fit elsewhere
        }
    }

    // Integer-division threshold on item size classes (harmonic bands).
    let item_class = item_size / quarter;
    match item_class {
        0 => score -= 2.0,   // tiny item: flexible, mild reward
        1 => {},             // small-medium
        2 => score += 2.0,   // medium-large
        _ => score += 4.0,   // large item: prefer roomier bins
    }

    // Prefer filling bins that are already mostly full (harmonic pairing of large
    // residual class with small residual class bins).
    if bin_residual <= quarter && bin_residual >= item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item = item_size as f64;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Progress-coupled residual weight: later in stream, prefer fuller bins
    score += pr_norm * (0.8 + 2.1 * progress * progress) * cap * 0.5;

    // Dead-space avoidance with progress-scaled dead zone (sharpened exponent)
    let dead_zone = (1.0 - pr_norm).powi(7);
    score += dead_zone * (10.0 + 46.0 * progress);

    // Exact fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item - pr) / item;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead chain bonus
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 640.0;
        } else if next_item_size < post_residual {
            let fill = nxt / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            let after_f = after as f64;
            if after_f <= mean_residual { score -= 32.0; }
            if after == 0 { score -= 60.0; }
            else if after <= 4 { score -= 42.0; }
            else if after <= 10 && next_item_size >= after { score -= 25.0; }
            if after_f > mean_residual * 2.0 { score += 25.0; }
            // New: two-step lookahead — residual after chain should still fit next item
            if after_f >= nxt && after_f - nxt <= mean_residual {
                score -= 40.0 * (1.0 - progress);
            }
        } else {
            let gap = (nxt - pr);
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
            // New: penalize bins that will certainly strand the next item
            if gap <= 12.0 && open_bins_count > 1 {
                score += 18.0 * (1.0 - gap / 12.0);
            }
        }
    }

    // Tight-fit reward relative to item size
    if post_residual > 0 && post_residual >= item_size {
        let tight = item / pr;
        if tight > 0.92 { score -= 50.0 * tight; }
        else if tight > 0.75 { score -= 20.0 * tight; }
        else { score -= 8.0 * tight; }
    }

    // Mean residual coupling: prefer tighter-than-mean bins
    score += 0.3 * (mean_residual - pr);

    // Open-bin pressure scaled by how empty the bin is
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation penalty, stronger late in stream
    let frag = if post_residual > 0 { pr / (pr + item) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // New-bin candidate logic: attract only for large items with few fitting bins
    if bin_residual == bin_capacity {
        let cap_frac = item / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // New: fresh bins are cheap early — slight extra attraction when stream is young
        if progress < 0.25 && cap_frac < 0.5 {
            score -= 8.0;
        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit any plausible
    // future item (sizes can be as small as 1, but tiny gaps are still
    // statistically unlikely to be filled) are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - pr / 10.0);
    }

    // Perfect fit bonus: reward filling the bin exactly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward placements that leave a gap exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Slight reward for leaving room for the next item.
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize blocking the next item.
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // encourage consolidation when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, minus potential value
        // if current mean residual is large (existing bins are fragmented).
        score += 80.0 + pressure - 0.3 * mean_residual;
    } else {
        // Slight reward for using existing bins as pressure grows.
        score -= 0.05 * pressure;
    }

    // Prefer bins whose residual is already close to mean (balance avoidance
    // of many half-full bins): penalize bins far above mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.1 * dev.max(0.0);

    score
}

