                score -= 400.0;
            } else if gap <= 10.0 {
                score -= 120.0 - gap * 4.0;
            }
        } else {
            // Next item cannot fit in this bin's leftover: mild penalty unless leftover tiny.
            let overshoot = nxt - pr;
            if post_residual > 0 {
                score += overshoot * 0.5;
            }
        }
    }

    // Compare post_residual against mean residual across open bins:
    // favor leaving residuals close to the mean (balanced bins),
    // penalize creating very small dead space (wasted slivers).
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += dev * 0.3;

    // Penalize small-but-nonzero dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
