    // Early in the stream, encourage consolidation into fewer bins;
    // late in the stream, allow more aggressive new-bin opening for tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        score += 20.0; // slight reluctance to open new bins early
    } else if progress > 0.7 {
        score -= 10.0 * (1.0 - pr / bin_capacity as f64); // favor tight fills late
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if no open bin fits well (this call is the only candidate), opening is fine.
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
        // Lookahead: opening a new bin is good if next item also large.
        if next_item_size >= 50 {
            score -= 30.0;
