    }

    // Slight preference for bins with larger residual before placement (bigger bins absorb items).
    score -= (bin_residual as f64) * 0.05;

    // Scale by number of open bins: many open bins -> prefer tighter packing.
    score += open_bins_count as f64 * 0.5;

    score
}

