        let match_q = next_item_size as f64 / post_residual as f64;
        if match_q > 0.9 { score -= 45.0; }
        else if match_q > 0.7 { score -= 22.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes group residuals into
    // "harmonic" buckets. Small residuals in low classes are dead space.
    let class = post_residual % 10;
    score += class as f64 * 0.35;

    // Perfect fit reward: post_residual in {0} or divisible by small harmonics.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 20 == 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Penalize residual that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.4;
        } else {
            // Reward leaving exactly enough room for the next item (tight chaining).
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 10.0;
            }
        }
        // Harmonic divisibility between next item and post-residual classes.
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when many bins are already open and mean
    // residual is high (fragmentation signal).
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5 + (mean_residual / bin_capacity as f64) * 20.0;
    } else {
        // Favor packing into bins whose residual deviates from mean (balance control).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Integer-division threshold: bins whose residual floor(res/10) is small
    // are nearly full; packing them tightly is good.
    let decile = post_residual / 10;
    if decile == 0 {
        score -= 8.0;
    } else if decile <= 2 {
        score -= 3.0;
    } else if decile >= 8 {
        score += 5.0;
    }

    // Early-stream exploration: be slightly more willing to open new bins early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= progress * 6.0;
    }

    score
}

