            score -= (post_residual - next_item_size) as f64 / bin_capacity as f64 * 20.0;
        } else {
            // Next item won't fit here; penalize leaving a large unusable-looking gap.
            score += (post_residual as f64 / bin_capacity as f64) * 15.0;
