pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classification via integer division.
    let pr = post_residual;
    // Class thresholds on post_residual (harmonic fractions of capacity).
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    // Penalize residuals in "dead zones" that few future items (>=10) can use.
    if pr > 0 && pr < 10 {
        score += 30.0; // unusable dead space
    } else if pr < quarter {
        // Modulo-10 harmonic classes: how well residual aligns with item granularity
        let m = pr % 10;
        score += match m {
            0 => 2.0,          // perfectly harmonic: another 10-multiple fits
            1..=4 => 6.0 + m as f64,
            _ => 9.0 + (9 - m) as f64,
        };
    } else if pr < eighth * 3 {
        score += 1.0; // mid zone: still reusable
    } else {
        // large residual: mildly reward leaving room
        score -= 3.0;
    }

    // Sixteenth-level harmonic bonus: residual divisible into 16ths cleanly
    if pr % sixteenth.max(1) == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of the slack after lookahead placement
            score -= 12.0 * (1.0 - slack / cap);
            if slack < 10.0 {
                score += 8.0; // would create dead space for next-next items
            }
        } else {
            // next item won't fit here; residual likely stranded
            score += 4.0 + (next_item_size - pr).min(40) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Tight fit reward: residual minus item small relative to capacity.
    let tightness = post_residual as f64 / cap;
    score -= (1.0 - tightness) * 5.0;

    // Mean residual coupling: prefer bins below mean residual (fill emptier-first counter:
    // actually prefer bins whose residual is close to item, i.e. below mean).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (1.0 - tightness);

    // Many open bins: discourage spreading; reward filling existing bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 1.5 * tightness;
    }

    // New-bin candidate handling: only attractive when no bin fits well
    // (post_residual == capacity - item for empty bin). Make it costly unless
    // current item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        // Empty bin: penalize unless item is big or few fitting bins.
        let big_item = item_size as f64 / cap;
        score += 20.0 - 18.0 * big_item;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score += 25.0; // a last-chance bin exists; prefer it
        }
    }

    score
}

