    // A residual gap is "unusable" if it cannot fit the next item (or a
    // representative small item when lookahead is unavailable).
    let ref_size = if next_item_size > 0 { next_item_size } else { 20 };
    if post_residual > 0 && post_residual < ref_size {
        score += (ref_size - post_residual) as f64 * 3.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Open bins pressure: discourage spreading across many bins unless fit is tight
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
    }

    // Mean residual alignment: prefer bins whose residual is close to mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Late-stream tightening: be pickier as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    // Lookahead synergy: reward leaving space exactly usable by next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 5.0 / (1.0 + slack);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
