        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // NEW: when open bins are highly fragmented (tiny mean residual),
        // opening fresh capacity is cheap insurance.
        if open_bins_count > 0 && mean_residual < 0.25 * cap {
            score -= 20.0;
        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // NEW: harmonic alignment bonus for decimal-friendly packing
    if item_size % 10 == 0 && post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    score
}

