    // Late in stream: consolidate into existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_residual - item_size) as f64;

    score
}

