    // NEW: residual variance shaping — penalize bins whose leftover diverges
    // from the stream's characteristic gap size, reducing dead-space spread
    let res_sigma = 0.2626 * cap;
    if pr > 0.0 {
        let dev = ((pr - mean_residual) / res_sigma.max(1.0)).abs();
        score += 3.5 * dev.min(4.0) * (0.6 + progress);
    }

    // NEW: harmonic pair-fit lookahead — if the next item leaves a second
    // residual that itself could absorb a small follow-up, reward it
    if next_item_size > 0 && next_item_size < post_residual {
