    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // next item likely can't use this bin
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins;
    // the new-bin candidate (bin_residual == bin_capacity) gets penalized.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).powf(1.3) * 5.0;
        score += 30.0 + pressure;
