        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Small residual hoarding: bins with tiny leftovers are precious late
    if post_residual > 0 && post_residual <= 6 && progress > 0.5 {
        score -= 18.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill_ratio = 1.0 - post / cap;

    // Core: post residual with smooth non-linear shaping
    let mut score = post * (1.0 + 0.8 * fill_ratio * fill_ratio);

    // Stream-progress coupling: prefer tighter fits (low post_residual) more strongly as stream advances
    let tightness = (cap - post) / cap;
    score -= 12.0 * progress * tightness * tightness * tightness;

    // Interaction: post_residual * progress polynomial coupling
    score += 0.15 * post * progress * (1.0 - progress);

    // Perfect-fit reward (smooth gaussian-like bump at post==0)
    let z = post / cap;
    score -= 25.0 * (-z * z * 40.0).exp();

    // Penalize near-full-but-wasteful residuals (dead space ~ small)
    score += 8.0 * (-((z - 0.5) * (z - 0.5)) * 8.0).exp() * (1.0 - progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving space close to next item size (smooth kernel)
    if next_item_size > 0 {
        let d = (post - next_item_size as f64) / cap;
        score -= 10.0 * (-d * d * 30.0).exp();
    }

    // Crowd penalty: when many bins open, discourage spreading; favor consolidation
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    // Mean-residual alignment: prefer bins whose resulting residual is near mean (keeps diversity of sizes)
    let md = (post - mean_residual) / cap;
    score += 3.0 * md * md;

    score
}

