    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Dead-space penalty: residuals that can never fit typical small items are bad.
    if post_residual < 10 {
        score -= 25.0; // perfect / near-perfect fill: strongly reward
    } else {
        // Non-linear dead-space curve: penalize residuals just below useful item sizes.
        let harmonic = (post_residual % 25) as f64;
        score += 0.15 * harmonic;
        if post_residual < 20 {
            score -= 8.0; // still a great fill
        } else if frac < 0.35 {
            score -= 3.0; // decent fill
        } else if frac > 0.7 {
            score += 6.0; // mostly empty bin being used: wasteful
        }
    }

    // Lookahead coupling: reward leaving residual that fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap); // tight-but-fitting is ideal
        } else {
            score += 4.0; // next item won't fit here: this residual likely dead
        }
    }

    // Last-chance bonus: if this is the only fitting bin, use it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing residuals are poor.
    if bin_residual == bin_capacity {
        // New bin baseline: slightly worse than a good fit, better than a bad one.
        score = cap * 0.55 - 0.2 * (open_bins_count as f64);
