    // Late-stream consolidation: as the stream ends, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - frac);

    // Prefer bins below mean residual (more packed) to consolidate.
    score += 0.1 * (mean_residual - post);

    score
}

