            // NEW: two-step lookahead — chain must still leave harmonic space
            if after % 10 == 0 && after > 0 { score -= 18.0; }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tight-fit reward relative to item size (mutated bands)
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / pr;
        if tight > 0.94 { score -= 55.0 * tight; }
        else if tight > 0.78 { score -= 22.0 * tight; }
        else { score -= 8.0 * tight; }
    }

    // Mean residual coupling: prefer tighter-than-mean bins
    score += 0.3 * (mean_residual - pr);

    // Open-bin pressure scaled by emptiness
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation penalty, stronger late in stream
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // New-bin candidate logic: open only when it truly pays off
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // NEW: opening a bin is cheaper when open bins are highly fragmented
        let frag_mean = (mean_residual / cap).clamp(0.0, 1.0);
        if frag_mean < 0.25 { score -= 40.0 * (0.25 - frag_mean) * 4.0; }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot follow here; penalize by leftover gap size
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare post_residual to mean residual across open bins:
    // prefer bins whose leftover stays close to (but below) mean, penalize outliers
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3;
    if dev > 20.0 {
        score += dev * 0.5; // extra penalty for creating large-above-average dead space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 120.0;
        // allow opening a new bin when item barely fits nowhere well
        if fitting_bins_count <= 1 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 250.0; // pair two items in a fresh bin
        }
    }

    // Late in stream: prefer tight packing, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 80.0;
    }

    score
}

