}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 1. Tightness reward: strongly reward small post_residual (good fill).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // 2. Perfect fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 3. Dead-space penalty: residuals too small for the smallest plausible item
    //    (<= 10) are wasted; penalize them heavily unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Lookahead coupling: if the next item fits in the post residual,
    //    this placement chains nicely; reward it. Otherwise penalize a bit.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / bin_capacity as f64 + 0.5);
        } else {
            score += 2.0;
        }
    }

    // 5. Last-chance logic: if this is the ONLY bin that can fit the item,
    //    strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. New-bin candidate handling: opening a new bin should only win when
    //    the fit into existing bins is poor (large post_residual) or when
    //    open bins are nearly full on average.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Early in the stream, exploring new bins is cheaper; later, consolidate.
        score += 25.0 * progress;
        // If many bins are open and their mean residual is large, prefer reuse.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
        }
        // If no existing bin fits well (this call had a good alternative),
        // the base penalty stands; a very poor fit elsewhere (post_residual
        // large) makes the new bin relatively attractive via comparison.
    } else {
        // Reuse reward scaled by how many bins already fit the item:
        // with many options, prefer the tightest, so add mild competition noise.
        if fitting_bins_count > 1 {
            score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // Late in the stream, favor closing out bins: reward placing into bins
        // whose residual is below the mean (they are the "small holes").
        if (post_residual as f64) < mean_residual {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // 7. Mild preference for bins with smaller residual overall (best-fit flavor),
    //    modulated by stream position.
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 + progress);

    // 8. Tiny tie-breaker using step parity-free deterministic term.
    score += (step_index % 3) as f64 * 0.01;

    score
}

