    // late in stream, waste matters more (bins close out), so amplify residual penalty
    score += 20.0 * progress * pr_norm * pr_norm * cap;

    // Smooth interaction: post_residual vs next item fit (lookahead), weighted by progress
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs() / cap;
        score -= 25.0 * (1.0 - fit_gap) * (1.0 - progress);
        // penalize if next item cannot fit in post-residual, smoothly
        let cannot_fit = ((pr - nx).max(0.0) / cap).powf(2.0);
        score += 15.0 * cannot_fit * (1.0 + progress);
    }

    // Dead-space penalty: residual too small to ever fit minimum item (smooth ramp)
    let min_item = 1.0;
    let dead = ((min_item - pr_norm).max(0.0) / min_item).min(1.0);
    score += 30.0 * dead * dead;

    // Last-chance bonus: only fitting bin -> encourage using it over opening new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Scarcity of fitting bins: more competition -> slightly favor this bin
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Coupling with mean residual: prefer bins near the mean (balanced closing)
    let dev = (pr - mean_residual).abs() / cap;
