        _ => 8.0,                         // tiny unusable sliver: penalize
    };
    score -= quarter_bonus;

    // Modulo arithmetic on post_residual: harmonic classes mod 10
    let m = post_residual % 10;
    let mod_bonus = match m {
        0 => -4.0,                        // exact decade residual: very reusable
        1..=3 => -1.5,
        4..=7 => 0.5,
        _ => 2.0,                         // awkward odd residual
    };
    score -= mod_bonus;

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: big reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            // Harmonic pair: post_residual % next_item_size small => chainable
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item would have fit before this placement: mild penalty
            score += 3.0;
        }
        // Sum of classes: if item + next exactly fills bin, jackpot
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
