            score -= 5.0; // fresh bin useful for medium next item
        }
    }

    // Fractional coupling: reward residual close to common item-size harmonics
    let harm = [10u32, 20, 25, 40, 50, 80];
    for &h in harm.iter() {
        if post_residual >= h && post_residual < h + 3 {
            score -= 4.0;
        }
    }

    // Mild drift: later in stream, prefer closing bins tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (frac * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
