    let pr_norm = pr / c;
    let fit_norm = pr_norm * pr_norm;

    // Base: reward tight fits (low post residual), with non-linear emphasis
    let mut score = pr * (1.0 + 1.5 * fit_norm);

    // Smooth stream-progress coupling: later in stream, penalize wasted residual more
    let tightness = (pr_norm - 0.5) * (pr_norm - 0.5);
    score += 20.0 * progress * (1.0 - pr_norm) * (0.5 + tightness);

    // Lookahead coupling: bonus if next item fits into post residual (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
