    }

    // Penalize opening a new bin when a reasonable fit exists
    if br == c {
        score += 15.0 + 10.0 * progress;
        // But allow new bin if all fits are terrible
        score -= 30.0 * (1.0 - fit_norm).max(0.0) * 0.0;
        if fit_norm > 0.36 {
            score -= 22.0;
        }
    }

    // Mild penalty proportional to open bin count to discourage bin proliferation
    score += open_bins_count as f64 * 0.3;

    // Mean-residual coupling: prefer bins close to mean residual (balance)
    let dev = (br - mean_residual).abs() / c;
    score += 4.0 * dev * dev;

