            let scale = if gap <= 8.0 { 0.45 } else { 0.6 };
            score += scale * gap;
        }
    }

    // Tight-fit reward relative to item size.
    if post > 0 && post >= item_size {
        let tight = item_size as f64 / post as f64;
        if tight > 0.92 {
            score -= 55.0 * tight;
        } else if tight > 0.75 {
            score -= 22.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // --- Last-chance logic: sole fitting bin should be used ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0 + 20.0 * progress;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / bin_capacity as f64;
        if open_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 0 {
            score -= 150.0;
        } else if cap_frac > 0.7 && fitting_bins_count <= 2 {
            // Large item, poor alternatives: opening a fresh bin is fine.
            score = 40.0 * (1.0 - cap_frac) + 20.0 * (1.0 - progress);
        } else {
