    if post_residual >= 10 && post_residual % 10 != 0 && slots == 0 {
        // residual in (0,10): pure dead space
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
