            score += 3.0 + (next_item_size - post_residual) as f64 / 20.0;
        }
    }

    // Exact fit of current item: maximal reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
