    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; waived if item is huge or fits are scarce.
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tightness = (item_size as f64) / (bin_capacity as f64);
        score += 10.0 - 18.0 * scarcity - 10.0 * tightness;
        // Opening a bin is good if it leaves a harmonic residual (multiple of 10/20).
        if item_size % 10 == 0 { score -= 8.0; }
        if item_size % 25 == 0 { score -= 4.0; }
    }

    // Mean-residual coupling: prefer bins whose post-residual stays near the mean band.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Stream progression: late in the stream, consolidate aggressively (close bins out).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual == 0) as i32 as f64 * 10.0;
    score += progress * 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Small tie-break by residual so tighter bins win.
    score += post_residual as f64 * 0.01;

    score
}

