}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets. Leftovers that are "harmonically useful"
    // (large, well-rounded fractions) should be rewarded; tiny dead space
    // (class 0) should be penalized.
    let frac = (post_residual as f64) / (bin_capacity as f64);
    let class = (frac * 8.0).floor() as i32; // 0..7 harmonic class
    let dead_penalty = match class {
        0 => 14.0,                       // unusable sliver (<12.5%)
        1 => 6.0,                        // poor fit zone
        2 => 2.0,
        3 => -1.0,
        4 => -3.0,                       // half-full bin: very reusable
        5 => -3.5,
        6 => -2.5,
        _ => -1.5,                       // nearly full: fine, little waste
    };
    score -= dead_penalty;

    // Modulo arithmetic on post_residual: leftovers divisible by small
    // harmonics (10, 20, 25, 50) tend to pair with common item sizes.
    if post_residual > 0 {
        if post_residual % 50 == 0 { score -= 5.0; }
        else if post_residual % 25 == 0 { score -= 3.0; }
        else if post_residual % 10 == 0 { score -= 2.0; }
        else if post_residual % 5 == 0 { score -= 1.0; }
    }

    // Coupling with lookahead item (k=2): if the next item fits the
    // post-residual exactly or harmonically, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 { score -= 6.0; } else { score -= 3.0; }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how much dead space this creates relative to next item.
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer bins whose residual is far below the mean (i.e., we are
    // tightening a loosely-packed bin) when many bins are open.
    let res_f = bin_residual as f64;
    if open_bins_count > 1 {
        score += (mean_residual - res_f) * 0.03;
    }

    // Early in the stream, be more willing to consolidate; late, keep
    // flexibility by slightly favoring larger post-residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
