    // New-bin candidate: only attractive if no open bin fits well
    // (handled via fitting_bins_count) — otherwise penalize opening.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 8.0 + (post_residual as f64) * 0.1 };
        score += pressure;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 4.0; // big next item: fresh bin is fine
        }
    }

    score
}

