    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New: scarcity-aware tie-break — with exactly two fitting bins, prefer the one
    // whose leftover stays closest to mean residual (keeps usable gaps alive)
    if fitting_bins_count == 2 && post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
