    let pr_norm = pr / cap ;
    score += pr_norm * (0.8 + 2.1 * progress * progress) * cap * 0.5 ;

    // dead-space avoidance with progress-scaled dead zone
    let dead_zone = (1.0 - pr_norm).powi (6) ;
    score += dead_zone * (10.0 + 42.0 * progress) ;

