    // Harmonic class of post_residual: dead space in small remainders is worse.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if pr <= 10 {
        score -= 35.0; // nearly-perfect: tiny residual, likely unusable anyway
    } else if pr <= 25 {
        score += 8.0; // awkward mid-range dead space
    } else if pr <= 50 {
        score += 3.0;
    }

    // Modulo classes on post_residual relative to capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr % quarter == 0 && pr > 0 {
        score -= 6.0; // residual aligned to quarter-class: reusable by common sizes
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0; // decade-aligned residual: fits round-sized items well
    }
    if pr > half {
        score -= 10.0; // still roomy bin, plenty of future utility
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact / harmonic match with next item is gold.
            if post_residual == next_item_size {
                score -= 45.0;
            } else {
                let gap = post_residual - next_item_size;
                if gap <= 10 {
                    score -= 25.0;
                } else {
                    score -= (gap as f64).recip() * 200.0; // tighter gap => bigger reward
                }
            }
        } else {
            // Next item cannot use this bin's remainder; penalize proportionally.
            let miss = next_item_size - post_residual;
            score += (miss as f64).min(50.0) * 0.3;
            // Integer-division threshold: residual class of pr vs next item class
            if pr / 20 == (next_item_size / 20) {
                score -= 5.0; // same coarse class, likely reusable later
            }
        }
    } else {
        // Last item: pure waste minimization.
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    if open_bins_count > 4 {
        score -= 2.0 + (open_bins_count as f64).ln() * 2.0;
    }

    // Mean residual coupling: bins below mean residual are tighter; using them
    // preserves roomier bins for future items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: only attractive for big items or when this
    // is a fresh empty bin late in the stream with no good alternatives.
    if bin_residual == bin_capacity {
        score += 55.0; // default penalty: prefer existing bins
        if item_size > bin_capacity * 3 / 4 {
            score -= 40.0; // huge items are fine in a fresh bin
        }
        if next_item_size > 0 && next_item_size >= post_residual && fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if step_index as f64 / total_items.max(1) as f64 > 0.9 {
            score -= 10.0; // late stream: cheap to open one more bin
        }
    }

    // Early-stream exploration: slightly prefer keeping residuals diverse.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && pr % 3 == 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Progress-coupled residual weight (refined: slightly sharper late ramp)
    score += pr_norm * (0.8 + 2.4 * progress * progress) * cap * 0.5;

    // Dead-space avoidance with progress-scaled dead zone (sharper exponent)
    let dead_zone = (1.0 - pr_norm).powi(7);
    score += dead_zone * (10.0 + 46.0 * progress);

    // Exact fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead chain bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual { score -= 32.0; }
            if after == 0 { score -= 60.0; }
            else if after <= 4 { score -= 42.0; }
            else if after <= 10 && next_item_size >= after { score -= 25.0; }
            if after as f64 > mean_residual * 2.0 { score += 25.0; }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tight-fit reward relative to item size
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.92 { score -= 50.0 * tight; }
        else if tight > 0.75 { score -= 20.0 * tight; }
        else { score -= 8.0 * tight; }
    }

    // Mean residual coupling: prefer tighter-than-mean bins
    score += 0.3 * (mean_residual - pr);

    // Open-bin pressure scaled by how empty the bin is
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation penalty, stronger late in stream
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);

    // New-bin candidate logic: attract only for large items with few fitting bins
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 10.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Last-chance consolidation: strongly favor sole fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // NEW: residual-sigma coupling — when bin residual is near the stream's
    // typical leftover, mildly penalize it (that leftover is likely to become
    // dead space); encourage bins whose leftover differs from the mean.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 3.0 {
            score += 6.0 * (3.0 - dev);
        }
    }

    // NEW: two-item exact-chain lookahead — reward bins where the next item
    // leaves a remainder exactly matching a plausible small follow-up fill.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 <= mean_residual * 0.4 && after > 0 {
            score -= 18.0;
        }
    }

    // NEW: late-stream conservatism — near the end, avoid creating any
    // leftover smaller than the next item (guaranteed dead space).
    if progress > 0.9 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0 * (1.0 - progress) * 10.0;
    }

    score
}

