    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= 0.8 * (bin_capacity as f64 - post_residual as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Pressure from number of open bins: prefer consolidating into existing bins.
    score += 0.9 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: if the next item can still fit in the post residual, reward it;
    // if not, penalize leaving a gap the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Slight preference for bins whose residual is already below average (closer to full).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
