    }

    // New empty bin should only win if existing bins are poor fits: penalize it.
    if bin_residual == bin_capacity {
        score += 25.0 + 1.5 * open_bins_count as f64;
    }

    // Late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress;

    score
}

