}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Tightness reward, non-linear, progress-coupled.
    score += pr_norm * (0.8 + 2.1 * progress * progress) * cap * 0.5;

    // Sharpened dead-zone avoidance.
    let dead_zone = (1.0 - pr_norm).powi(6);
    score += dead_zone * (10.0 + 42.0 * progress);

    // Exact / near-exact fit bonuses.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 260.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // Lookahead chain logic.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if (next_item_size as u64) < (post_residual as u64) {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 310.0 } else if fill > 0.6 { 195.0 } else { 130.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
                score -= 32.0;
            }
            if after == 0 {
                score -= 60.0;
            } else if after <= 4 {
                score -= 42.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 25.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 25.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let near_miss_scale = if gap <= 8.0 { 0.5 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Dead-space penalty: residual too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_ratio = (next_item_size as f64 - pr) / cap;
        score += 20.0 * waste_ratio * cap * (0.5 + progress);
    }

    // Tightness relative to the placed item.
    if post_residual > 0 && post_residual >= item_size {
        let tight_i = item_size as f64 / pr;
        if tight_i > 0.92 {
            score -= 50.0 * tight_i;
        } else if tight_i > 0.75 {
            score -= 20.0 * tight_i;
        } else {
            score -= 8.0 * tight_i;
        }
    }

    // Last-chance consolidation: stronger than parent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0 + 30.0 * openness * (1.0 - progress);
        }
        score -= 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // Penalize opening new bins when many open bins already fit the item.
        if fitting_bins_count >= 2 {
            score += 18.0 * (fitting_bins_count as f64).min(4.0);
        }
        // NEW: discourage fresh bins when the lookahead item can still use mean residual space.
        if next_item_size > 0 && (next_item_size as f64) < mean_residual {
            score += 12.0;
        }
    }

    // Spread / fragmentation penalties.
    score += (open_bins_count as f64).ln() * 1.5 * progress;
    score += 0.5 * open_bins_count as f64 * pr_norm;
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);
    score += 0.3 * (mean_residual - pr);

    // NEW: mid-size waste guard — penalize leaving residuals just above small-item sizes.
    if post_residual > 0 && post_residual <= 12 {
        score -= 18.0 * (1.0 - pr / 13.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = post_residual as f64 - next_item_size as f64;
        // exact match is a jackpot
        score -= 30.0 * (1.0 - gap / cap);
        if gap == 0.0 {
            score -= 20.0;
        }
        // chain potential: residual after the hypothetical next placement
        let chain_residual = gap;
        if chain_residual >= 10.0 {
            score -= 5.0 * (chain_residual / cap);
        }
    } else if next_item_size > 0 {
        // next item cannot follow here -> dead space risk, penalize small unusable residuals
        score += 15.0 * (1.0 - post_residual as f64 / cap);
    }

    // Penalize residuals that are too small to ever be useful (below min item size)
    if post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins with residual below mean residual (tight packing) mildly
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: discourage opening a new bin unless it's early or all fits are terrible
    if bin_residual == bin_capacity {
        let penalty = 45.0 + 55.0 * progress;
        score += penalty;
        // exception: if the item is large relative to capacity, opening fresh is fine
        if item_size as f64 > 0.7 * cap {
            score -= 35.0;
        }
    }

    // Slight preference for fuller bins overall
    score -= 10.0 * (1.0 - bin_residual as f64 / cap);

    score
}

