}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) + norm_pr * (1.0 - progress) * (1.0 - progress);

    let mut score = 2.0 * poly * cap;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    score -= (cap - pr) * (0.5 + 1.5 * progress * progress);

    // Lookahead: reward bins whose leftover can host the next item, scaled by progress.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / cap) * (0.3 + 0.7 * progress);
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item.
        score += 6.0 * norm_pr * (0.5 + progress);
    }

    // Penalize spreading across many open bins; encourage closing bins.
    score += 0.4 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    score += 0.3 * (pr - mean_residual).abs() * (1.0 - progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless it enables a near-perfect future fit.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
        if next_item_size > 0 {
            let perfect = (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs();
            score -= 25.0 * (1.0 - perfect / cap) * (perfect <= 10.0) as i32 as f64;
        }
    }

    score
}

