    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation penalty, stronger late
    let frag = pr / (pr + item_size as f64);
    score += 12.0 * frag * frag * (0.5 + progress);

    // NEW: two-step lookahead — reward bins whose residual after this item
    // can still absorb the next item AND leave a near-zero remainder.
    if next_item_size > 0 && post_residual > 0 && next_item_size < post_residual {
        let after2 = post_residual - next_item_size;
        if after2 > 0 && after2 < item_size {
