            // strong consolidation signal, amplified by progress
            score -= 45.0 * (1.0 - after2 as f64 / item_size as f64) * (0.6 + progress);
        }
    }

    // NEW: residual variance damping — avoid bins whose residual is far
    // below the mean (over-tightening leaves unusable slivers elsewhere).
    let dev = (pr - mean_residual).abs();
