        score += 3.0;
    } else if post_residual >= 80 {
        // huge leftover: bin was barely used; slightly penalize vs tight fits
        score += 2.0;
    }

    // --- Lookahead coupling (k=2): can next_item_size exactly fill the post_residual? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
