    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Tightness reward, non-linear, progress-coupled
    score -= 40.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.7 + 0.6 * progress);

    // Exact / near-exact fits: overwhelming rewards
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 4 {
        score -= 220.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 12.0 + 22.0 * waste + 28.0 * waste * waste;
    }

    // Dead-space avoidance with sharpened dead zone
    let dead_zone = (1.0 - pr_norm).powi(5);
    score += dead_zone * (8.0 + 35.0 * progress);

    // Lookahead chain logic
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 550.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 260.0 } else if fill > 0.6 { 160.0 } else { 100.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after == 0 { score -= 55.0; }
            else if after <= 4 { score -= 38.0; }
            else if after as f64 <= mean_residual { score -= 26.0; }
            if after as f64 > mean_residual * 2.0 { score += 20.0; }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let scale = if gap <= 8.0 { 0.5 } else { 0.3 };
            score += scale * gap;
        }
    }

    // Tight-fit reward relative to item size
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / pr;
        if tight > 0.92 { score -= 45.0 * tight; }
        else if tight > 0.75 { score -= 18.0 * tight; }
        else { score -= 7.0 * tight; }
    }

    // Mean residual coupling: prefer tighter-than-mean bins
    score += 0.25 * (mean_residual - pr);

    // Fragmentation penalty, stronger late
    let frag = pr / (pr + item_size as f64);
    score += 10.0 * frag * frag * (0.5 + progress);

    // New-bin candidate: gated opening
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 55.0 * (1.0 - cap_frac) + 22.0 * (1.0 - progress);
        } else {
            score += 14.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
