    score += tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins can fit, unless residuals are wasteful.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are only chosen when fitting bins look bad.
        score += 55.0;
        // Late in the stream, opening a fresh bin is more acceptable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 20.0;
        // If few fitting bins and they leave dead space, new bin becomes attractive.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // If mean residual is small (bins nearly full), a new bin is reasonable.
        score += (mean_residual - 30.0) * 0.5;
    } else {
        // Reward using existing bins, more so when many bins are open (consolidation).
        score -= 8.0;
        score -= (open_bins_count.min(50) as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid wasting its space.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
        // Especially if the leftover would be dead space anyway.
        if post_residual < 10 {
            score -= 20.0;
        }
    }

    // Lookahead: check if next item can fit into post_residual (chaining bonus).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Great: next item chains into this bin.
            let slack_after_next = post_residual - next_item_size;
            score -= 15.0 + (10 - slack_after_next.min(10)) as f64;
        } else {
            // Dead space for the next item: penalize proportionally to mismatch.
            let waste = next_item_size - post_residual;
            score += (waste.min(50) as f64) * 0.6;
        }
        // If next item is large, prefer bins that will still be useful.
        if next_item_size >= 60 && post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Mild preference for bins with residual close to mean (keep distribution balanced).
    score += ((bin_residual as f64 - mean_residual) / 50.0).abs() * 3.0;

    // Time-horizon scaling: early stream, be conservative with new bins.
    let early = (1.0 - (step_index as f64 / (total_items.max(1) as f64))) * 5.0;
    if is_new_bin {
        score += early;
    }

    score
}

