    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 3.0 * pressure;
    } else {
        // New-bin candidate: penalize opening a new bin when open bins exist
        // and fit well; allow it when open bins are nearly full (high mean fill).
        score += 15.0 + 2.0 * pressure;
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
        if mean_fill > 0.7 {
            score -= 20.0 * (mean_fill - 0.7);
        }
    }

    // Lookahead coupling: if next item fits into this bin's post_residual,
    // reward chaining placements.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If post_residual is smaller than next item but nonzero, mild penalty
    else if next_item_size > 0 && post_residual > 0 {
        score += 0.1 * (next_item_size - post_residual) as f64;
    }

    // Early stream: slightly favor consolidation into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    // Distance from mean residual: prefer bins deviating below mean (filling emptier bins)
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

