pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Harmonic class: partition post_residual into capacity/8 bands via integer division
    let band = post_residual / (bin_capacity / 8);
    let band_center = (band as f64 + 0.5) * (bin_capacity as f64 / 8.0);
    // Penalize residuals far from useful "small item" sizes (1..=25 usable zone)
    let usable = if post_residual >= 1 && post_residual <= 25 { 1.0 } else { 0.0 };
    score -= 12.0 * usable;
    score += 0.15 * (band_center - post_residual as f64).abs();

    // Modulo arithmetic on post_residual: residues near 0 (perfect fit multiples) rewarded
    let rem = post_residual % (bin_capacity / 4);
    score -= 8.0 * (1.0 - (rem as f64 / (bin_capacity as f64 / 4.0)).abs());

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space unless next item pairs with a class boundary
            score += 6.0;
            if post_residual % (bin_capacity / 5) == 0 { score -= 4.0; }
        }
    } else {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: usually worse than a decent fit, but attractive when
    // the item is large and no open bin offers a good home.
    if bin_residual == bin_capacity {
        let base = 45.0
            + 20.0 * (1.0 - fill_frac)
            + 0.5 * mean_residual;
        // If this bin is the only fitter and residual would be small, opening is fine
        let escape = if fitting_bins_count <= 1 && post_residual <= bin_capacity / 10 { -30.0 } else { 0.0 };
        score = score.max(base + escape);
    }

