    }

    // MUTATION: two-step lookahead synergy — reward bins where item + next item
    // nearly exhaust the bin, combining fine-grained residual fitting with lookahead
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = pr - next_item_size as f64;
