pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: residuals divisible by 10 (and by 25) are
    // "reusable classes" for typical item sizes; odd/prime-ish leftovers are dead space.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0;
            if pr % 25 == 0 { score -= 6.0; }
        }
        if pr % 7 == 0 || pr % 13 == 0 { score += 5.0; }
        // Small leftovers (<10) are near-perfect fits
        if pr < 10 { score -= 25.0; }
        // Large leftovers that no plausible item can use well
        if pr > 60 { score += 8.0; }
    }

    // Integer-division thresholds: leftover in [next_item_size, next_item_size+9]
    // means the lookahead item fits perfectly next.
    if next_item_size > 0 && pr >= next_item_size {
        let slack = pr - next_item_size;
        if slack <= 5 {
            score -= 20.0;
        } else if slack <= 15 {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Penalize if leftover is just below the next item (unusable sliver)
        if pr < next_item_size && next_item_size - pr <= 5 {
            score += 10.0;
        }
    } else if next_item_size == 0 {
        // Last item: just minimize leftover
        score -= 5.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits (post_residual already does),
        // slight penalty to spread load when many bins fit.
        score += 2.0;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    // to keep a spread of residuals for future items.
    score += 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well
    // (residual == capacity) or when open bins are all nearly full.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so existing bins usually win; relax when bins are crowded
        // and mean residual is small (little room anywhere).
        let mut new_bin_score = 45.0 - 0.8 * crowd - 0.05 * mean_residual + 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            // Next item is big: keeping current bins' space may matter less
            new_bin_score -= 5.0;
        }
        // If this bin is the only fitting option, opening new is fine
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        score = score.min(new_bin_score);
    }

    // Mild tie-break noise via deterministic harmonic mixing
    score += ((step_index as u64).wrapping_mul(2654435761) % 7) as f64 * 0.01;

    score
}

