        score -= 120.0;
    }

    // Penalize opening new bins when good open candidates exist late in the stream.
    if bin_residual == bin_capacity {
        let base_penalty = 90.0 + 60.0 * progress;
        // Discourage new bin if some open bin leaves a tight fit.
        if post_residual >= 0 && fitting_bins_count > 0 {
            score += base_penalty;
        } else {
            score += base_penalty * 0.5;
        }
        // Early stream: new bins are cheap; late stream: consolidation matters.
        if open_bins_count > 8 && progress > 0.5 {
            score += 40.0;
        }
    }

    // Mild preference for bins with tighter residuals (best-fit flavor).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64).signum() * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small residuals are dead space unless they match the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            // Bonus proportional to how tightly the next item would fit.
            score -= 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else if next_item_size > 0 {
            // Dead space relative to the lookahead item: penalize.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // Early in the stream, keeping bins consolidated matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
        // If many bins are open and mean residual is fragmented, opening fresh is less bad.
        score -= 0.5 * open_bins_count as f64;
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // Never open a new bin when an exact fit exists elsewhere is handled by
        // the huge exact-fit bonus above.
    }

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    score += 0.1 * (bin_residual as f64 - item_size as f64).abs();

    // Slight preference for more-filled bins among ties.
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_post = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (small post_residual). Late: residual is less costly,
    // so reward using existing bins more strongly.
    let quad = norm_post * norm_post;
    let progress_poly = progress * progress;
    score += 8.0 * quad * (1.0 - progress_poly);
    score -= 12.0 * progress_poly * (1.0 - quad) * (1.0 - quad);

    // Dead-space penalty: residuals too small for typical future items are worthless.
    let dead = (pr - next_item_size as f64).max(0.0) / cap;
    score += 5.0 * dead * dead;

    // Perfect-fit reward (smooth cubic falloff around zero residual).
    score -= 10.0 * (-norm_post * 12.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when other bins could fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 15.0 * (1.0 - progress_poly) + 10.0 * (fitting_bins_count.max(1) as f64).ln();
        // Late in the stream with a large next item, a fresh bin is more acceptable.
        if next_item_size as f64 > 0.6 * cap {
            score -= 18.0 * progress_poly;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * norm_post;

    // Lookahead: if the next item exactly fits the resulting residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
    }

    // Smooth deviation from mean residual: avoid leaving bins wildly unbalanced.
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10 and mod 20
    let class10 = (post_residual % 10) as f64;
    let class20 = (post_residual % 20) as f64;
    // Dead space that can never be filled well: residues far from 0 mod 10
    score += 0.6 * class10 + 0.4 * class20;

    // Integer-division thresholds: post_residual in "dead zone" (1..=9) is nearly useless
    let dead_zone = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += 8.0 * dead_zone;

    // Reward tight fits (post_residual near zero)
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: does next item fit into the post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect harmonic match: next item exactly fills remaining space
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 - 0.15 * gap;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > post_residual {
        // next item can't use this residual: residual likely wasted
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // Favor using bins with small residual relative to mean (compact bins)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 4.0;
        // but if item is large, new bin is fine
        if item_size >= 50 {
            score -= 6.0;
        }
        // discourage new bins when many bins are open with slack
        if mean_residual > item_size as f64 {
            score += 3.0;
        }
    }

    // Late in the stream, be greedy about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - (post_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible future item are pure waste — penalize them heavily.
    let min_useful = 8u32; // smallest expected item size
    if post_residual < min_useful {
        score += 40.0 + 2.0 * (min_useful - post_residual) as f64;
    } else {
        // Smooth "tightness" reward: perfect fills get a bonus, but a residual
        // that exactly matches the lookahead item is ideal.
        let tight = (post_residual as f64) / (bin_capacity as f64);
        score -= 12.0 * (1.0 - tight) * (1.0 - tight);
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0; // residual too small for the known next item
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when fit quality
    // is mediocre; encourage using existing bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Mean-residual anchoring: prefer bins whose residual is near the fleet mean
    // (keeps residuals balanced and reusable).
    score += 0.10 * ((post_residual as f64) - mean_residual).abs();

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 1
            || (fitting_bins_count == 1 && post_residual >= min_useful);
        if good_fit_exists {
            score += 30.0;
        } else {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * chain_tightness;
    }
    // Penalize post residuals that are dead space: too small for any plausible next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // unusable sliver
    }

    // Relative-to-mean residual: prefer bins already below mean residual (consolidating).
    score -= 5.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Allow new bin early in stream or when few bins open (cheap diversification).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress) * (1.0 / (1.0 + open_bins_count as f64));
        // If lookahead chains perfectly into a fresh bin, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * (bin_capacity as f64) * 0.6;

    // Lookahead: reward if next item fits into the post residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * next_item_size as f64;
    }
    // Penalize leaving a residual that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by how many
    // open bins already exist and how much slack they collectively hold.
    if bin_residual == bin_capacity {
        let slack = (mean_residual - post_residual as f64).max(0.0);
        score += 18.0 + 0.8 * open_bins_count as f64 + 0.05 * slack;
        // Early in the stream, opening bins is cheaper; late, prefer packing.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        // Prefer bins whose residual deviates favorably from the mean
        // (pack into emptier bins to consolidate slack elsewhere).
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: residual value changes over stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) - prn * progress;
    score += 8.0 * poly;

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 && nx > pr {
            score += (nx - pr) * 0.5 * (0.5 + progress);
        } else if nx <= pr {
            score -= 2.0 * (1.0 - prn);
        }
    }

    // Reward near-perfect fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    // Encourage balancing residuals toward mean early on
    score += 0.3 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes modulo 10.
    // Residues 1..9 (non-multiples of 10) create "dead space" that only tiny
    // future items can fill; penalize them super-linearly.
    let r = post_residual % 10;
    if post_residual > 0 {
        let dead = match r {
            0 => 0.0,
            1..=3 => 6.0,
            4..=6 => 3.0,
            7..=9 => 1.5,
            _ => 0.0,
        };
        score += dead * (post_residual as f64 / 10.0).sqrt();
    }
    // Perfect zero residual is ideal: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Lookahead coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // harmonic class match: both in same decade class -> likely co-fill
            let cls_a = next_item_size / 10;
            let cls_b = post_residual / 10;
            if cls_a == cls_b {
                score -= 8.0;
            }
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // next item cannot fit here: leftover must survive another round
            score += 3.0 * (post_residual as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 40.0;
        // large items (>= half capacity) are fine to start fresh
        if item_size * 2 >= bin_capacity {
            score -= 25.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // many open bins with slack: avoid opening yet another
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        // Prefer bins whose residual is close to item (best-fit sharpening)
        let gap = (bin_residual - item_size) as f64;
        score += 0.05 * gap;
        // prefer bins with small residual relative to fleet mean (near-full bins)
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Slight penalty when too many bins are open: encourage filling existing ones.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
