pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus for leaving no dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize tiny dead space less than medium dead space (non-linear).
        let pr = post_residual as f64;
        if pr < 10.0 {
            score -= 50.0; // near-perfect fit is excellent
        } else {
            // Dead space relative to capacity: quadratic penalty grows fast.
            score += (pr * pr) / (bin_capacity as f64);
        }
    }

    // Aggressive 2-step lookahead: if the NEXT item fits exactly into the
    // post-residual, this bin chains perfectly — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportionally to how snug the chain is.
            let chain_left = post_residual - next_item_size;
            score -= 300.0 - (chain_left as f64) * 2.0;
        } else {
            // Next item will NOT fit in this bin: mild penalty, scaled by
            // how badly it misses (potential wasted capacity reservation).
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 1.5;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer filling bins that are already low (consolidating waste).
    let residual_gap = (bin_residual as f64) - mean_residual;
    score += residual_gap * 0.8;

    // Last-chance bin: if this is the only bin that fits the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin, discounted for large items.
        score += 120.0 - 90.0 * fit_ratio;
