        if fitting_bins_count > 1 {
            score += 150.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
        // If next item is small, a fresh big residual is useful for it.
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 100.0;
        }
    }

    // Slight preference for denser packing when many bins are open.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

