    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);
    score += 0.3 * (mean_residual - pr);

    // Penalize leaving residuals that no typical item can use
    if post_residual > 0 {
        let usable = (post_residual as f64 / mean_residual.max(1.0)).min(2.0);
        if usable < 1.0 {
            score += 18.0 * (1.0 - usable) * (0.5 + progress);
        }
    }

    // Reward bins whose post-residual matches next item within a small window
    if next_item_size > 0 && post_residual >= next_item_size {
        let d = (post_residual - next_item_size) as f64;
        if d <= 12.0 {
            score -= 20.0 * (1.0 - d / 12.0) * (0.6 + 0.4 * progress);
        }
    }

    // Reward keeping post-residual aligned with mean residual (harmonized leftovers)
    if post_residual > 0 && mean_residual > 0.0 {
        let align = 1.0 - ((pr - mean_residual).abs() / cap).min(1.0);
        score -= 6.0 * align * (0.4 + 0.6 * progress);
    }

    // Late-stream consolidation — prefer filling nearly-full bins more aggressively
    if progress > 0.7 && post_residual > 0 {
        let squeeze = 1.0 - pr_norm;
        score -= 14.0 * squeeze * squeeze * (progress - 0.7) / 0.3;
    }

    // Two-step lookahead synergy — reward bins where item + next item nearly exhaust the bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = pr - next_item_size as f64;
        let two_fill = (item_size as f64 + next_item_size as f64) / (bin_residual as f64);
        if two_fill > 0.97 {
            score -= 90.0 * (two_fill - 0.97) / 0.03;
        } else if after2 <= 6.0 {
            score -= 35.0 * (1.0 - after2 / 6.0);
        }
        // Penalize residuals that can fit neither the next item nor a small item
        if after2 > 0.0 && after2 < 8.0 {
            score += 10.0 * (8.0 - after2) / 8.0 * (0.5 + progress);
        }
    }

    // Mid-stream tightening of fragmentation tolerance
    if progress > 0.35 && progress <= 0.7 && post_residual > 0 {
        let squeeze = 1.0 - pr_norm;
        score -= 8.0 * squeeze * squeeze * (progress - 0.35) / 0.35;
    }

    // MUTATION: residual-shape targeting — reward leaving residuals that are
    // multiples of a "harmonic" chunk so future mid-size items tile them cleanly
    if post_residual > 0 && mean_residual > 1.0 {
        let ratio = pr / mean_residual;
        let nearest = ratio.round();
        let dev = (ratio - nearest).abs();
        if nearest >= 1.0 && dev < 0.12 {
            score -= 22.0 * (1.0 - dev / 0.12) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION: pair-completion lookahead — strongly prefer bins where the next
    // item's leftover can still host a third small item (triple-fill chains)
    if next_item_size > 0 && post_residual > next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after >= 1.0 && after <= mean_residual * 0.6 {
            score -= 18.0 * (1.0 - after / (mean_residual * 0.6)) * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (small post_residual), but avoid perfect-fill
    // over-fragmentation when the leftover could still serve a future item.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: reward residual that matches the next item size well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as u32 - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Penalize leaving a residual that can't host the next item
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize it mildly, more when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 15.0 * progress + open_bins_count as f64;
    } else {
        // Slight preference for reusing bins that are already relatively empty
        // (consolidation): keeps emptier bins available for future items.
        let rel = bin_residual as f64 / bin_capacity as f64;
        score -= 4.0 * rel;
        // Penalize bins far from the mean residual to spread load evenly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Dead-space guard: residuals below the minimum item size are wasted.
    if post_residual < 1 {
        score += 100.0;
    } else if post_residual < 10 {
        score += 8.0;
    }

    // Early stream: be conservative, keep bins balanced; late stream: greedy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

