    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Tightness: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Exact-ish fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: penalize if next item would fit in post_residual (reserve space),
    // reward if post_residual is unusable dead space for the next item.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score += 0.35 * (next_item_size as f64) * (0.5 + progress);
        } else {
            score -= 6.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly early, more when open bins have poor fit options.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.15 * open_bins_count as f64 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins below mean residual (denser bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 4.0 * dev;

    // Late-stream consolidation pressure.
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

