pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit preference with nonlinear dead-space penalty
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fill_frac = 1.0 - pr / cap;
    score -= 12.0 * fill_frac * fill_frac;

    // Harmonic class of post_residual: residues that create "usable" slots
    // (post_residual divisible into common small sizes) are rewarded.
    if post_residual > 0 {
        let mut bonus = 0.0;
        for s in [10u32, 20, 25, 30, 40, 50].iter() {
            if post_residual % s == 0 || post_residual >= *s {
                bonus += 2.0;
            }
        }
        // Perfect divisibility is a strong reward (slot reusable by many sizes)
        if post_residual % 10 == 0 {
            bonus += 6.0;
        }
        if post_residual % 25 == 0 {
            bonus += 4.0;
        }
        score -= bonus;
    } else {
        // Perfect closure: bin exactly filled — best possible outcome
        score -= 30.0;
    }

    // Integer-division threshold: tiny leftovers (< 10) are dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling (k=2): reward if next item fits post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // extra reward when the pair closes the bin exactly
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; mildly penalize wasting this slot
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // existing fits are terrible (huge post_residual waste elsewhere).
    if bin_residual == bin_capacity {
        score += 25.0;
        // as stream progresses, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // if many bins are open, discourage spreading further
        score += 0.5 * open_bins_count as f64;
        // but if no open bin fits well (mean residual small relative to item),
        // opening new bin becomes attractive
        if mean_residual < item_size as f64 * 0.5 {
            score -= 35.0;
        }
    }

    // Mild tie-breaker: prefer bins with residual far from mean (better packing diversity)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Small progress-adaptive tightness weight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 + progress) * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the smallest
    // plausible item are pure waste — penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that cannot fit the lookahead item either (double dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual is well above the item (big-gap bins absorb
    // the item without creating a new tiny gap) only mildly; prefer tight fits.
    let gap_ratio = post_residual as f64 / bin_capacity as f64;
    score += gap_ratio * 20.0;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.4 + 0.6 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (pristine bin): make it moderately attractive only
    // when the current bin would leave a large unusable remainder or when
    // the item is large and no tight option exists.
    if bin_residual == bin_capacity {
        let wasted = (bin_capacity - item_size) as f64;
        let new_bin_penalty = 45.0 + wasted * 0.5;
        // New bins become more acceptable late in the stream.
        score += new_bin_penalty * (1.0 - 0.4 * progress);
        // If the lookahead item is large, a fresh bin is useful.
        if next_item_size > 0 && next_item_size >= bin_residual - item_size {
            score -= 10.0;
        }
    }

    // Mild alignment with mean residual: prefer bins below the mean residual
    // (i.e., tighter bins) to consolidate small gaps.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

