    }

    // Last-chance consolidation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 32.0 + 22.0 * progress;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0 + 12.0 * openness * (1.0 - progress);
        }
        score -= 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 { score += 12.0; }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 32.0;
        }
        // Penalize opening new bins when open bins already fit
        if fitting_bins_count >= 2 {
            score += 20.0 * (fitting_bins_count as f64).min(4.0);
        }
    }

    // Spread / fragmentation penalties
    score += (open_bins_count as f64).ln() * 1.5 * progress;
    score += 0.5 * open_bins_count as f64 * pr_norm;
    let frag = if post_residual > 0 { pr / (pr + item_size as f64) } else { 0.0 };
    score += 12.0 * frag * frag * (0.5 + progress);
    score += 0.3 * (mean_residual - pr);

    // Penalize leaving residuals that no typical item can use
    if post_residual > 0 {
        let usable = (post_residual as f64 / mean_residual.max(1.0)).min(2.0);
        if usable < 1.0 {
            score += 18.0 * (1.0 - usable) * (0.5 + progress);
        }
    }

    // Reward bins whose post-residual matches next item within a small window
    if next_item_size > 0 && post_residual >= next_item_size {
        let d = (post_residual - next_item_size) as f64;
        if d <= 12.0 {
            score -= 22.0 * (1.0 - d / 12.0) * (0.6 + 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: penalize small post_residual non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness);

    // Penalize dead space that is too small for typical future items
    // (residuals below ~10 are nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect pair
