        } else {
            // next item won't fit here; slight penalty proportional to overflow
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is discouraged unless the item
    // fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its post_residual is large, so add a fixed
        // opening cost, softened late in the stream or when many bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 18.0 - 8.0 * progress;

        // If no open bin fits at all, opening is necessary -> reduce cost.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // If item is large, a fresh bin wastes less potential.
        score -= 0.1 * item_size as f64;
    } else {
        // Mild reward for using existing bins, stronger when many are open.
        score -= 2.0 + 0.3 * open_bins_count as f64;
    }

    // Global residual coupling: prefer bins below mean residual (packing
    // fuller bins keeps a pool of larger residuals available).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Time-horizon modulation: early in the stream, be conservative about
    // creating small residuals (long future ahead); later, accept them.
    let horizon = if total_items > 0 {
        1.0 - step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += horizon * 0.2 * post_residual as f64;

    score
}

