    // Prefer bins whose residual deviates below the mean (consolidate large gaps)
    let dev = mean_residual - pr;
    score += 0.3 * dev * (1.0 - progress);

    // Mild penalty for spreading across many bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    // New-bin candidate: keep it competitive only when residuals are all poor
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - progress) - 10.0 * progress * (mean_residual / cap - norm_pr).max(0.0);
    }

    score
}

