pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // fraction of capacity left

    // Integer-division thresholds on post_residual (harmonic classes of C/4).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class = post_residual / quarter; // 0..4 harmonic class

    // Penalize dead space non-linearly; small residuals are near-useless.
    match class {
        0 => score += 25.0,                    // residual < 25: dead space
        1 => score += 8.0,                     // 25..50: awkward
        2 => score += 0.0,                     // 50..75: decent
        _ => score -= 4.0,                     // >= 75: roomy
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes are reusable; penalize odd/unusable remainders.
    let m8 = post_residual % 8;
    if m8 != 0 {
        score += (8 - m8) as f64 * 0.5;
    }
    if post_residual % 10 == 0 {
        score -= 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Next item cannot use this residual: penalize leftover size relative to it.
            score += (next_item_size - post_residual).min(40) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.85;
        // Open new bin if item is large relative to mean residual (poor fits everywhere).
        if item_size as f64 > mean_residual + 10.0 {
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score = 0.0;
        }
    }

    // Mild tightness reward: prefer bins whose residual was small pre-placement.
    score += (bin_residual as f64 - post_f) * 0.0; // no-op placeholder for coupling clarity
    score -= (bin_capacity - bin_residual) as f64 * 0.05; // reward already-filled bins

    // Stream progression: later in stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * frac * (10.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Dead-zone shaping: penalize residuals that are likely unusable.
    let dead_zone = (1.0 - pr_norm).powi(7);
    score += dead_zone * (10.0 + 46.0 * progress);

    // Perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 280.0;
    } else if post_residual < item_size {
        let waste = (item_size - post_residual) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    }

    // --- Lookahead: strong chain bonus when the next item continues this bin ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 680.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 330.0 } else if fill > 0.6 { 200.0 } else { 125.0 };
            score -= chain_bonus * fill;
            let after = post_residual - next_item_size;
            if after as f64 <= mean_residual {
