        }
    }

    // Tightness reward when the item fills most of the bin.
    if post_residual > 0 && post_residual >= item_size {
        let tight = item_size as f64 / pr;
        if tight > 0.92 {
            score -= 55.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Balance against mean residual.
    score += 0.3 * (mean_residual - pr);
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Fragmentation penalty grows with progress.
    let frag = pr / (pr + item_size as f64);
    score += 12.0 * frag * frag * (0.5 + progress);

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 12.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 32.0;
        }
        if item_size as f64 >= 0.85 * cap {
            score -= 40.0 * (item_size as f64 / cap - 0.85);
        }
    }

    // Last-chance logic.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 32.0 + 22.0 * progress;
    }

    // Near-miss dead zone: residual slightly smaller than next item is wasted.
    if post_residual > 0 && post_residual < 12 && next_item_size > post_residual && (next_item_size - post_residual) <= 4 {
        score += 18.0;
    }

    // Mutation: harmonic alignment bonus for multiples of 10 with progress modulation.
    if item_size % 10 == 0 && post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0 * (1.0 - 0.5 * progress);
    }

    // Mutation: prefer bins whose residual is close to next_item_size even if not exact.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / pr;
        score -= 20.0 * snug * snug;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
