    // Coupling with mean residual: prefer bins whose post-residual tracks the mean.
    score += 0.3 * (pr - mean_residual).abs();

    // Lookahead: if next item fits the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
