    // --- Global pressure: many open bins with high mean residual -> consolidate ---
    if open_bins_count > 4 && mean_residual > 30.0 {
        score += (mean_residual - post as f64).abs() * 0.1;
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    let post = post_residual;
    let class = post / 10;
    let rem = post % 10;

    // Harmonic classification of the leftover
    if post == 0 {
        score -= 1000.0;
    } else if post <= 3 {
        score -= 280.0;
    } else if post <= 10 {
        score += 25.0 + (10 - post) as f64;
    } else if post < item_size {
        let waste = (item_size - post) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    } else {
        let harmonic_bonus = if rem == 0 {
            40.0 + class as f64 * 3.0
        } else if rem <= 3 {
            20.0
        } else {
            -5.0
        };
        score -= harmonic_bonus;
    }

    // Dead-zone penalty: strongly punish near-full leftovers late in the stream
    let dead_zone = (1.0 - pr_norm).powi(7);
    score += dead_zone * (10.0 + 46.0 * progress);

    // Tightness coupling
    if post > 0 && post >= item_size {
        let tight = item_size as f64 / pr;
        if tight > 0.92 {
            score -= 55.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Lookahead: chain with next item
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 680.0;
        } else if next_item_size < post {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 330.0 } else if fill > 0.6 { 200.0 } else { 125.0 };
            score -= chain_bonus * fill;
            let after = post - next_item_size;
            if after as f64 <= mean_residual {
                score -= 36.0;
            }
            if after == 0 {
                score -= 65.0;
            } else if after <= 4 {
                score -= 45.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 28.0;
            }
            if after as f64 > mean_residual * 2.0 {
                score += 28.0;
            }
        } else {
            let gap = (next_item_size - post) as f64;
            let near_miss_scale = if gap <= 6.0 { 0.55 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Last-chance logic
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 32.0 + 22.0 * progress;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score = 100.0 + 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score = 100.0 + 15.0;
        }
        if open_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 0 {
            score -= 150.0;
        } else {
            let frag = (mean_residual / cap).clamp(0.0, 1.0);
            score -= frag * 120.0;
            score += progress * 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if item_size as f64 >= 0.85 * cap {
            score -= 40.0 * (item_size as f64 / cap - 0.85);
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 32.0;
        }
        if fitting_bins_count > 2 {
            score += 12.0;
        }
    } else {
        if fitting_bins_count > 1 {
            score += fitting_bins_count as f64 * 0.5;
        }
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
        let frag = pr / (pr + item_size as f64);
        score += 12.0 * frag * frag * (0.5 + progress);
    }

    // Progress modulation
    score += (1.0 - progress) * pr * 0.15;
    score -= progress * (post == 0) as i32 as f64 * 50.0;

    // Harmonic divisor coupling
    if item_size % 10 == 0 && post % 10 == 0 && post > 0 {
        score -= 10.0;
    }

    // Mean-residual balancing term
    score += 0.3 * (mean_residual - pr);

    // Near-miss residual trap: leftover just below next item wastes space
    if post > 0 && post < 12 && next_item_size > post && (next_item_size - post) <= 4 {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual is "dead" if it's too small to hold even the smallest plausible item (<= 10)
    // or too small to hold the next item when that would have been a perfect fit.
    if post_residual < 10 {
        score += 60.0; // tiny unusable sliver — severe penalty
    } else if post_residual < item_size.min(20) {
        // gap smaller than the current item: likely wasted unless next item fits
        if next_item_size == 0 || post_residual < next_item_size {
            score += 25.0;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead coupling: reward residuals that exactly fit the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // keep room for the next item if possible
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize spreading); with few bins, be more permissive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bins have bad fits
    // (large post_residual relative to mean residual) or few fitting bins.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score = 20.0 + 70.0 * bad_fit * scarcity - 30.0 * pressure.min(2.0);
    }

    // Mild stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a post_residual that
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item: heavy reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Penalize gap between post_residual and next item size,
            // scaled by how large the next item is (big next items matter more).
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            score += gap * (0.5 + 1.5 * next_frac);
        }
        // If the next item also fits here after this placement, extra reward.
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: prefer minimal post_residual (perfect fit).
        score += 0.0;
    }

    // Tightness reward: smaller waste relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Penalize creating unusable dead space (too small for the smallest item).
    if post_residual < item_size.min(10).max(1) {
        score += 5.0;
    }

    // Compare against the mean residual of open bins: placing in a bin whose
    // residual is below average (a "cramped" bin) is desirable to compact bins.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 3.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 3.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has no lookahead synergy yet.
    // Prefer it only when it gives a great base residual for the next item
    // or when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: slightly penalized so good fits in open bins win,
        // but becomes attractive when post_residual would be small relative
        // to the next item.
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins: discourage opening yet another one.
        score += 0.5 * open_bins_count as f64;
    }

    score
}

