    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual;
    let pr = post as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.55 * pr_norm * pr_norm);

    // Progress-scaled residual pressure (borrowed from best)
    score += pr_norm * (0.8 + 2.4 * progress * progress) * cap * 0.5;
    let dead_zone = (1.0 - pr_norm).powi(7);
    score += dead_zone * (10.0 + 46.0 * progress);

    // Harmonic class of post residual
    let class = post / 10;
    let rem = post % 10;

    if post == 0 {
        score -= 1000.0;
    } else if post <= 3 {
        score -= 280.0;
    } else if post < item_size {
        let waste = (item_size - post) as f64 / item_size as f64;
        score += 15.0 + 25.0 * waste + 32.0 * waste * waste;
    } else {
        let harmonic_bonus = if rem == 0 {
            40.0 + class as f64 * 3.0
        } else if rem <= 3 {
            20.0
        } else {
            -5.0
        };
        score -= harmonic_bonus;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 680.0;
        } else if next_item_size < post {
            let fill = next_item_size as f64 / pr;
            let chain_bonus = if fill > 0.8 { 330.0 } else if fill > 0.6 { 200.0 } else { 125.0 };
            score -= chain_bonus * fill;
            let after = post - next_item_size;
            if after == 0 {
                score -= 65.0;
            } else if after <= 4 {
                score -= 45.0;
            } else if after <= 10 && next_item_size >= after {
                score -= 28.0;
            }
            if after as f64 <= mean_residual {
                score -= 36.0;
            } else if after as f64 > mean_residual * 2.0 {
                score += 28.0;
            }
        } else {
            let gap = (next_item_size - post) as f64;
            let near_miss_scale = if gap <= 6.0 { 0.55 } else { 0.35 };
            score += near_miss_scale * gap;
        }
    }

    // Tightness of the current placement
    if post > 0 && post >= item_size {
        let tight = item_size as f64 / pr;
        if tight > 0.92 {
            score -= 55.0 * tight;
        } else if tight > 0.75 {
            score -= 20.0 * tight;
        } else {
            score -= 8.0 * tight;
        }
    }

    // Bin dies after this item: penalize if next item is large
    if next_item_size > 0 && post < next_item_size {
        score += (next_item_size - post) as f64 * 0.4;
    }

    // Last-chance logic
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 32.0 + 22.0 * progress;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let cap_frac = item_size as f64 / cap;
        if cap_frac > 0.7 {
            score += 62.0 * (1.0 - cap_frac) + 25.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        if open_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 {
            score -= 85.0;
        }
        if fitting_bins_count > 2 {
            score += 12.0;
        }
        if item_size as f64 > 0.9 * mean_residual && fitting_bins_count <= 2 {
            score -= 32.0;
        }
        if item_size as f64 >= 0.85 * cap {
            score -= 40.0 * (item_size as f64 / cap - 0.85);
        }
    } else {
        if fitting_bins_count > 1 {
            score += fitting_bins_count as f64 * 0.5;
        }
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Balance and fragmentation modulation
    score += 0.3 * (mean_residual - pr);
    score += 0.5 * open_bins_count as f64 * pr_norm;
    let frag = pr / (pr + item_size as f64);
    score += 12.0 * frag * frag * (0.5 + progress);

    // Progress modulation: keep flexibility early, close bins late
    score += (1.0 - progress) * pr * 0.15;
    score -= progress * (post == 0) as i32 as f64 * 50.0;

    // Near-miss dead-zone trap
    if post > 0 && post < 12 && next_item_size > post && (next_item_size - post) <= 4 {
        score += 18.0;
    }

    // Modulo coupling on harmonics
    if item_size % 10 == 0 && post % 10 == 0 && post > 0 {
        score -= 10.0;
    }

    score
}
